window.PK=window.PK||{};window.PK.peptides=[{"slug":"bpc-157","name":"BPC-157","synonyme":["Body Protection Compound 157","PL 14736"],"kategorie":"Regeneration","studienlage":"frühe klinische Studien","kurz":"Syntetyczny peptyd badany głównie w przedklinicznych modelach regeneracji tkanek.","kurz_en":"Syntetyczny peptyd badany głównie w przedklinicznych modelach regeneracji tkanek.","beschreibung":"BPC-157 to syntetyczny pentadekapeptyd, którego sekwencja pochodzi od białka ochronnego występującego w ludzkim soku żołądkowym. Należy do najczęściej badanych peptydów w badaniach nad regeneracją tkanek, z szeroką bazą badań na zwierzętach i ograniczoną liczbą małych badań na ludziach. Główne obszary badań obejmują ścięgna, więzadła, wyściółkę przewodu pokarmowego i gojenie ran.","beschreibung_en":"BPC-157 to syntetyczny pentadekapeptyd, którego sekwencja pochodzi od białka ochronnego występującego w ludzkim soku żołądkowym. Należy do najczęściej badanych peptydów w badaniach nad regeneracją tkanek, z szeroką bazą badań na zwierzętach i ograniczoną liczbą małych badań na ludziach. Główne obszary badań obejmują ścięgna, więzadła, wyściółkę przewodu pokarmowego i gojenie ran.","mechanismus":"W modelach przedklinicznych opisywano udział BPC-157 w angiogenezie poprzez szlak VEGFR2-AKT-eNOS, wspierającej tworzenie nowych naczyń krwionośnych w uszkodzonej tkance. Inne badane mechanizmy obejmują zwiększenie ekspresji receptorów hormonu wzrostu, modulację cytokin zapalnych i wspieranie migracji komórek poprzez szlak FAK-paksylina. Dokładne mechanizmy u ludzi nie zostały jeszcze w pełni ustalone.","mechanismus_en":"W modelach przedklinicznych opisywano udział BPC-157 w angiogenezie poprzez szlak VEGFR2-AKT-eNOS, wspierającej tworzenie nowych naczyń krwionośnych w uszkodzonej tkance. Inne badane mechanizmy obejmują zwiększenie ekspresji receptorów hormonu wzrostu, modulację cytokin zapalnych i wspieranie migracji komórek poprzez szlak FAK-paksylina. Dokładne mechanizmy u ludzi nie zostały jeszcze w pełni ustalone.","evidenz":[{"art":"przedkliniczne","kurz":"Przegląd systematyczny z 2025 roku obejmował literaturę z lat 1993-2024 i uwzględnił 35 przedklinicznych badań na zwierzętach dotyczących urazów mięśni, ścięgien, więzadeł i kości, które w większości opisywały pozytywne wyniki gojenia.","kurz_en":"Przegląd systematyczny z 2025 roku obejmował literaturę z lat 1993-2024 i uwzględnił 35 przedklinicznych badań na zwierzętach dotyczących urazów mięśni, ścięgien, więzadeł i kości, które w większości opisywały pozytywne wyniki gojenia.","quelle":"Vasireddi et al. 2025, HSS Journal, PMID 40756949"},{"art":"kliniczne","kurz":"Ten sam przegląd wskazał retrospektywną serię przypadków klinicznych, w której 7 z 12 pacjentów zgłosiło ulgę w bólu trwającą ponad sześć miesięcy po wstrzyknięciach dostawowych w kolano.","kurz_en":"Ten sam przegląd wskazał retrospektywną serię przypadków klinicznych, w której 7 z 12 pacjentów zgłosiło ulgę w bólu trwającą ponad sześć miesięcy po wstrzyknięciach dostawowych w kolano.","quelle":"Vasireddi et al. 2025, HSS Journal, PMID 40756949"},{"art":"kliniczne","kurz":"Retrospektywna analiza 16 pacjentów z bólem kolana opisała znaczną poprawę u 14 z nich w okresie obserwacji trwającym od sześciu do dwunastu miesięcy. Nie było grupy kontrolnej.","kurz_en":"Retrospektywna analiza 16 pacjentów z bólem kolana opisała znaczną poprawę u 14 z nich w okresie obserwacji trwającym od sześciu do dwunastu miesięcy. Nie było grupy kontrolnej.","quelle":"Lee & Padgett 2021, Altern Ther Health Med, PMID 34324435"}],"sicherheit":["W dużej mierze brakuje kontrolowanych placebo danych dotyczących bezpieczeństwa u ludzi; większość stwierdzeń o bezpieczeństwie opiera się na modelach zwierzęcych.","Na poziomie mechanistycznym dyskutuje się, że te same szlaki napędzające angiogenezę i proliferację komórek podczas gojenia teoretycznie mogłyby również wspierać istniejący wzrost guza. Powiązanie przyczynowo-skutkowe u ludzi nie zostało ustalone.","Dostępne małe badania na ludziach nie wykazały poważnych zdarzeń niepożądanych.","Produkty z niekontrolowanej produkcji niosą ryzyko zanieczyszczenia niezależne od samej cząsteczki."],"sicherheit_en":["W dużej mierze brakuje kontrolowanych placebo danych dotyczących bezpieczeństwa u ludzi; większość stwierdzeń o bezpieczeństwie opiera się na modelach zwierzęcych.","Na poziomie mechanistycznym dyskutuje się, że te same szlaki napędzające angiogenezę i proliferację komórek podczas gojenia teoretycznie mogłyby również wspierać istniejący wzrost guza. Powiązanie przyczynowo-skutkowe u ludzi nie zostało ustalone.","Dostępne małe badania na ludziach nie wykazały poważnych zdarzeń niepożądanych.","Produkty z niekontrolowanej produkcji niosą ryzyko zanieczyszczenia niezależne od samej cząsteczki."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"BPC-157 nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych i nie jest klasyfikowany jako produkt spożywczy. Jest sprzedawany wyłącznie jako substancja chemiczna do badań.","rechtsstatus_en":"BPC-157 nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych i nie jest klasyfikowany jako produkt spożywczy. Jest sprzedawany wyłącznie jako substancja chemiczna do badań.","typischeMg":[],"faq":[{"q":"Czy BPC-157 jest zatwierdzonym lekiem?","a":"Nie. BPC-157 nie jest zatwierdzony jako lek w UE ani w Stanach Zjednoczonych. Jest sprzedawany handlowo wyłącznie jako odczynnik badawczy do użytku laboratoryjnego, nie do użytku u ludzi.","q_en":"Czy BPC-157 jest zatwierdzonym lekiem?","a_en":"Nie. BPC-157 nie jest zatwierdzony jako lek w UE ani w Stanach Zjednoczonych. Jest sprzedawany handlowo wyłącznie jako odczynnik badawczy do użytku laboratoryjnego, nie do użytku u ludzi."},{"q":"Skąd pochodzi sekwencja BPC-157?","a":"Pochodzi od białka ochronnego występującego w ludzkim soku żołądkowym, od którego wywodzi się też nazwa Body Protection Compound.","q_en":"Skąd pochodzi sekwencja BPC-157?","a_en":"Pochodzi od białka ochronnego występującego w ludzkim soku żołądkowym, od którego wywodzi się też nazwa Body Protection Compound."},{"q":"Czy istnieją badania na ludziach dotyczące BPC-157?","a":"Istnieje kilka małych badań i serii przypadków z ograniczeniami metodologicznymi, ale brak dużych badań kontrolowanych placebo. Większość dowodów pochodzi z modeli zwierzęcych.","q_en":"Czy istnieją badania na ludziach dotyczące BPC-157?","a_en":"Istnieje kilka małych badań i serii przypadków z ograniczeniami metodologicznymi, ale brak dużych badań kontrolowanych placebo. Większość dowodów pochodzi z modeli zwierzęcych."}],"seo":{"title":"BPC-157: profil badawczy i dowody","title_en":"BPC-157: profil badawczy i dowody","description":"Przegląd BPC-157: pochodzenie, mechanizm, dowody i profil bezpieczeństwa, przedstawione rzeczowo w kontekście badawczym.","description_en":"Przegląd BPC-157: pochodzenie, mechanizm, dowody i profil bezpieczeństwa, przedstawione rzeczowo w kontekście badawczym."},"demo":false,"steckbrief":{"cas":"137525-51-0","molekulargewicht":"1419,5 g/mol","aminosaeuren":15,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":15,"quellen":["PubChem CID 9941957","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, standard handlowy)"},"verwandt":["tb-500","ghk-cu","thymosin-alpha-1","pentadeca-arginate"]},{"slug":"pentadeca-arginate","name":"Pentadeca Arginate (PDA)","synonyme":["PDA","Sól argininowa BPC-157"],"kategorie":"Regeneration","studienlage":"präklinisch","kurz":"Pentadekapeptyd o tej samej sekwencji aminokwasowej co BPC-157, oferowany jako sól argininowa w celu poprawy rozpuszczalności i stabilności.","kurz_en":"Pentadekapeptyd o tej samej sekwencji aminokwasowej co BPC-157, oferowany jako sól argininowa w celu poprawy rozpuszczalności i stabilności.","beschreibung":"Pentadeca Arginate, często skracany do PDA, ma tę samą 15-aminokwasową sekwencję co dobrze znany peptyd BPC-157. Różnica polega na przeciwjonie: zamiast soli octanowej sekwencja jest związana z argininą, co według dostawców poprawia rozpuszczalność i trwałość podczas przechowywania. Niezależne badania dotyczące tej konkretnej formy soli nie są jeszcze dostępne.","beschreibung_en":"Pentadeca Arginate, często skracany do PDA, ma tę samą 15-aminokwasową sekwencję co dobrze znany peptyd BPC-157. Różnica polega na przeciwjonie: zamiast soli octanowej sekwencja jest związana z argininą, co według dostawców poprawia rozpuszczalność i trwałość podczas przechowywania. Niezależne badania dotyczące tej konkretnej formy soli nie są jeszcze dostępne.","mechanismus":"Ponieważ sekwencja aminokwasowa jest identyczna jak w BPC-157, mechanizmy opisane w modelach przedklinicznych opierają się na tej samej podstawowej strukturze, w tym na udziale w angiogenezie poprzez szlak VEGFR2-AKT-eNOS i modulacji procesów zapalnych. Nie badano niezależnie, czy wiązanie argininy zmienia, przyspiesza lub spowalnia te efekty. Dokładne mechanizmy u ludzi pozostają niewyjaśnione nawet dla samej sekwencji macierzystej.","mechanismus_en":"Ponieważ sekwencja aminokwasowa jest identyczna jak w BPC-157, mechanizmy opisane w modelach przedklinicznych opierają się na tej samej podstawowej strukturze, w tym na udziale w angiogenezie poprzez szlak VEGFR2-AKT-eNOS i modulacji procesów zapalnych. Nie badano niezależnie, czy wiązanie argininy zmienia, przyspiesza lub spowalnia te efekty. Dokładne mechanizmy u ludzi pozostają niewyjaśnione nawet dla samej sekwencji macierzystej.","evidenz":[{"art":"przedkliniczne","kurz":"Ponieważ Pentadeca Arginate ma tę samą sekwencję co BPC-157, dostępne dowody opierają się na badaniach sekwencji macierzystej. Przegląd systematyczny z 2025 roku objął 35 przedklinicznych badań na zwierzętach dotyczących urazów mięśni, ścięgien, więzadeł i kości, które w większości opisywały pozytywne wyniki gojenia.","kurz_en":"Ponieważ Pentadeca Arginate ma tę samą sekwencję co BPC-157, dostępne dowody opierają się na badaniach sekwencji macierzystej. Przegląd systematyczny z 2025 roku objął 35 przedklinicznych badań na zwierzętach dotyczących urazów mięśni, ścięgien, więzadeł i kości, które w większości opisywały pozytywne wyniki gojenia.","quelle":"Vasireddi et al. 2025, HSS Journal, PMID 40756949"},{"art":"przedkliniczne","kurz":"Badanie komórkowe opisało aktywację i zwiększenie ekspresji VEGFR2, kluczowego receptora w tworzeniu naczyń krwionośnych, dla tej samej sekwencji, wraz ze zwiększonym tworzeniem rurek przez komórki śródbłonka w modelu laboratoryjnym.","kurz_en":"Badanie komórkowe opisało aktywację i zwiększenie ekspresji VEGFR2, kluczowego receptora w tworzeniu naczyń krwionośnych, dla tej samej sekwencji, wraz ze zwiększonym tworzeniem rurek przez komórki śródbłonka w modelu laboratoryjnym.","quelle":"Hsieh et al. 2016, Journal of Molecular Medicine, PMID 27847966"}],"sicherheit":["Nie istnieją niezależne dane dotyczące bezpieczeństwa samej soli argininowej, ukierunkowane wyszukiwanie literatury nie przyniosło wyników.","W dużej mierze brakuje kontrolowanych placebo danych z badań na ludziach dla sekwencji bazowej; większość stwierdzeń o bezpieczeństwie opiera się na modelach zwierzęcych.","Na poziomie mechanistycznym dyskutuje się, że te same szlaki napędzające angiogenezę i proliferację komórek podczas gojenia teoretycznie mogłyby również wspierać istniejący wzrost guza. Powiązanie przyczynowo-skutkowe u ludzi nie zostało ustalone.","Produkty z niekontrolowanej produkcji niosą ryzyko zanieczyszczenia niezależne od samej cząsteczki."],"sicherheit_en":["Nie istnieją niezależne dane dotyczące bezpieczeństwa samej soli argininowej, ukierunkowane wyszukiwanie literatury nie przyniosło wyników.","W dużej mierze brakuje kontrolowanych placebo danych z badań na ludziach dla sekwencji bazowej; większość stwierdzeń o bezpieczeństwie opiera się na modelach zwierzęcych.","Na poziomie mechanistycznym dyskutuje się, że te same szlaki napędzające angiogenezę i proliferację komórek podczas gojenia teoretycznie mogłyby również wspierać istniejący wzrost guza. Powiązanie przyczynowo-skutkowe u ludzi nie zostało ustalone.","Produkty z niekontrolowanej produkcji niosą ryzyko zanieczyszczenia niezależne od samej cząsteczki."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Pentadeca Arginate nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych i nie jest klasyfikowany jako produkt spożywczy. Jest sprzedawany wyłącznie jako substancja chemiczna do badań.","rechtsstatus_en":"Pentadeca Arginate nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych i nie jest klasyfikowany jako produkt spożywczy. Jest sprzedawany wyłącznie jako substancja chemiczna do badań.","typischeMg":[],"faq":[{"q":"Czy Pentadeca Arginate jest tym samym co BPC-157?","a":"Sekwencja aminokwasowa jest identyczna. Różnica polega na przeciwjonie: BPC-157 jest zazwyczaj oferowany jako sól octanowa, Pentadeca Arginate jako sól argininowa, która według dostawców poprawia rozpuszczalność.","q_en":"Czy Pentadeca Arginate jest tym samym co BPC-157?","a_en":"Sekwencja aminokwasowa jest identyczna. Różnica polega na przeciwjonie: BPC-157 jest zazwyczaj oferowany jako sól octanowa, Pentadeca Arginate jako sól argininowa, która według dostawców poprawia rozpuszczalność."},{"q":"Czy istnieją niezależne badania na temat soli argininy?","a":"Nie, ukierunkowane wyszukiwanie literatury nie znalazło niezależnych badań dotyczących samej soli argininowej. Dostępne dowody dotyczą sekwencji macierzystej BPC-157.","q_en":"Czy istnieją niezależne badania na temat soli argininy?","a_en":"Nie, ukierunkowane wyszukiwanie literatury nie znalazło niezależnych badań dotyczących samej soli argininowej. Dostępne dowody dotyczą sekwencji macierzystej BPC-157."},{"q":"Czy Pentadeca Arginate jest zatwierdzonym lekiem?","a":"Nie. Nie jest zatwierdzony w UE ani w Stanach Zjednoczonych i jest sprzedawany wyłącznie jako odczynnik badawczy do użytku laboratoryjnego.","q_en":"Czy Pentadeca Arginate jest zatwierdzonym lekiem?","a_en":"Nie. Nie jest zatwierdzony w UE ani w Stanach Zjednoczonych i jest sprzedawany wyłącznie jako odczynnik badawczy do użytku laboratoryjnego."}],"seo":{"title":"Pentadeca Arginate (PDA): profil badawczy i dowody","title_en":"Pentadeca Arginate (PDA): profil badawczy i dowody","description":"Przegląd Pentadeca Arginate: identyczność sekwencji z BPC-157, dowody dotyczące sekwencji macierzystej i profil bezpieczeństwa, przedstawione rzeczowo dla celów badawczych.","description_en":"Przegląd Pentadeca Arginate: identyczność sekwencji z BPC-157, dowody dotyczące sekwencji macierzystej i profil bezpieczeństwa, przedstawione rzeczowo dla celów badawczych."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":null,"aminosaeuren":15,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":15,"quellen":["chemverify Katalog 14.09.2026 (CAS/Molekulargewicht dort nicht geführt, PubChem: kein Eintrag für Pentadeca Arginate)"]},"verwandt":["bpc-157","tb-500","ghk-cu"]},{"slug":"tb-500","name":"TB-500","synonyme":["Fragment tymozyny beta-4","TB4 Frag"],"kategorie":"Regeneration","studienlage":"präklinisch","kurz":"Syntetyczny fragment własnego białka organizmu, tymozyny beta-4, badany w badaniach przedklinicznych nad migracją komórek i regeneracją tkanek.","kurz_en":"Syntetyczny fragment własnego białka organizmu, tymozyny beta-4, badany w badaniach przedklinicznych nad migracją komórek i regeneracją tkanek.","beschreibung":"TB-500 to syntetycznie wytworzona, siedmioaminokwasowa sekwencja rdzeniowa własnego białka organizmu, tymozyny beta-4. Większość dostępnych danych, w tym z badań klinicznych, dotyczy pełnej, 43-aminokwasowej tymozyny beta-4, a nie samego izolowanego fragmentu TB-500. Obszary badań obejmują migrację komórek, angiogenezę i możliwą rolę w aktywacji mieszków włosowych.","beschreibung_en":"TB-500 to syntetycznie wytworzona, siedmioaminokwasowa sekwencja rdzeniowa własnego białka organizmu, tymozyny beta-4. Większość dostępnych danych, w tym z badań klinicznych, dotyczy pełnej, 43-aminokwasowej tymozyny beta-4, a nie samego izolowanego fragmentu TB-500. Obszary badań obejmują migrację komórek, angiogenezę i możliwą rolę w aktywacji mieszków włosowych.","mechanismus":"Badana sekwencja rdzeniowa wiąże G-aktynę, budulec cytoskeletu, tym samym wpływając na ruch komórek w tkance. W pełnym białku tymozyny beta-4 opisano również zaangażowanie w angiogenezę poprzez zwiększoną ekspresję VEGF i efekt regulujący stan zapalny poprzez szlak NF-κB. Nie jest naukowo ustalone, czy te mechanizmy w pełni przenoszą się na izolowany fragment TB-500.","mechanismus_en":"Badana sekwencja rdzeniowa wiąże G-aktynę, budulec cytoskeletu, tym samym wpływając na ruch komórek w tkance. W pełnym białku tymozyny beta-4 opisano również zaangażowanie w angiogenezę poprzez zwiększoną ekspresję VEGF i efekt regulujący stan zapalny poprzez szlak NF-κB. Nie jest naukowo ustalone, czy te mechanizmy w pełni przenoszą się na izolowany fragment TB-500.","evidenz":[{"art":"przedkliniczne","kurz":"Badanie u szczurów i myszy opisało, że aktywna sekwencja tymozyny beta-4, która również tworzy TB-500, wpływała na migrację komórek macierzystych w mieszku włosowym.","kurz_en":"Badanie u szczurów i myszy opisało, że aktywna sekwencja tymozyny beta-4, która również tworzy TB-500, wpływała na migrację komórek macierzystych w mieszku włosowym.","quelle":"Philp et al. 2004, FASEB Journal, PMID 14657002"},{"art":"kliniczne","kurz":"Randomizowane, kontrolowane placebo badanie kliniczne u pacjentów z ciężkim zespołem suchego oka testowało preparat w postaci kropli do oczu zawierający pełne białko tymozyny beta-4 i opisało poprawę objawów przedmiotowych i podmiotowych w porównaniu z placebo. Badanie dotyczyło pełnego białka, a nie samego fragmentu TB-500.","kurz_en":"Randomizowane, kontrolowane placebo badanie kliniczne u pacjentów z ciężkim zespołem suchego oka testowało preparat w postaci kropli do oczu zawierający pełne białko tymozyny beta-4 i opisało poprawę objawów przedmiotowych i podmiotowych w porównaniu z placebo. Badanie dotyczyło pełnego białka, a nie samego fragmentu TB-500.","quelle":"Sosne et al. 2015, Cornea, PMID 25826322"}],"sicherheit":["Dla TB-500 jako izolowanego fragmentu nie ma dostępnych niezależnych badań bezpieczeństwa na ludziach.","Dla pełnego białka tymozyny beta-4 kliniczne badania opisały głównie łagodne i przejściowe działania niepożądane.","Na poziomie mechanistycznym dyskutuje się teoretyczny związek między działaniami promującymi angiogenezę a istniejącym wzrostem guza, związek przyczynowy nie został ustalony.","Tymozyna beta-4 i powiązane fragmenty znajdują się na liście substancji zabronionych Światowej Agencji Antydopingowej (WADA)."],"sicherheit_en":["Dla TB-500 jako izolowanego fragmentu nie ma dostępnych niezależnych badań bezpieczeństwa na ludziach.","Dla pełnego białka tymozyny beta-4 kliniczne badania opisały głównie łagodne i przejściowe działania niepożądane.","Na poziomie mechanistycznym dyskutuje się teoretyczny związek między działaniami promującymi angiogenezę a istniejącym wzrostem guza, związek przyczynowy nie został ustalony.","Tymozyna beta-4 i powiązane fragmenty znajdują się na liście substancji zabronionych Światowej Agencji Antydopingowej (WADA)."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"TB-500 nie jest zatwierdzony jako lek w Niemczech, UE ani w Stanach Zjednoczonych i jest sprzedawany wyłącznie jako odczynnik badawczy. Powiązane białko, tymozyna beta-4, również nie jest zatwierdzone jako samodzielny lek.","rechtsstatus_en":"TB-500 nie jest zatwierdzony jako lek w Niemczech, UE ani w Stanach Zjednoczonych i jest sprzedawany wyłącznie jako odczynnik badawczy. Powiązane białko, tymozyna beta-4, również nie jest zatwierdzone jako samodzielny lek.","typischeMg":[],"faq":[{"q":"Czy TB-500 jest tym samym co tymozyna beta-4?","a":"Nie. TB-500 jest syntetycznym, siedmioaminokwasowym fragmentem pełnej, 43-aminokwasowej sekwencji tymozyny beta-4. Większość danych klinicznych dotyczy pełnego białka, a nie fragmentu.","q_en":"Czy TB-500 jest tym samym co tymozyna beta-4?","a_en":"Nie. TB-500 jest syntetycznym, siedmioaminokwasowym fragmentem pełnej, 43-aminokwasowej sekwencji tymozyny beta-4. Większość danych klinicznych dotyczy pełnego białka, a nie fragmentu."},{"q":"Czy istnieją badania kliniczne dotyczące samego TB-500?","a":"Nie ma dostępnych niezależnych badań klinicznych na ludziach dotyczących izolowanego fragmentu TB-500. Dostępne dane kliniczne pochodzą z pełnego białka tymozyny beta-4.","q_en":"Czy istnieją badania kliniczne dotyczące samego TB-500?","a_en":"Nie ma dostępnych niezależnych badań klinicznych na ludziach dotyczących izolowanego fragmentu TB-500. Dostępne dane kliniczne pochodzą z pełnego białka tymozyny beta-4."},{"q":"Czy TB-500 ma znaczenie w przepisach antydopingowych?","a":"Tymozyna beta-4 i powiązane fragmenty znajdują się na liście substancji zabronionych Światowej Agencji Antydopingowej (WADA).","q_en":"Czy TB-500 ma znaczenie w przepisach antydopingowych?","a_en":"Tymozyna beta-4 i powiązane fragmenty znajdują się na liście substancji zabronionych Światowej Agencji Antydopingowej (WADA)."}],"seo":{"title":"TB-500: profil badawczy i dowody","title_en":"TB-500: profil badawczy i dowody","description":"Przegląd TB-500: pochodzenie z tymozyny beta-4, mechanizm, dowody i profil bezpieczeństwa, przedstawione w sposób faktyczny w kontekście badań.","description_en":"Przegląd TB-500: pochodzenie z tymozyny beta-4, mechanizm, dowody i profil bezpieczeństwa, przedstawione w sposób faktyczny w kontekście badań."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":"4963 g/mol","aminosaeuren":43,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":43,"quellen":["PubChem CID 45382195","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, standard handlowy)"},"verwandt":["bpc-157","ghk-cu","thymosin-alpha-1","pentadeca-arginate"]},{"slug":"5-amino-1mq","name":"5-Amino-1MQ","synonyme":["5-Amino 1MQ","5A1MQ","Inhibitor NNMT"],"kategorie":"Stoffwechsel","studienlage":"präklinisch","kurz":"Mała cząsteczka i selektywny inhibitor enzymu N-metylotransferazy nikotynamidu (NNMT), badany do tej pory wyłącznie w przedklinicznych modelach zwierzęcych związanych z metabolizmem tłuszczów.","kurz_en":"Mała cząsteczka i selektywny inhibitor enzymu N-metylotransferazy nikotynamidu (NNMT), badany do tej pory wyłącznie w przedklinicznych modelach zwierzęcych związanych z metabolizmem tłuszczów.","beschreibung":"5-Amino-1MQ nie jest peptydem, lecz małą cząsteczką, selektywnym, biodostępnym po podaniu doustnym inhibitorem N-metylotransferazy nikotynamidu (NNMT). Ma masę cząsteczkową 173,21 Da, a partie badawcze sprzedawane handlowo mają zazwyczaj czystość co najmniej 98 procent. Znajduje się w kategorii metabolizmu, ponieważ NNMT bierze udział w metabolizmie energetycznym w tkance tłuszczowej i mięśniach. Do tej pory dostępne są tylko dane przedkliniczne z modeli gryzoni i nie są znane żadne kontrolowane badania na ludziach.","beschreibung_en":"5-Amino-1MQ nie jest peptydem, lecz małą cząsteczką, selektywnym, biodostępnym po podaniu doustnym inhibitorem N-metylotransferazy nikotynamidu (NNMT). Ma masę cząsteczkową 173,21 Da, a partie badawcze sprzedawane handlowo mają zazwyczaj czystość co najmniej 98 procent. Znajduje się w kategorii metabolizmu, ponieważ NNMT bierze udział w metabolizmie energetycznym w tkance tłuszczowej i mięśniach. Do tej pory dostępne są tylko dane przedkliniczne z modeli gryzoni i nie są znane żadne kontrolowane badania na ludziach.","mechanismus":"NNMT przenosi grupę metylową z S-adenozylometioniny (SAM) na nikotynamid, prekursor NAD+, tworząc 1-metylonikotynamid. Reakcja ta zużywa zarówno SAM, jak i nikotynamid, prekursor NAD+. 5-Amino-1MQ selektywnie hamuje ten enzym, co w modelach zwierzęcych zachowało wewnątrzkomórkowy poziom NAD+ i SAM w komórkach tłuszczowych i mięśniowych. W badaniach przedklinicznych wiązano to ze zwiększonym wydatkiem energetycznym, mniejszymi rozmiarami adipocytów i lepszą zdolnością regeneracyjną tkanki mięśniowej.","mechanismus_en":"NNMT przenosi grupę metylową z S-adenozylometioniny (SAM) na nikotynamid, prekursor NAD+, tworząc 1-metylonikotynamid. Reakcja ta zużywa zarówno SAM, jak i nikotynamid, prekursor NAD+. 5-Amino-1MQ selektywnie hamuje ten enzym, co w modelach zwierzęcych zachowało wewnątrzkomórkowy poziom NAD+ i SAM w komórkach tłuszczowych i mięśniowych. W badaniach przedklinicznych wiązano to ze zwiększonym wydatkiem energetycznym, mniejszymi rozmiarami adipocytów i lepszą zdolnością regeneracyjną tkanki mięśniowej.","evidenz":[{"art":"przedkliniczne","kurz":"W modelu myszy z genetycznym wyciszeniem NNMT w tkance tłuszczowej zaobserwowano ochronę przed otyłością wywołaną dietą w porównaniu do zwierząt kontrolnych, wraz ze zwiększonym wydatkiem energetycznym.","kurz_en":"W modelu myszy z genetycznym wyciszeniem NNMT w tkance tłuszczowej zaobserwowano ochronę przed otyłością wywołaną dietą w porównaniu do zwierząt kontrolnych, wraz ze zwiększonym wydatkiem energetycznym.","quelle":"Kraus D et al. 2014, Nature 508:258-262, PMID 24717514"},{"art":"przedkliniczne","kurz":"U myszy z otyłością wywołaną dietą jedenaście dni podawania 5-Amino-1MQ zmniejszyło masę ciała, masę tkanki tłuszczowej i rozmiar adipocytów w porównaniu ze zwierzętami kontrolnymi, bez zmiany ilości przyjmowanego pokarmu.","kurz_en":"U myszy z otyłością wywołaną dietą jedenaście dni podawania 5-Amino-1MQ zmniejszyło masę ciała, masę tkanki tłuszczowej i rozmiar adipocytów w porównaniu ze zwierzętami kontrolnymi, bez zmiany ilości przyjmowanego pokarmu.","quelle":"Neelakantan H et al. 2018, Biochemical Pharmacology, PMID 29155147"},{"art":"przedkliniczne","kurz":"U starych myszy inhibitor NNMT wiązał się z reaktywacją starzejących się (senescentnych) komórek macierzystych mięśni i lepszą zdolnością regeneracyjną mięśni szkieletowych po urazie.","kurz_en":"U starych myszy inhibitor NNMT wiązał się z reaktywacją starzejących się (senescentnych) komórek macierzystych mięśni i lepszą zdolnością regeneracyjną mięśni szkieletowych po urazie.","quelle":"Neelakantan H et al. 2019, Biochemical Pharmacology 163:481-492, PMID 30753815"},{"art":"przedkliniczne","kurz":"Połączenie diety o obniżonej kaloryczności z 5-Amino-1MQ szybciej normalizowało odsetek tkanki tłuszczowej i masę ciała u myszy z otyłością wywołaną dietą niż sama zmiana diety, jednocześnie zmieniając skład mikrobiomu jelitowego.","kurz_en":"Połączenie diety o obniżonej kaloryczności z 5-Amino-1MQ szybciej normalizowało odsetek tkanki tłuszczowej i masę ciała u myszy z otyłością wywołaną dietą niż sama zmiana diety, jednocześnie zmieniając skład mikrobiomu jelitowego.","quelle":"Scientific Reports 2022, PMID 35013352"}],"sicherheit":["W badaniu Neelakantana i wsp. z 2018 roku u otyłych myszy spożycie pokarmu nie zmieniło się pod wpływem 5-Amino-1MQ, co w modelu zwierzęcym sugeruje rozsądną tolerancję w okresie trwania badania.","Nie są znane kontrolowane badania bezpieczeństwa 5-Amino-1MQ u ludzi, dostępne są tylko dane z modeli zwierzęcych.","Standardowe przedkliniczne pakiety toksykologiczne, takie jak badania wielotygodniowego, wielokrotnego podawania na dodatkowych gatunkach, nie zostały opublikowane dla 5-Amino-1MQ.","Interakcje z innymi substancjami lub suplementami nie były systematycznie badane dla 5-Amino-1MQ."],"sicherheit_en":["W badaniu Neelakantana i wsp. z 2018 roku u otyłych myszy spożycie pokarmu nie zmieniło się pod wpływem 5-Amino-1MQ, co w modelu zwierzęcym sugeruje rozsądną tolerancję w okresie trwania badania.","Nie są znane kontrolowane badania bezpieczeństwa 5-Amino-1MQ u ludzi, dostępne są tylko dane z modeli zwierzęcych.","Standardowe przedkliniczne pakiety toksykologiczne, takie jak badania wielotygodniowego, wielokrotnego podawania na dodatkowych gatunkach, nie zostały opublikowane dla 5-Amino-1MQ.","Interakcje z innymi substancjami lub suplementami nie były systematycznie badane dla 5-Amino-1MQ."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"5-Amino-1MQ nie jest zatwierdzony jako lek w UE ani w Stanach Zjednoczonych i jest sprzedawany wyłącznie jako odczynnik badawczy. Nie są znane żadne badania rejestracyjne na ludziach.","rechtsstatus_en":"5-Amino-1MQ nie jest zatwierdzony jako lek w UE ani w Stanach Zjednoczonych i jest sprzedawany wyłącznie jako odczynnik badawczy. Nie są znane żadne badania rejestracyjne na ludziach.","typischeMg":[10,50],"faq":[{"q":"Czy 5-Amino-1MQ jest peptydem?","a":"Nie. 5-Amino-1MQ jest małą cząsteczką, a nie peptydem, i nie składa się z łańcucha aminokwasów. Jest badany jako selektywny inhibitor enzymu NNMT i wymieniony tutaj wśród związków związanych z metabolizmem, ponieważ działa na powiązane systemy docelowe.","q_en":"Czy 5-Amino-1MQ jest peptydem?","a_en":"Nie. 5-Amino-1MQ jest małą cząsteczką, a nie peptydem, i nie składa się z łańcucha aminokwasów. Jest badany jako selektywny inhibitor enzymu NNMT i wymieniony tutaj wśród związków związanych z metabolizmem, ponieważ działa na powiązane systemy docelowe."},{"q":"Czy istnieją badania na ludziach dotyczące 5-Amino-1MQ?","a":"Nie, do tej pory nie są znane żadne kontrolowane badania kliniczne na ludziach. Wszystkie opublikowane dane pochodzą z badań przedklinicznych na myszach.","q_en":"Czy istnieją badania na ludziach dotyczące 5-Amino-1MQ?","a_en":"Nie, do tej pory nie są znane żadne kontrolowane badania kliniczne na ludziach. Wszystkie opublikowane dane pochodzą z badań przedklinicznych na myszach."},{"q":"Dlaczego NNMT jest przedmiotem badań?","a":"NNMT to enzym aktywny w tkance tłuszczowej i mięśniowej, który rozkłada nikotynamid, prekursor NAD+. Podwyższony poziom NNMT powiązano w modelach przedklinicznych ze zmniejszoną aktywnością metaboliczną, dlatego jego hamowanie jest badane jako podejście badawcze.","q_en":"Dlaczego NNMT jest przedmiotem badań?","a_en":"NNMT to enzym aktywny w tkance tłuszczowej i mięśniowej, który rozkłada nikotynamid, prekursor NAD+. Podwyższony poziom NNMT powiązano w modelach przedklinicznych ze zmniejszoną aktywnością metaboliczną, dlatego jego hamowanie jest badane jako podejście badawcze."}],"seo":{"title":"5-Amino-1MQ: Inhibitor NNMT w badaniach przedklinicznych","title_en":"5-Amino-1MQ: Inhibitor NNMT w badaniach przedklinicznych","description":"5-Amino-1MQ w pigułce: mechanizm, stan badań przedklinicznych i status prawny inhibitora NNMT, który jest małą cząsteczką, a nie peptydem.","description_en":"5-Amino-1MQ w pigułce: mechanizm, stan badań przedklinicznych i status prawny inhibitora NNMT, który jest małą cząsteczką, a nie peptydem."},"demo":false,"steckbrief":{"cas":"685079-15-6","molekulargewicht":"159,21 g/mol","aminosaeuren":null,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":null,"quellen":["PubChem CID 950107","chemverify Katalog 14.09.2026","kein Peptid, kleines Molekül ohne Aminosäuresequenz (NNMT-Inhibitor)"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)"},"verwandt":["aod-9604","mots-c","tirzepatid"]},{"slug":"aod-9604","name":"AOD-9604","synonyme":["Lek przeciw otyłości 9604","Tyr-hGH Frag 177-191"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Fragment peptydowy ludzkiego hormonu wzrostu (aminokwasy 177-191), badany pod kątem działania zmniejszającego tkankę tłuszczową, bez działania pobudzającego wzrost, charakterystycznego dla pełnego hormonu.","kurz_en":"Fragment peptydowy ludzkiego hormonu wzrostu (aminokwasy 177-191), badany pod kątem działania zmniejszającego tkankę tłuszczową, bez działania pobudzającego wzrost, charakterystycznego dla pełnego hormonu.","beschreibung":"AOD-9604 to syntetyczny, 16-aminokwasowy fragment ludzkiego hormonu wzrostu (sekwencja Tyr-hGH177-191), pierwotnie opracowany przez Metabolic Pharmaceuticals we współpracy z Monash University w celu regulacji masy ciała. Badano go w sześciu randomizowanych, kontrolowanych placebo badaniach klinicznych z udziałem ponad 900 osób pod kątem działania metabolicznego i bezpieczeństwa. Rozwój kliniczny jako związku przeciw otyłości przerwano w 2007 roku, ponieważ największe badanie nie osiągnęło pierwszorzędowego punktu końcowego dotyczącego skuteczności.","beschreibung_en":"AOD-9604 to syntetyczny, 16-aminokwasowy fragment ludzkiego hormonu wzrostu (sekwencja Tyr-hGH177-191), pierwotnie opracowany przez Metabolic Pharmaceuticals we współpracy z Monash University w celu regulacji masy ciała. Badano go w sześciu randomizowanych, kontrolowanych placebo badaniach klinicznych z udziałem ponad 900 osób pod kątem działania metabolicznego i bezpieczeństwa. Rozwój kliniczny jako związku przeciw otyłości przerwano w 2007 roku, ponieważ największe badanie nie osiągnęło pierwszorzędowego punktu końcowego dotyczącego skuteczności.","mechanismus":"AOD-9604 obejmuje region lipolityczny (aminokwasy 177-191) cząsteczki hormonu wzrostu, bez regionu wiążącego receptor, odpowiedzialnego za zależne od IGF-1 działanie wzrostowe i metaboliczne pełnego hGH. Modele przedkliniczne opisują aktywację lipolizy przez przekaźnik diacyloglicerol i enzym lipazę wrażliwą na hormony, za pośrednictwem receptora beta-3-adrenergicznego. W przeciwieństwie do pełnego hGH AOD-9604 nie wpływał w badaniach na poziom IGF-1 ani na wrażliwość na insulinę.","mechanismus_en":"AOD-9604 obejmuje region lipolityczny (aminokwasy 177-191) cząsteczki hormonu wzrostu, bez regionu wiążącego receptor, odpowiedzialnego za zależne od IGF-1 działanie wzrostowe i metaboliczne pełnego hGH. Modele przedkliniczne opisują aktywację lipolizy przez przekaźnik diacyloglicerol i enzym lipazę wrażliwą na hormony, za pośrednictwem receptora beta-3-adrenergicznego. W przeciwieństwie do pełnego hGH AOD-9604 nie wpływał w badaniach na poziom IGF-1 ani na wrażliwość na insulinę.","evidenz":[{"art":"przedkliniczne","kurz":"W badaniu przedklinicznym na otyłych szczurach Zucker 19-dniowe doustne podawanie AOD-9604 zmniejszyło przyrost masy ciała o ponad 50 procent w porównaniu ze zwierzętami kontrolnymi.","kurz_en":"W badaniu przedklinicznym na otyłych szczurach Zucker 19-dniowe doustne podawanie AOD-9604 zmniejszyło przyrost masy ciała o ponad 50 procent w porównaniu ze zwierzętami kontrolnymi.","quelle":"Ng FM et al. 2000, Hormone Research 53(6):274-278, PMID 11146367"},{"art":"przedkliniczne","kurz":"U otyłych myszy przewlekłe podawanie AOD-9604 zwiększało utlenianie tłuszczów i wrażliwość lipolityczną poprzez szlak receptora beta-3-adrenergicznego, porównywalnie z pełnym hGH, ale bez wpływu na wrażliwość na insulinę.","kurz_en":"U otyłych myszy przewlekłe podawanie AOD-9604 zwiększało utlenianie tłuszczów i wrażliwość lipolityczną poprzez szlak receptora beta-3-adrenergicznego, porównywalnie z pełnym hGH, ale bez wpływu na wrażliwość na insulinę.","quelle":"Heffernan M et al. 2001, Endocrinology 142(12):5182-5189, PMID 11673763"},{"art":"kliniczne","kurz":"W randomizowanym, podwójnie zaślepionym, kontrolowanym placebo badaniu wieloośrodkowym u 300 dorosłych z otyłością grupa przyjmująca 1 mg doustnie dziennie schudła średnio 2,8 kg w ciągu 12 tygodni, w porównaniu z 0,8 kg w grupie placebo.","kurz_en":"W randomizowanym, podwójnie zaślepionym, kontrolowanym placebo badaniu wieloośrodkowym u 300 dorosłych z otyłością grupa przyjmująca 1 mg doustnie dziennie schudła średnio 2,8 kg w ciągu 12 tygodni, w porównaniu z 0,8 kg w grupie placebo.","quelle":"Herd C et al. 2005, randomisierte Multicenter-Studie (Publikationsnachweis: ResearchGate ID 295313034 / University of Melbourne)"},{"art":"kliniczne","kurz":"Przegląd bezpieczeństwa obejmujący sześć randomizowanych, kontrolowanych placebo badań klinicznych na ludziach nie wykazał wzrostu poziomu IGF-1, poważnych zdarzeń niepożądanych związanych z AOD-9604 ani wykrywalnych przeciwciał przeciw AOD-9604.","kurz_en":"Przegląd bezpieczeństwa obejmujący sześć randomizowanych, kontrolowanych placebo badań klinicznych na ludziach nie wykazał wzrostu poziomu IGF-1, poważnych zdarzeń niepożądanych związanych z AOD-9604 ani wykrywalnych przeciwciał przeciw AOD-9604.","quelle":"Stier H et al. 2013, Journal of Endocrinology and Metabolism 3(2), jofem.org"}],"sicherheit":["W sześciu randomizowanych, kontrolowanych placebo badaniach klinicznych na ludziach nie wystąpiły poważne zdarzenia niepożądane związane z AOD-9604, a zgłaszane efekty były niewielkie i przejściowe.","W przeciwieństwie do pełnego hGH, AOD-9604 nie podniósł poziomów IGF-1 ani nie pogorszył tolerancji glukozy w tych badaniach.","W badaniach sprawdzających immunogenność nie wykryto przeciwciał przeciwko AOD-9604.","Rozwój kliniczny przerwano w 2007 roku po tym, jak większe badanie fazy 2b nie osiągnęło statystycznie pierwszorzędowego punktu końcowego dotyczącego utraty masy ciała w porównaniu z placebo; jako powodu nie podano żadnych obaw dotyczących bezpieczeństwa.","Ponieważ AOD-9604 nie jest nigdzie zatwierdzony jako lek, nie istnieje oficjalna charakterystyka produktu dotycząca długoterminowego bezpieczeństwa."],"sicherheit_en":["W sześciu randomizowanych, kontrolowanych placebo badaniach klinicznych na ludziach nie wystąpiły poważne zdarzenia niepożądane związane z AOD-9604, a zgłaszane efekty były niewielkie i przejściowe.","W przeciwieństwie do pełnego hGH, AOD-9604 nie podniósł poziomów IGF-1 ani nie pogorszył tolerancji glukozy w tych badaniach.","W badaniach sprawdzających immunogenność nie wykryto przeciwciał przeciwko AOD-9604.","Rozwój kliniczny przerwano w 2007 roku po tym, jak większe badanie fazy 2b nie osiągnęło statystycznie pierwszorzędowego punktu końcowego dotyczącego utraty masy ciała w porównaniu z placebo; jako powodu nie podano żadnych obaw dotyczących bezpieczeństwa.","Ponieważ AOD-9604 nie jest nigdzie zatwierdzony jako lek, nie istnieje oficjalna charakterystyka produktu dotycząca długoterminowego bezpieczeństwa."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"AOD-9604 nie jest zatwierdzony jako lek w UE ani w Stanach Zjednoczonych. Rozwój kliniczny jako związku przeciw otyłości przerwano w 2007 roku po badaniu fazy 2b. Substancja jest sprzedawana wyłącznie jako odczynnik badawczy i znajduje się na Liście Substancji Zabronionych WADA w sporcie.","rechtsstatus_en":"AOD-9604 nie jest zatwierdzony jako lek w UE ani w Stanach Zjednoczonych. Rozwój kliniczny jako związku przeciw otyłości przerwano w 2007 roku po badaniu fazy 2b. Substancja jest sprzedawana wyłącznie jako odczynnik badawczy i znajduje się na Liście Substancji Zabronionych WADA w sporcie.","typischeMg":[2,5,10],"faq":[{"q":"Czy AOD-9604 jest zatwierdzony jako lek?","a":"Nie. AOD-9604 był badany w sześciu badaniach klinicznych, a prace nad nim jako związkiem przeciw otyłości przerwano w 2007 roku. Obecnie nie jest zatwierdzonym lekiem i jest sprzedawany wyłącznie jako odczynnik badawczy.","q_en":"Czy AOD-9604 jest zatwierdzony jako lek?","a_en":"Nie. AOD-9604 był badany w sześciu badaniach klinicznych, a prace nad nim jako związkiem przeciw otyłości przerwano w 2007 roku. Obecnie nie jest zatwierdzonym lekiem i jest sprzedawany wyłącznie jako odczynnik badawczy."},{"q":"Jak AOD-9604 różni się od pełnego hormonu wzrostu?","a":"AOD-9604 zawiera tylko region lipolityczny cząsteczki hGH (aminokwasy 177-191), a nie region, który wyzwala efekty wzrostu mediowane przez IGF-1. W przeciwieństwie do nienaruszonego hGH, nie wykazał wpływu na IGF-1 ani czułość na insulinę w badaniach.","q_en":"Jak AOD-9604 różni się od pełnego hormonu wzrostu?","a_en":"AOD-9604 zawiera tylko region lipolityczny cząsteczki hGH (aminokwasy 177-191), a nie region, który wyzwala efekty wzrostu mediowane przez IGF-1. W przeciwieństwie do nienaruszonego hGH, nie wykazał wpływu na IGF-1 ani czułość na insulinę w badaniach."},{"q":"Czy AOD-9604 jest dozwolony w sporcie?","a":"Nie. AOD-9604 jest wymieniony jako fragment hormonu wzrostu na Liście Substancji Zabronionych WADA i nie jest dla niego dostępne zwolnienie z powodów terapeutycznych (TUE).","q_en":"Czy AOD-9604 jest dozwolony w sporcie?","a_en":"Nie. AOD-9604 jest wymieniony jako fragment hormonu wzrostu na Liście Substancji Zabronionych WADA i nie jest dla niego dostępne zwolnienie z powodów terapeutycznych (TUE)."}],"seo":{"title":"AOD-9604: fragment hGH 177-191 w badaniach","title_en":"AOD-9604: fragment hGH 177-191 w badaniach","description":"AOD-9604 w pigułce: mechanizm, status badań i profil bezpieczeństwa fragmentu hGH 177-191 badanego w badaniach klinicznych dotyczących regulacji masy ciała.","description_en":"AOD-9604 w pigułce: mechanizm, status badań i profil bezpieczeństwa fragmentu hGH 177-191 badanego w badaniach klinicznych dotyczących regulacji masy ciała."},"demo":false,"steckbrief":{"cas":"221231-10-3","molekulargewicht":"1815,1 g/mol","aminosaeuren":16,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":16,"quellen":["PubChem CID 71300630","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)"},"verwandt":["tesamorelin","mots-c","5-amino-1mq"]},{"slug":"cagrilintid","name":"Cagrilintide","synonyme":["AM833","NN9838"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Długo działający analog własnego hormonu organizmu, amyliny, badany w badaniach klinicznych pod kątem regulacji metabolizmu i sytości, samodzielnie i w połączeniu z semaglutydem.","kurz_en":"Długo działający analog własnego hormonu organizmu, amyliny, badany w badaniach klinicznych pod kątem regulacji metabolizmu i sytości, samodzielnie i w połączeniu z semaglutydem.","beschreibung":"Cagrilintide to długo działający analog amyliny opracowany przez Novo Nordisk. Jest badany w badaniach fazy 3 zarówno jako substancja samodzielna, jak i w stałej kombinacji ze związkiem GLP-1, semaglutydem, oferowanej pod nazwą CagriSema. Do tej pory cagrilintide nie jest zatwierdzony jako samodzielny lek w żadnym kraju.","beschreibung_en":"Cagrilintide to długo działający analog amyliny opracowany przez Novo Nordisk. Jest badany w badaniach fazy 3 zarówno jako substancja samodzielna, jak i w stałej kombinacji ze związkiem GLP-1, semaglutydem, oferowanej pod nazwą CagriSema. Do tej pory cagrilintide nie jest zatwierdzony jako samodzielny lek w żadnym kraju.","mechanismus":"Cagrilintide wiąże się z receptorami amyliny w mózgu, głównie z podtypami AMY1 i AMY3, tworzonymi przez receptor kalcytoniny wraz z pomocniczymi białkami RAMP. Powiązano to ze spowolnionym opróżnianiem żołądka, zmniejszonym uwalnianiem glukagonu po posiłku i sygnalizacją sytości w regionach mózgu, takich jak area postrema. Lipidacja cząsteczki kwasem tłuszczowym znacznie wydłuża czas jej działania w porównaniu z naturalnym hormonem amyliną, co umożliwiło podawanie raz w tygodniu w warunkach badania.","mechanismus_en":"Cagrilintide wiąże się z receptorami amyliny w mózgu, głównie z podtypami AMY1 i AMY3, tworzonymi przez receptor kalcytoniny wraz z pomocniczymi białkami RAMP. Powiązano to ze spowolnionym opróżnianiem żołądka, zmniejszonym uwalnianiem glukagonu po posiłku i sygnalizacją sytości w regionach mózgu, takich jak area postrema. Lipidacja cząsteczki kwasem tłuszczowym znacznie wydłuża czas jej działania w porównaniu z naturalnym hormonem amyliną, co umożliwiło podawanie raz w tygodniu w warunkach badania.","evidenz":[{"art":"kliniczne","kurz":"W randomizowanym badaniu fazy 2 testującym różne ilości u 706 dorosłych z nadwagą lub otyłością, cagrilintide sam przez 26 tygodni doprowadził do średniej utraty masy ciała o 10,8 procent przy najwyższej przetestowanej ilości, w porównaniu z około 3 procentami w grupie placebo.","kurz_en":"W randomizowanym badaniu fazy 2 testującym różne ilości u 706 dorosłych z nadwagą lub otyłością, cagrilintide sam przez 26 tygodni doprowadził do średniej utraty masy ciała o 10,8 procent przy najwyższej przetestowanej ilości, w porównaniu z około 3 procentami w grupie placebo.","quelle":"Lau DCW et al. 2021, The Lancet 398:2160-2172, PMID 34798060"},{"art":"kliniczne","kurz":"W badaniu fazy 3 REDEFINE 1 ramię z samym cagrilintide w ilości 2,4 mg tygodniowo osiągnęło po 68 tygodniach utratę masy ciała na poziomie około 11,8 procent, w porównaniu z 2,3 procent w grupie placebo.","kurz_en":"W badaniu fazy 3 REDEFINE 1 ramię z samym cagrilintide w ilości 2,4 mg tygodniowo osiągnęło po 68 tygodniach utratę masy ciała na poziomie około 11,8 procent, w porównaniu z 2,3 procent w grupie placebo.","quelle":"Garvey WT et al. 2025, New England Journal of Medicine 393:625-638, PMID 40544433"},{"art":"przedkliniczne","kurz":"W mysim modelu otyłości wywołanej dietą działanie cagrilintide obniżające masę ciała zależało od receptorów amyliny w mózgu, AMY1 i AMY3, a u zwierząt z wyłączonymi (knockout) receptorami efekt nie występował.","kurz_en":"W mysim modelu otyłości wywołanej dietą działanie cagrilintide obniżające masę ciała zależało od receptorów amyliny w mózgu, AMY1 i AMY3, a u zwierząt z wyłączonymi (knockout) receptorami efekt nie występował.","quelle":"Carvas AO et al. 2025, eBioMedicine, PMID 40609154"},{"art":"przedkliniczne","kurz":"Optymalizacja strukturalna z lipidacją kwasem tłuszczowym nadała cagrilintide znacznie dłuższy okres półtrwania, wynoszący około 159-195 godzin, niż ma własny hormon organizmu, amylina, co umożliwiło podawanie raz w tygodniu w warunkach badania.","kurz_en":"Optymalizacja strukturalna z lipidacją kwasem tłuszczowym nadała cagrilintide znacznie dłuższy okres półtrwania, wynoszący około 159-195 godzin, niż ma własny hormon organizmu, amylina, co umożliwiło podawanie raz w tygodniu w warunkach badania.","quelle":"Kruse T et al. 2021, Journal of Medicinal Chemistry 64:11183-11194, PMID 34288673"}],"sicherheit":["W randomizowanym badaniu fazy 2, w którym cagrilintide był jedyną substancją, działania żołądkowo-jelitowe wystąpiły u 41-63 procent uczestników, w porównaniu z 32 procentami w grupie placebo, najczęściej były to nudności.","W badaniu kombinacyjnym fazy 1b z narastającymi ilościami cagrilintide w połączeniu z semaglutydem działania żołądkowo-jelitowe opisano jako najczęstszą kategorię zdarzeń niepożądanych, przy ogólnie dającym się opanować profilu bezpieczeństwa.","Jako agonista receptora amyliny opisano spowolnione opróżnianie żołądka, mechanizm, który przyczynia się także do działań żołądkowo-jelitowych związków GLP-1.","Ponieważ cagrilintide nie jest nigdzie zatwierdzony jako samodzielny lek, nie istnieje oficjalna charakterystyka produktu dotycząca długoterminowego bezpieczeństwa."],"sicherheit_en":["W randomizowanym badaniu fazy 2, w którym cagrilintide był jedyną substancją, działania żołądkowo-jelitowe wystąpiły u 41-63 procent uczestników, w porównaniu z 32 procentami w grupie placebo, najczęściej były to nudności.","W badaniu kombinacyjnym fazy 1b z narastającymi ilościami cagrilintide w połączeniu z semaglutydem działania żołądkowo-jelitowe opisano jako najczęstszą kategorię zdarzeń niepożądanych, przy ogólnie dającym się opanować profilu bezpieczeństwa.","Jako agonista receptora amyliny opisano spowolnione opróżnianie żołądka, mechanizm, który przyczynia się także do działań żołądkowo-jelitowych związków GLP-1.","Ponieważ cagrilintide nie jest nigdzie zatwierdzony jako samodzielny lek, nie istnieje oficjalna charakterystyka produktu dotycząca długoterminowego bezpieczeństwa."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Cagrilintide jest obecnie w badaniach fazy 3 zarówno jako substancja samodzielna, jak i w stałej kombinacji z semaglutydem o nazwie CagriSema i nie został jeszcze zatwierdzony jako lek w UE ani w Stanach Zjednoczonych. W grudniu 2025 roku złożono do amerykańskiej FDA wniosek o dopuszczenie nowego leku (NDA) dla kombinacji CagriSema, a decyzji spodziewano się w 2026 roku. Cagrilintide jest sprzedawany wyłącznie jako odczynnik badawczy.","rechtsstatus_en":"Cagrilintide jest obecnie w badaniach fazy 3 zarówno jako substancja samodzielna, jak i w stałej kombinacji z semaglutydem o nazwie CagriSema i nie został jeszcze zatwierdzony jako lek w UE ani w Stanach Zjednoczonych. W grudniu 2025 roku złożono do amerykańskiej FDA wniosek o dopuszczenie nowego leku (NDA) dla kombinacji CagriSema, a decyzji spodziewano się w 2026 roku. Cagrilintide jest sprzedawany wyłącznie jako odczynnik badawczy.","typischeMg":[5,10],"faq":[{"q":"Czy cagrilintide jest już dostępny jako lek?","a":"Nie. Cagrilintide jest badany jako substancja samodzielna i w kombinacji CagriSema w badaniach fazy 3. Proces zatwierdzenia przez FDA dla CagriSema toczy się od grudnia 2025 roku. Cagrilintide nie jest obecnie zatwierdzonym lekiem.","q_en":"Czy cagrilintide jest już dostępny jako lek?","a_en":"Nie. Cagrilintide jest badany jako substancja samodzielna i w kombinacji CagriSema w badaniach fazy 3. Proces zatwierdzenia przez FDA dla CagriSema toczy się od grudnia 2025 roku. Cagrilintide nie jest obecnie zatwierdzonym lekiem."},{"q":"Co odróżnia cagrilintide od semaglutydu?","a":"Semaglutyd działa na receptor GLP-1, podczas gdy cagrilintide działa na receptory amyliny w mózgu. Oba związki są też badane jako stała kombinacja o nazwie CagriSema, która w badaniach wykazała większy wpływ na masę ciała niż każda z substancji osobno.","q_en":"Co odróżnia cagrilintide od semaglutydu?","a_en":"Semaglutyd działa na receptor GLP-1, podczas gdy cagrilintide działa na receptory amyliny w mózgu. Oba związki są też badane jako stała kombinacja o nazwie CagriSema, która w badaniach wykazała większy wpływ na masę ciała niż każda z substancji osobno."},{"q":"Skąd pochodzi cagrilintide?","a":"Cagrilintide został opracowany przez firmę farmaceutyczną Novo Nordisk, która opracowała też semaglutyd. W badaniach klinicznych, w tym w programie REDEFINE, występuje pod skrótami AM833 i NN9838.","q_en":"Skąd pochodzi cagrilintide?","a_en":"Cagrilintide został opracowany przez firmę farmaceutyczną Novo Nordisk, która opracowała też semaglutyd. W badaniach klinicznych, w tym w programie REDEFINE, występuje pod skrótami AM833 i NN9838."}],"seo":{"title":"Cagrilintide: analog amyliny w badaniach fazy 3","title_en":"Cagrilintide: analog amyliny w badaniach fazy 3","description":"Cagrilintide w pigułce: mechanizm, status badań i profil bezpieczeństwa analogu amyliny, badanego samodzielnie i w kombinacji CagriSema.","description_en":"Cagrilintide w pigułce: mechanizm, status badań i profil bezpieczeństwa analogu amyliny, badanego samodzielnie i w kombinacji CagriSema."},"demo":false,"steckbrief":{"cas":"1415456-99-3","molekulargewicht":"4409 g/mol","aminosaeuren":37,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":37,"quellen":["PubChem CID 171397054","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)"},"verwandt":["semaglutid","tirzepatid","retatrutid","survodutid"]},{"slug":"mots-c","name":"MOTS-c","synonyme":["Peptyd pochodzenia mitochondrialnego MOTS-c","Mitochondrialna otwarta ramka odczytu genu 12S rRNA typu c"],"kategorie":"Stoffwechsel","studienlage":"frühe klinische Studien","kurz":"Peptyd kodowany przez mitochondrialne DNA, badany jako mimetyk wysiłku fizycznego w badaniach metabolicznych.","kurz_en":"Peptyd kodowany przez mitochondrialne DNA, badany jako mimetyk wysiłku fizycznego w badaniach metabolicznych.","beschreibung":"MOTS-c to 16-aminokwasowy peptyd kodowany bezpośrednio w mitochondrialnym DNA, a nie w jądrze komórkowym. Odkryto go w 2015 roku i bada się go jako endogenną cząsteczkę sygnałową, uwalnianą w większych ilościach podczas wysiłku fizycznego. Badania koncentrują się na możliwym wpływie na wrażliwość na insulinę, metabolizm tłuszczów i starzenie komórkowe.","beschreibung_en":"MOTS-c to 16-aminokwasowy peptyd kodowany bezpośrednio w mitochondrialnym DNA, a nie w jądrze komórkowym. Odkryto go w 2015 roku i bada się go jako endogenną cząsteczkę sygnałową, uwalnianą w większych ilościach podczas wysiłku fizycznego. Badania koncentrują się na możliwym wpływie na wrażliwość na insulinę, metabolizm tłuszczów i starzenie komórkowe.","mechanismus":"MOTS-c hamuje cykl folianowy komórki, powodując gromadzenie się cząsteczki sygnalizacyjnej AICAR i aktywację centralnego czujnika energii AMPK. Ta ścieżka stymuluje, między innymi, wychwyt glukozy do komórek mięśniowych i utlenianie kwasów tłuszczowych. Pod stresem metabolicznym MOTS-c przemieszcza się również do jądra komórkowego, gdzie wpływa na ekspresję genów zaangażowanych w adaptację do stresu.","mechanismus_en":"MOTS-c hamuje cykl folianowy komórki, powodując gromadzenie się cząsteczki sygnalizacyjnej AICAR i aktywację centralnego czujnika energii AMPK. Ta ścieżka stymuluje, między innymi, wychwyt glukozy do komórek mięśniowych i utlenianie kwasów tłuszczowych. Pod stresem metabolicznym MOTS-c przemieszcza się również do jądra komórkowego, gdzie wpływa na ekspresję genów zaangażowanych w adaptację do stresu.","evidenz":[{"art":"przedkliniczne","kurz":"W pierwotnym opisie MOTS-c zapobiegał rozwojowi oporności na insulinę u myszy na diecie wysokotłuszczowej przez kilka tygodni i przywracał u starych myszy wrażliwość na insulinę typową dla młodych zwierząt.","kurz_en":"W pierwotnym opisie MOTS-c zapobiegał rozwojowi oporności na insulinę u myszy na diecie wysokotłuszczowej przez kilka tygodni i przywracał u starych myszy wrażliwość na insulinę typową dla młodych zwierząt.","quelle":"Lee et al. 2015, Cell Metabolism 21(3):443-454"},{"art":"przedkliniczne","kurz":"U starszych myszy wielokrotne podawanie MOTS-c przez kilka tygodni wydłużyło medianę przeżycia o 5-7 procent i poprawiło wytrzymałość, siłę chwytu i równowagę w porównaniu z placebo.","kurz_en":"U starszych myszy wielokrotne podawanie MOTS-c przez kilka tygodni wydłużyło medianę przeżycia o 5-7 procent i poprawiło wytrzymałość, siłę chwytu i równowagę w porównaniu z placebo.","quelle":"Reynolds et al. 2021, Nature Communications, DOI 10.1038/s41467-020-20790-0"},{"art":"kliniczne","kurz":"W badaniu obserwacyjnym 20 aktywnych fizycznie dorosłych stężenia MOTS-c w surowicy korelowały dodatnio z mocą skoku, maksymalną siłą i masą mięśni nóg, ale nie z maksymalnym poborem tlenu.","kurz_en":"W badaniu obserwacyjnym 20 aktywnych fizycznie dorosłych stężenia MOTS-c w surowicy korelowały dodatnio z mocą skoku, maksymalną siłą i masą mięśni nóg, ale nie z maksymalnym poborem tlenu.","quelle":"Domin et al. 2023, International Journal of Molecular Sciences"}],"sicherheit":["Opublikowane badania na zwierzętach trwające do sześciu miesięcy nie wykazały istotnych działań niepożądanych.","Najczęściej zgłaszanym działaniem jest reakcja w miejscu wstrzyknięcia, taka jak uczucie pieczenia i zaczerwienienia.","MOTS-c hamuje cykl folianowy; możliwy niedobór folianów przy dłuższym stosowaniu do tej pory był opisywany jedynie teoretycznie.","Kontrolowane badania interwencyjne na ludziach dotyczące skuteczności i bezpieczeństwa nie są jeszcze dostępne."],"sicherheit_en":["Opublikowane badania na zwierzętach trwające do sześciu miesięcy nie wykazały istotnych działań niepożądanych.","Najczęściej zgłaszanym działaniem jest reakcja w miejscu wstrzyknięcia, taka jak uczucie pieczenia i zaczerwienienia.","MOTS-c hamuje cykl folianowy; możliwy niedobór folianów przy dłuższym stosowaniu do tej pory był opisywany jedynie teoretycznie.","Kontrolowane badania interwencyjne na ludziach dotyczące skuteczności i bezpieczeństwa nie są jeszcze dostępne."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"MOTS-c nie jest zatwierdzony jako lek ani jako środek spożywczy w UE ani w USA. Jest sprzedawany wyłącznie jako odczynnik badawczy i nie jest przeznaczony do stosowania u ludzi.","rechtsstatus_en":"MOTS-c nie jest zatwierdzony jako lek ani jako środek spożywczy w UE ani w USA. Jest sprzedawany wyłącznie jako odczynnik badawczy i nie jest przeznaczony do stosowania u ludzi.","typischeMg":[5,10],"faq":[{"q":"Co odróżnia MOTS-c od innych peptydów","a":"MOTS-c jest kodowany bezpośrednio w mitochondrialnym DNA, a nie w jądrze komórkowym. Działa poprzez komórkowy czujnik energii AMPK i dlatego jest klasyfikowany jako mimetyk wysiłku fizycznego.","q_en":"Co odróżnia MOTS-c od innych peptydów","a_en":"MOTS-c jest kodowany bezpośrednio w mitochondrialnym DNA, a nie w jądrze komórkowym. Działa poprzez komórkowy czujnik energii AMPK i dlatego jest klasyfikowany jako mimetyk wysiłku fizycznego."},{"q":"Czy MOTS-c jest zatwierdzonym lekiem","a":"Nie. MOTS-c nie jest zatwierdzony jako lek ani jako środek spożywczy w UE ani w USA i jest sprzedawany wyłącznie jako odczynnik badawczy.","q_en":"Czy MOTS-c jest zatwierdzonym lekiem","a_en":"Nie. MOTS-c nie jest zatwierdzony jako lek ani jako środek spożywczy w UE ani w USA i jest sprzedawany wyłącznie jako odczynnik badawczy."},{"q":"Jak solidne są dane ludzkie dotyczące MOTS-c","a":"Dotychczas ograniczone. Dowody opierają się głównie na przedklinicznych badaniach na zwierzętach i jednym obserwacyjnym badaniu na ludziach dotyczącym korelacji z siłą mięśni; nadal brakuje kontrolowanych badań interwencyjnych na ludziach.","q_en":"Jak solidne są dane ludzkie dotyczące MOTS-c","a_en":"Dotychczas ograniczone. Dowody opierają się głównie na przedklinicznych badaniach na zwierzętach i jednym obserwacyjnym badaniu na ludziach dotyczącym korelacji z siłą mięśni; nadal brakuje kontrolowanych badań interwencyjnych na ludziach."}],"seo":{"title":"Przegląd badań: MOTS-c","title_en":"Przegląd badań: MOTS-c","description":"MOTS-c przedstawiony rzeczowo: mitochondrialny mechanizm działania, dane z badań przedklinicznych i klinicznych oraz status prawny peptydu.","description_en":"MOTS-c przedstawiony rzeczowo: mitochondrialny mechanizm działania, dane z badań przedklinicznych i klinicznych oraz status prawny peptydu."},"demo":false,"steckbrief":{"cas":"1627580-64-6","molekulargewicht":"2174,6 g/mol","aminosaeuren":16,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":16,"quellen":["PubChem CID 146675088","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)"},"verwandt":["semaglutid","ss-31","aod-9604","5-amino-1mq"]},{"slug":"retatrutid","name":"Retatrutyd","synonyme":["LY3437943"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Peptyd, który działa jednocześnie na receptory GLP-1, GIP i glukagonu, obecnie w zaawansowanych badaniach klinicznych związanych z regulacją metaboliczną.","kurz_en":"Peptyd, który działa jednocześnie na receptory GLP-1, GIP i glukagonu, obecnie w zaawansowanych badaniach klinicznych związanych z regulacją metaboliczną.","beschreibung":"Retatrutyd jest tak zwanym agonistą potrójnym, który działa jednocześnie na trzy receptory metaboliczne: GLP-1, GIP i glukagonu. Producent, Eli Lilly, ogłosił 23 lipca 2026 r. wstępne wyniki (topline) fazy 3 i zapowiedział złożenie wniosku do amerykańskiego urzędu FDA w 1. kwartale 2027 r. Retatrutyd jest substancją badaną i do tej pory nie został dopuszczony do obrotu jako lek w żadnym kraju.","beschreibung_en":"Retatrutyd jest tak zwanym agonistą potrójnym, który działa jednocześnie na trzy receptory metaboliczne: GLP-1, GIP i glukagonu. Producent, Eli Lilly, ogłosił 23 lipca 2026 r. wstępne wyniki (topline) fazy 3 i zapowiedział złożenie wniosku do amerykańskiego urzędu FDA w 1. kwartale 2027 r. Retatrutyd jest substancją badaną i do tej pory nie został dopuszczony do obrotu jako lek w żadnym kraju.","mechanismus":"Poprzez receptor GLP-1 opisano wpływ na regulację sytości i spowolnione opróżnianie żołądka. Receptor GIP powiązano ze zwiększonym wydzielaniem insuliny i możliwym łagodzeniem działań żołądkowo-jelitowych. Dodatkowe działanie na receptor glukagonu wiązano ze zwiększonym wydatkiem energetycznym wątroby i aktywacją brunatnej tkanki tłuszczowej.","mechanismus_en":"Poprzez receptor GLP-1 opisano wpływ na regulację sytości i spowolnione opróżnianie żołądka. Receptor GIP powiązano ze zwiększonym wydzielaniem insuliny i możliwym łagodzeniem działań żołądkowo-jelitowych. Dodatkowe działanie na receptor glukagonu wiązano ze zwiększonym wydatkiem energetycznym wątroby i aktywacją brunatnej tkanki tłuszczowej.","evidenz":[{"art":"kliniczne","kurz":"W randomizowanym badaniu fazy 2 u dorosłych z otyłością istotnie większy odsetek uczestników przyjmujących retatrutyd osiągnął znaczną utratę masy ciała po 48 tygodniach w porównaniu z placebo.","kurz_en":"W randomizowanym badaniu fazy 2 u dorosłych z otyłością istotnie większy odsetek uczestników przyjmujących retatrutyd osiągnął znaczną utratę masy ciała po 48 tygodniach w porównaniu z placebo.","quelle":"Jastreboff AM et al. 2023, New England Journal of Medicine 389:514-526, PMID 37366315"},{"art":"kliniczne","kurz":"W podbadaniu z udziałem uczestników ze współistniejącą stłuszczeniową chorobą wątroby po 24 tygodniach zaobserwowano mierzone metodą MRI zmniejszenie zawartości tłuszczu w wątrobie, które rosło wraz z podawaną ilością.","kurz_en":"W podbadaniu z udziałem uczestników ze współistniejącą stłuszczeniową chorobą wątroby po 24 tygodniach zaobserwowano mierzone metodą MRI zmniejszenie zawartości tłuszczu w wątrobie, które rosło wraz z podawaną ilością.","quelle":"Sanyal AJ et al. 2024, Nature Medicine"},{"art":"kliniczne","kurz":"W badaniu fazy 2 u osób z cukrzycą typu 2 retatrutyd obniżał HbA1c bardziej niż aktywny komparator dulaglutyd, przy większej utracie masy ciała.","kurz_en":"W badaniu fazy 2 u osób z cukrzycą typu 2 retatrutyd obniżał HbA1c bardziej niż aktywny komparator dulaglutyd, przy większej utracie masy ciała.","quelle":"Rosenstock J et al. 2023, The Lancet 402:529-544, PMID 37385280"}],"sicherheit":["Najczęściej zgłaszane efekty w badaniach dotyczą układu pokarmowego, w tym nudności i biegunki, i zmniejszały się w trakcie badań.","Przy większej podawanej ilości w badaniach obserwowano wyższy odsetek przerwań leczenia niż w grupie placebo.","W badaniu fazy 3 niektórzy uczestnicy z grupy otrzymującej większą ilość zgłaszali dysestezję (mrowienie lub drętwienie kończyn), która w większości ustępowała w trakcie badania.","Ponieważ retatrutyd nie jest nigdzie zatwierdzony jako lek, nie istnieje oficjalna charakterystyka produktu dotycząca długoterminowego bezpieczeństwa."],"sicherheit_en":["Najczęściej zgłaszane efekty w badaniach dotyczą układu pokarmowego, w tym nudności i biegunki, i zmniejszały się w trakcie badań.","Przy większej podawanej ilości w badaniach obserwowano wyższy odsetek przerwań leczenia niż w grupie placebo.","W badaniu fazy 3 niektórzy uczestnicy z grupy otrzymującej większą ilość zgłaszali dysestezję (mrowienie lub drętwienie kończyn), która w większości ustępowała w trakcie badania.","Ponieważ retatrutyd nie jest nigdzie zatwierdzony jako lek, nie istnieje oficjalna charakterystyka produktu dotycząca długoterminowego bezpieczeństwa."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Retatrutyd jest substancją badaną i nie został dopuszczony do obrotu jako lek ani w UE, ani w Stanach Zjednoczonych. Producent, Eli Lilly, ogłosił 23 lipca 2026 r. wstępne wyniki (topline) fazy 3 i zapowiedział złożenie wniosku do FDA w 1. kwartale 2027 r. Złożenie wniosku nie jest dopuszczeniem do obrotu. Jest sprzedawany wyłącznie jako chemikalia badawcze.","rechtsstatus_en":"Retatrutyd jest substancją badaną i nie został dopuszczony do obrotu jako lek ani w UE, ani w Stanach Zjednoczonych. Producent, Eli Lilly, ogłosił 23 lipca 2026 r. wstępne wyniki (topline) fazy 3 i zapowiedział złożenie wniosku do FDA w 1. kwartale 2027 r. Złożenie wniosku nie jest dopuszczeniem do obrotu. Jest sprzedawany wyłącznie jako chemikalia badawcze.","typischeMg":[5,10,15],"faq":[{"q":"Czy retatrutyd jest już dostępny jako lek?","a":"Nie. Producent, Eli Lilly, ogłosił 23 lipca 2026 r. wstępne wyniki (topline) fazy 3 i zapowiedział złożenie wniosku do FDA w 1. kwartale 2027 r. Retatrutyd jest substancją badaną i obecnie nie jest zatwierdzonym lekiem.","q_en":"Czy retatrutyd jest już dostępny jako lek?","a_en":"Nie. Producent, Eli Lilly, ogłosił 23 lipca 2026 r. wstępne wyniki (topline) fazy 3 i zapowiedział złożenie wniosku do FDA w 1. kwartale 2027 r. Retatrutyd jest substancją badaną i obecnie nie jest zatwierdzonym lekiem."},{"q":"Czym retatrutyd różni się od semaglutydu?","a":"Semaglutyd działa tylko na receptor GLP-1, podczas gdy retatrutyd działa dodatkowo na receptory GIP i glukagonu. W badaniach klinicznych wykazano w konsekwencji większy wpływ na masę ciała i tłuszcz wątrobowy.","q_en":"Czym retatrutyd różni się od semaglutydu?","a_en":"Semaglutyd działa tylko na receptor GLP-1, podczas gdy retatrutyd działa dodatkowo na receptory GIP i glukagonu. W badaniach klinicznych wykazano w konsekwencji większy wpływ na masę ciała i tłuszcz wątrobowy."},{"q":"Skąd pochodzi retatrutyd?","a":"Retatrutyd został opracowany przez firmę farmaceutyczną Eli Lilly i jest badany w programie fazy 3 TRIUMPH, dla którego w 2026 r. ogłoszono wstępne wyniki (topline).","q_en":"Skąd pochodzi retatrutyd?","a_en":"Retatrutyd został opracowany przez firmę farmaceutyczną Eli Lilly i jest badany w programie fazy 3 TRIUMPH, dla którego w 2026 r. ogłoszono wstępne wyniki (topline)."}],"seo":{"title":"Retatrutyd: agonista potrójny, wyniki fazy 3 ogłoszone","title_en":"Retatrutyd: agonista potrójny, wyniki fazy 3 ogłoszone","description":"Retatrutyd w pigułce: mechanizm działania, status badań i profil bezpieczeństwa trójagonisty GLP-1/GIP/glukagon w zaawansowanych badaniach klinicznych.","description_en":"Retatrutyd w pigułce: mechanizm działania, status badań i profil bezpieczeństwa trójagonisty GLP-1/GIP/glukagon w zaawansowanych badaniach klinicznych."},"demo":false,"steckbrief":{"cas":"2381989-03-1","molekulargewicht":"~4600 g/mol","aminosaeuren":39,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":"rozpuszczalny w wodzie jałowej lub wodzie bakteriostatycznej","sequenzLaenge":39,"quellen":["chemverify Katalog 14.09.2026 (PubChem: kein Eintrag)"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit_en":"rozpuszczalny w wodzie jałowej lub wodzie bakteriostatycznej"},"verwandt":["semaglutid","tirzepatid","cagrilintid","survodutid"]},{"slug":"semaglutid","name":"Semaglutyd","synonyme":[],"kategorie":"Stoffwechsel","studienlage":"zugelassenes Arzneimittel","kurz":"Agonista receptora GLP-1, znany jako zatwierdzony lek i wymieniony tutaj jako substancja badawcza do regulacji metabolicznej.","kurz_en":"Agonista receptora GLP-1, znany jako zatwierdzony lek i wymieniony tutaj jako substancja badawcza do regulacji metabolicznej.","beschreibung":"Semaglutyd jest agonistą receptora GLP-1 zatwierdzonym jako lek pod wieloma nazwami handlowymi. Jest przedmiotem szeroko zakrojonych badań klinicznych dotyczących regulacji metabolicznej i sytości. Partie badawcze wymienione tutaj nie są równoważne zatwierdzonym lekom i przeznaczone są wyłącznie do użytku laboratoryjnego.","beschreibung_en":"Semaglutyd jest agonistą receptora GLP-1 zatwierdzonym jako lek pod wieloma nazwami handlowymi. Jest przedmiotem szeroko zakrojonych badań klinicznych dotyczących regulacji metabolicznej i sytości. Partie badawcze wymienione tutaj nie są równoważne zatwierdzonym lekom i przeznaczone są wyłącznie do użytku laboratoryjnego.","mechanismus":"Semaglutyd aktywuje receptor GLP-1, który wpływa na regulację apetytu w podwzgórzu, spowalnia opróżnianie żołądka i stymuluje uwalnianie insuliny w sposób zależny od glukozy. Działanie zależne od glukozy jest opisywane jako powód niższego ryzyka hipoglikemii w porównaniu do insuliny.","mechanismus_en":"Semaglutyd aktywuje receptor GLP-1, który wpływa na regulację apetytu w podwzgórzu, spowalnia opróżnianie żołądka i stymuluje uwalnianie insuliny w sposób zależny od glukozy. Działanie zależne od glukozy jest opisywane jako powód niższego ryzyka hipoglikemii w porównaniu do insuliny.","evidenz":[{"art":"kliniczne","kurz":"W badaniu randomizowanym z udziałem 1 961 dorosłych z nadwagą lub otyłością tygodniowe podawanie semaglutydu przez 68 tygodni prowadziło do średniej utraty masy ciała o 14,9 procent, wobec 2,4 procent w grupie placebo.","kurz_en":"W badaniu randomizowanym z udziałem 1 961 dorosłych z nadwagą lub otyłością tygodniowe podawanie semaglutydu przez 68 tygodni prowadziło do średniej utraty masy ciała o 14,9 procent, wobec 2,4 procent w grupie placebo.","quelle":"Wilding JPH et al. 2021, New England Journal of Medicine, PMID 33567185"},{"art":"kliniczne","kurz":"W badaniu dotyczącym wyników sercowo-naczyniowych z udziałem 3 297 osób z cukrzycą typu 2 i podwyższonym ryzykiem sercowo-naczyniowym semaglutyd wiązał się z niższą o 26 % częstością poważnych zdarzeń sercowo-naczyniowych w porównaniu z placebo.","kurz_en":"W badaniu dotyczącym wyników sercowo-naczyniowych z udziałem 3 297 osób z cukrzycą typu 2 i podwyższonym ryzykiem sercowo-naczyniowym semaglutyd wiązał się z niższą o 26 % częstością poważnych zdarzeń sercowo-naczyniowych w porównaniu z placebo.","quelle":"Marso SP et al. 2016, New England Journal of Medicine 375:1834-1844, PMID 27633186"}],"sicherheit":["Często zgłaszane działania to żołądkowo-jelitowe, zwłaszcza nudności, biegunka i wymioty, głównie przejściowe w trakcie stosowania.","Rzadkie przypadki omówione w literaturze obejmują możliwy związek z nietętniczą przednią niedokrwienną neuropatią nerwu wzrokowego.","Zgodnie z ChPL stosowanie jest przeciwwskazane u osób z rakiem rdzeniastym tarczycy w wywiadzie osobistym lub rodzinnym."],"sicherheit_en":["Często zgłaszane działania to żołądkowo-jelitowe, zwłaszcza nudności, biegunka i wymioty, głównie przejściowe w trakcie stosowania.","Rzadkie przypadki omówione w literaturze obejmują możliwy związek z nietętniczą przednią niedokrwienną neuropatią nerwu wzrokowego.","Zgodnie z ChPL stosowanie jest przeciwwskazane u osób z rakiem rdzeniastym tarczycy w wywiadzie osobistym lub rodzinnym."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Semaglutyd jest zatwierdzony jako lek pod nazwami Ozempic, Wegovy i Rybelsus w UE i Stanach Zjednoczonych do leczenia cukrzycy typu 2 oraz kontroli masy ciała i jest dostępny wyłącznie na receptę. Opisane tu partie badawcze nie są równoważne zatwierdzonym gotowym produktom farmaceutycznym.","rechtsstatus_en":"Semaglutyd jest zatwierdzony jako lek pod nazwami Ozempic, Wegovy i Rybelsus w UE i Stanach Zjednoczonych do leczenia cukrzycy typu 2 oraz kontroli masy ciała i jest dostępny wyłącznie na receptę. Opisane tu partie badawcze nie są równoważne zatwierdzonym gotowym produktom farmaceutycznym.","typischeMg":[2,5],"faq":[{"q":"Czy semaglutyd jest zatwierdzonym lekiem?","a":"Tak, semaglutyd jest zatwierdzony jako lek na receptę pod nazwami Ozempic, Wegovy i Rybelsus. Opisana tutaj substancja jest wyłącznie partią badawczą, a nie gotowym produktem farmaceutycznym.","q_en":"Czy semaglutyd jest zatwierdzonym lekiem?","a_en":"Tak, semaglutyd jest zatwierdzony jako lek na receptę pod nazwami Ozempic, Wegovy i Rybelsus. Opisana tutaj substancja jest wyłącznie partią badawczą, a nie gotowym produktem farmaceutycznym."},{"q":"Jak semaglutyd różni się od retatrutydu?","a":"Semaglutyd działa wyłącznie na receptor GLP-1, a retatrutyd działa dodatkowo na receptory GIP i glukagonu. Retatrutyd jest substancją badaną i nie został jeszcze dopuszczony do obrotu, podczas gdy semaglutyd już jest dopuszczony.","q_en":"Jak semaglutyd różni się od retatrutydu?","a_en":"Semaglutyd działa wyłącznie na receptor GLP-1, a retatrutyd działa dodatkowo na receptory GIP i glukagonu. Retatrutyd jest substancją badaną i nie został jeszcze dopuszczony do obrotu, podczas gdy semaglutyd już jest dopuszczony."},{"q":"Do czego służy semaglutyd jako lek?","a":"Jako zatwierdzony lek semaglutyd jest przepisywany w cukrzycy typu 2 i w kontroli masy ciała. Ta strona opisuje substancję wyłącznie jako związek badawczy do celów laboratoryjnych.","q_en":"Do czego służy semaglutyd jako lek?","a_en":"Jako zatwierdzony lek semaglutyd jest przepisywany w cukrzycy typu 2 i w kontroli masy ciała. Ta strona opisuje substancję wyłącznie jako związek badawczy do celów laboratoryjnych."}],"seo":{"title":"Semaglutyd: związek GLP-1 w kontekście badawczym","title_en":"Semaglutyd: związek GLP-1 w kontekście badawczym","description":"Semaglutyd w pigułce: mechanizm działania, status badań, profil bezpieczeństwa i status prawny zatwierdzonego agonisty receptora GLP-1.","description_en":"Semaglutyd w pigułce: mechanizm działania, status badań, profil bezpieczeństwa i status prawny zatwierdzonego agonisty receptora GLP-1."},"demo":false,"steckbrief":{"cas":"910463-68-2","molekulargewicht":"4114 g/mol","aminosaeuren":31,"halbwertszeit":"≈ 1 tydzień (eliminacja, ChPL Ozempic)","reinheitsstandard":"≥ 99 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":31,"quellen":["PubChem CID 56843331","DailyMed SPL OZEMPIC (Semaglutid), Novo Nordisk","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 1 tydzień (eliminacja, ChPL Ozempic)","reinheitsstandard_en":"≥ 99 % (HPLC, standard handlowy)"},"verwandt":["tirzepatid","retatrutid","survodutid","cagrilintid"]},{"slug":"survodutid","name":"Survodutyd","synonyme":["BI 456906"],"kategorie":"Stoffwechsel","studienlage":"klinisch untersucht","kurz":"Peptyd działający jednocześnie na receptory GLP-1 i glukagonu, obecnie w zaawansowanych badaniach klinicznych związanych z regulacją metaboliczną.","kurz_en":"Peptyd działający jednocześnie na receptory GLP-1 i glukagonu, obecnie w zaawansowanych badaniach klinicznych związanych z regulacją metaboliczną.","beschreibung":"Survodutyd jest podwójnym agonistą receptorów GLP-1 i glukagonu, opracowanym przez Boehringer Ingelheim we współpracy z Zealand Pharma. Jest badany w badaniach fazy 3 pod kątem regulacji masy ciała w otyłości, a także w stłuszczeniowym zapaleniu wątroby związanym z dysfunkcją metaboliczną (MASH), i do tej pory nie jest zatwierdzony jako lek w żadnym kraju.","beschreibung_en":"Survodutyd jest podwójnym agonistą receptorów GLP-1 i glukagonu, opracowanym przez Boehringer Ingelheim we współpracy z Zealand Pharma. Jest badany w badaniach fazy 3 pod kątem regulacji masy ciała w otyłości, a także w stłuszczeniowym zapaleniu wątroby związanym z dysfunkcją metaboliczną (MASH), i do tej pory nie jest zatwierdzony jako lek w żadnym kraju.","mechanismus":"Poprzez receptor GLP-1 opisano zwiększone uczucie sytości i spowolnione opróżnianie żołądka. Dodatkowa aktywacja receptora glukagonu została powiązana ze zwiększonym wydatkiem energetycznym wątroby i redukcją zawartości tłuszczu wątrobowego. To podwójne działanie odróżnia survodutyd od czystych agonistów GLP-1.","mechanismus_en":"Poprzez receptor GLP-1 opisano zwiększone uczucie sytości i spowolnione opróżnianie żołądka. Dodatkowa aktywacja receptora glukagonu została powiązana ze zwiększonym wydatkiem energetycznym wątroby i redukcją zawartości tłuszczu wątrobowego. To podwójne działanie odróżnia survodutyd od czystych agonistów GLP-1.","evidenz":[{"art":"kliniczne","kurz":"W randomizowanym badaniu fazy 3 z udziałem 725 dorosłych z otyłością bez cukrzycy survodutyd doprowadził po 76 tygodniach do średniej utraty masy ciała o 12-13 procent, w porównaniu z 5 procentami w grupie placebo.","kurz_en":"W randomizowanym badaniu fazy 3 z udziałem 725 dorosłych z otyłością bez cukrzycy survodutyd doprowadził po 76 tygodniach do średniej utraty masy ciała o 12-13 procent, w porównaniu z 5 procentami w grupie placebo.","quelle":"Le Roux CW et al. 2026, New England Journal of Medicine, DOI 10.1056/NEJMoa2600751"},{"art":"kliniczne","kurz":"W randomizowanym badaniu fazy 2 z udziałem 386 dorosłych z otyłością survodutyd doprowadził po 46 tygodniach do utraty masy ciała do 14,9 procent w grupie z najwyższą ilością, w porównaniu z 2,8 procent w grupie placebo.","kurz_en":"W randomizowanym badaniu fazy 2 z udziałem 386 dorosłych z otyłością survodutyd doprowadził po 46 tygodniach do utraty masy ciała do 14,9 procent w grupie z najwyższą ilością, w porównaniu z 2,8 procent w grupie placebo.","quelle":"le Roux CW et al. 2024, The Lancet Diabetes & Endocrinology 12:162-173, PMID 38330987"},{"art":"kliniczne","kurz":"W badaniu fazy 2 z udziałem 293 osób z MASH i zwłóknieniem wątroby u nawet 62 procent uczestników przyjmujących survodutyd po 48 tygodniach stwierdzono poprawę histologiczną MASH bez pogorszenia zwłóknienia, w porównaniu z 14 procentami w grupie placebo.","kurz_en":"W badaniu fazy 2 z udziałem 293 osób z MASH i zwłóknieniem wątroby u nawet 62 procent uczestników przyjmujących survodutyd po 48 tygodniach stwierdzono poprawę histologiczną MASH bez pogorszenia zwłóknienia, w porównaniu z 14 procentami w grupie placebo.","quelle":"Sanyal AJ et al. 2024, New England Journal of Medicine, PMID 38847460"}],"sicherheit":["Najczęściej zgłaszane działania w badaniach dotyczą układu pokarmowego, w tym nudności, biegunka i wymioty, występujące wyraźnie częściej po survodutydzie niż po placebo.","W badaniu fazy 3 w otyłości objawy żołądkowo-jelitowe zgłaszało do 90 procent uczestników przyjmujących survodutyd, w porównaniu z 48 procentami w grupie placebo, głównie łagodne do umiarkowanych.","W badaniu fazy 2 w MASH odnotowano poważne zdarzenia niepożądane u 8 procent uczestników przyjmujących survodutyd i u 7 procent w grupie placebo.","Ponieważ survodutyd nie jest nigdzie zatwierdzony jako lek, nie istnieje oficjalna charakterystyka produktu dotycząca długoterminowego bezpieczeństwa."],"sicherheit_en":["Najczęściej zgłaszane działania w badaniach dotyczą układu pokarmowego, w tym nudności, biegunka i wymioty, występujące wyraźnie częściej po survodutydzie niż po placebo.","W badaniu fazy 3 w otyłości objawy żołądkowo-jelitowe zgłaszało do 90 procent uczestników przyjmujących survodutyd, w porównaniu z 48 procentami w grupie placebo, głównie łagodne do umiarkowanych.","W badaniu fazy 2 w MASH odnotowano poważne zdarzenia niepożądane u 8 procent uczestników przyjmujących survodutyd i u 7 procent w grupie placebo.","Ponieważ survodutyd nie jest nigdzie zatwierdzony jako lek, nie istnieje oficjalna charakterystyka produktu dotycząca długoterminowego bezpieczeństwa."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Survodutyd jest obecnie w badaniach fazy 3 w otyłości i MASH i nie został jeszcze zatwierdzony jako lek w UE ani w Stanach Zjednoczonych. Według producenta zatwierdzenie przez FDA jest spodziewane najwcześniej w 2027 roku; jest sprzedawany wyłącznie jako odczynnik badawczy.","rechtsstatus_en":"Survodutyd jest obecnie w badaniach fazy 3 w otyłości i MASH i nie został jeszcze zatwierdzony jako lek w UE ani w Stanach Zjednoczonych. Według producenta zatwierdzenie przez FDA jest spodziewane najwcześniej w 2027 roku; jest sprzedawany wyłącznie jako odczynnik badawczy.","typischeMg":[5,10,20],"faq":[{"q":"Czy survodutyd jest już dostępny jako lek?","a":"Nie. Survodutyd jest obecnie w badaniach fazy 3; według producenta zatwierdzenie przez FDA jest spodziewane najwcześniej w 2027 roku. Obecnie nie jest to zatwierdzony lek.","q_en":"Czy survodutyd jest już dostępny jako lek?","a_en":"Nie. Survodutyd jest obecnie w badaniach fazy 3; według producenta zatwierdzenie przez FDA jest spodziewane najwcześniej w 2027 roku. Obecnie nie jest to zatwierdzony lek."},{"q":"Co odróżnia survodutyd od semaglutydu?","a":"Semaglutyd działa tylko na receptor GLP-1, podczas gdy survodutyd dodatkowo działa na receptor glukagonu. Badania kliniczne wykazały, że to podwójne działanie zmniejsza zawartość tłuszczu wątrobowego obok wpływu na masę ciała.","q_en":"Co odróżnia survodutyd od semaglutydu?","a_en":"Semaglutyd działa tylko na receptor GLP-1, podczas gdy survodutyd dodatkowo działa na receptor glukagonu. Badania kliniczne wykazały, że to podwójne działanie zmniejsza zawartość tłuszczu wątrobowego obok wpływu na masę ciała."},{"q":"Skąd pochodzi survodutyd?","a":"Survodutyd został opracowany przez firmę farmaceutyczną Boehringer Ingelheim i jest badany w kilku badaniach fazy 3 w ramach programu SYNCHRONIZE, częściowo we współpracy z Zealand Pharma.","q_en":"Skąd pochodzi survodutyd?","a_en":"Survodutyd został opracowany przez firmę farmaceutyczną Boehringer Ingelheim i jest badany w kilku badaniach fazy 3 w ramach programu SYNCHRONIZE, częściowo we współpracy z Zealand Pharma."}],"seo":{"title":"Survodutyd: podwójny agonista w badaniach fazy 3","title_en":"Survodutyd: podwójny agonista w badaniach fazy 3","description":"Survodutyd w pigułce: mechanizm, status badań i profil bezpieczeństwa podwójnego agonisty GLP-1/glukagonu w zaawansowanych badaniach klinicznych.","description_en":"Survodutyd w pigułce: mechanizm, status badań i profil bezpieczeństwa podwójnego agonisty GLP-1/glukagonu w zaawansowanych badaniach klinicznych."},"demo":false,"steckbrief":{"cas":"2805997-46-8","molekulargewicht":"4232 g/mol","aminosaeuren":null,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":null,"quellen":["PubChem CID 171378821","chemverify Katalog 14.09.2026 (Aminosäurenzahl/Reinheitsstandard dort nicht geführt)"]},"verwandt":["semaglutid","tirzepatid","retatrutid","cagrilintid"]},{"slug":"tirzepatid","name":"Tirzepatyd","synonyme":["LY3298176"],"kategorie":"Stoffwechsel","studienlage":"zugelassenes Arzneimittel","kurz":"Podwójny agonista receptorów GIP/GLP-1, znany jako zatwierdzony lek i wymieniony tu jako substancja badawcza do regulacji metabolicznej.","kurz_en":"Podwójny agonista receptorów GIP/GLP-1, znany jako zatwierdzony lek i wymieniony tu jako substancja badawcza do regulacji metabolicznej.","beschreibung":"Tirzepatyd jest podwójnym agonistą receptorów GIP/GLP-1 zatwierdzonym jako lek pod nazwami Mounjaro i Zepbound. Jest przedmiotem szeroko zakrojonych badań klinicznych dotyczących regulacji metabolicznej i masy ciała w cukrzycy typu 2 i otyłości. Partie badawcze wymienione tutaj nie są równoważne zatwierdzonym lekom i przeznaczone są wyłącznie do użytku laboratoryjnego.","beschreibung_en":"Tirzepatyd jest podwójnym agonistą receptorów GIP/GLP-1 zatwierdzonym jako lek pod nazwami Mounjaro i Zepbound. Jest przedmiotem szeroko zakrojonych badań klinicznych dotyczących regulacji metabolicznej i masy ciała w cukrzycy typu 2 i otyłości. Partie badawcze wymienione tutaj nie są równoważne zatwierdzonym lekom i przeznaczone są wyłącznie do użytku laboratoryjnego.","mechanismus":"Tirzepatyd aktywuje jednocześnie receptor GIP i receptor GLP-1, dlatego opisuje się go jako podwójnego agonistę. Poprzez receptor GLP-1 opisano wpływ na regulację sytości w podwzgórzu, spowolnione opróżnianie żołądka i zależne od glukozy uwalnianie insuliny. Dodatkowy składnik, receptor GIP, powiązano ze zwiększonym wydzielaniem insuliny i wpływem na metabolizm lipidów.","mechanismus_en":"Tirzepatyd aktywuje jednocześnie receptor GIP i receptor GLP-1, dlatego opisuje się go jako podwójnego agonistę. Poprzez receptor GLP-1 opisano wpływ na regulację sytości w podwzgórzu, spowolnione opróżnianie żołądka i zależne od glukozy uwalnianie insuliny. Dodatkowy składnik, receptor GIP, powiązano ze zwiększonym wydzielaniem insuliny i wpływem na metabolizm lipidów.","evidenz":[{"art":"kliniczne","kurz":"W randomizowanym badaniu z udziałem 2 539 dorosłych z otyłością lub nadwagą cotygodniowe podawanie tirzepatydu przez 72 tygodnie doprowadziło do średniej utraty masy ciała do 20,9 procent (15 mg) w porównaniu z 3,1 procent w grupie placebo.","kurz_en":"W randomizowanym badaniu z udziałem 2 539 dorosłych z otyłością lub nadwagą cotygodniowe podawanie tirzepatydu przez 72 tygodnie doprowadziło do średniej utraty masy ciała do 20,9 procent (15 mg) w porównaniu z 3,1 procent w grupie placebo.","quelle":"Jastreboff AM et al. 2022, New England Journal of Medicine, PMID 35658024"},{"art":"kliniczne","kurz":"W randomizowanym badaniu bezpośrednio porównującym leczenie u 1 879 osób z cukrzycą typu 2 po 40 tygodniach obserwowano przy tirzepatydzie spadek HbA1c o 2,09 do 2,46 punktu procentowego i masy ciała o 7,8 do 12,4 kg, w obu przypadkach większy niż przy semaglutydzie 1 mg.","kurz_en":"W randomizowanym badaniu bezpośrednio porównującym leczenie u 1 879 osób z cukrzycą typu 2 po 40 tygodniach obserwowano przy tirzepatydzie spadek HbA1c o 2,09 do 2,46 punktu procentowego i masy ciała o 7,8 do 12,4 kg, w obu przypadkach większy niż przy semaglutydzie 1 mg.","quelle":"Frías JP et al. 2021, New England Journal of Medicine, PMID 34170647"}],"sicherheit":["Najczęściej zgłaszane działania to żołądkowo-jelitowe, zwłaszcza nudności, wymioty i biegunka, z ryzykiem odwodnienia w nasilonych przypadkach.","Zgodnie z ChPL stosowanie jest przeciwwskazane u osób z rakiem rdzeniastym tarczycy w wywiadzie osobistym lub rodzinnym albo z zespołem mnogich nowotworów wewnątrzwydzielniczych typu 2.","Badania na szczurach wykazały guzy komórek C tarczycy zależne od ilości i czasu ekspozycji; według ChPL nie ustalono, czy ten wynik przekłada się na ludzi."],"sicherheit_en":["Najczęściej zgłaszane działania to żołądkowo-jelitowe, zwłaszcza nudności, wymioty i biegunka, z ryzykiem odwodnienia w nasilonych przypadkach.","Zgodnie z ChPL stosowanie jest przeciwwskazane u osób z rakiem rdzeniastym tarczycy w wywiadzie osobistym lub rodzinnym albo z zespołem mnogich nowotworów wewnątrzwydzielniczych typu 2.","Badania na szczurach wykazały guzy komórek C tarczycy zależne od ilości i czasu ekspozycji; według ChPL nie ustalono, czy ten wynik przekłada się na ludzi."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Tirzepatyd jest zatwierdzony jako lek pod nazwą Mounjaro w UE od września 2022 roku do leczenia cukrzycy typu 2, a od końca 2023 roku także do kontroli masy ciała. W Stanach Zjednoczonych jest zatwierdzony pod nazwą Mounjaro do leczenia cukrzycy typu 2 i pod nazwą Zepbound do kontroli masy ciała i w obu regionach jest dostępny wyłącznie na receptę. Opisane tu partie badawcze nie są równoważne zatwierdzonym gotowym produktom farmaceutycznym.","rechtsstatus_en":"Tirzepatyd jest zatwierdzony jako lek pod nazwą Mounjaro w UE od września 2022 roku do leczenia cukrzycy typu 2, a od końca 2023 roku także do kontroli masy ciała. W Stanach Zjednoczonych jest zatwierdzony pod nazwą Mounjaro do leczenia cukrzycy typu 2 i pod nazwą Zepbound do kontroli masy ciała i w obu regionach jest dostępny wyłącznie na receptę. Opisane tu partie badawcze nie są równoważne zatwierdzonym gotowym produktom farmaceutycznym.","typischeMg":[10,30,60],"faq":[{"q":"Czy tirzepatyd jest zatwierdzonym lekiem?","a":"Tak, tirzepatyd jest zatwierdzony jako lek wydawany na receptę pod nazwami Mounjaro i Zepbound. Opisana tutaj substancja jest wyłącznie partią badawczą, a nie gotowym produktem farmaceutycznym.","q_en":"Czy tirzepatyd jest zatwierdzonym lekiem?","a_en":"Tak, tirzepatyd jest zatwierdzony jako lek wydawany na receptę pod nazwami Mounjaro i Zepbound. Opisana tutaj substancja jest wyłącznie partią badawczą, a nie gotowym produktem farmaceutycznym."},{"q":"Jak tirzepatyd różni się od semaglutydu?","a":"Semaglutyd działa tylko na receptor GLP-1, podczas gdy tirzepatyd dodatkowo działa na receptor GIP. W badaniu porównawczym tirzepatyd wykazał większe działanie na HbA1c i masę ciała niż semaglutyd.","q_en":"Jak tirzepatyd różni się od semaglutydu?","a_en":"Semaglutyd działa tylko na receptor GLP-1, podczas gdy tirzepatyd dodatkowo działa na receptor GIP. W badaniu porównawczym tirzepatyd wykazał większe działanie na HbA1c i masę ciała niż semaglutyd."},{"q":"Do czego stosuje się tirzepatyd jako lek?","a":"Jako zatwierdzony lek, tirzepatyd jest przepisywany na cukrzycę typu 2 i kontrolę masy ciała. Ta strona opisuje substancję wyłącznie jako związek badawczy do celów laboratoryjnych.","q_en":"Do czego stosuje się tirzepatyd jako lek?","a_en":"Jako zatwierdzony lek, tirzepatyd jest przepisywany na cukrzycę typu 2 i kontrolę masy ciała. Ta strona opisuje substancję wyłącznie jako związek badawczy do celów laboratoryjnych."}],"seo":{"title":"Tirzepatyd: przegląd związku o podwójnym działaniu GIP/GLP-1","title_en":"Tirzepatyd: przegląd związku o podwójnym działaniu GIP/GLP-1","description":"Tirzepatyd w pigułce: podwójny mechanizm działania GIP/GLP-1, dowody z badań SURMOUNT i SURPASS, profil bezpieczeństwa i status prawny związku.","description_en":"Tirzepatyd w pigułce: podwójny mechanizm działania GIP/GLP-1, dowody z badań SURMOUNT i SURPASS, profil bezpieczeństwa i status prawny związku."},"demo":false,"steckbrief":{"cas":"2023788-19-2","molekulargewicht":"4813 g/mol","aminosaeuren":39,"halbwertszeit":"≈ 5 dni (eliminacja, ChPL Mounjaro)","reinheitsstandard":"≥ 99 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":39,"quellen":["PubChem CID 166567236","DailyMed SPL MOUNJARO (Tirzepatid), Eli Lilly and Company","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 5 dni (eliminacja, ChPL Mounjaro)","reinheitsstandard_en":"≥ 99 % (HPLC, standard handlowy)"},"verwandt":["semaglutid","retatrutid","cagrilintid","survodutid"]},{"slug":"cjc-1295","name":"CJC-1295","synonyme":["Mod GRF 1-29","Modified GRF (1-29)","CJC-1295 z DAC","DAC:GRF"],"kategorie":"Wachstumshormon-Achse","studienlage":"frühe klinische Studien","kurz":"Syntetyczny analog hormonu uwalniającego hormon wzrostu, badany w dwóch wariantach o różnym czasie działania.","kurz_en":"Syntetyczny analog hormonu uwalniającego hormon wzrostu, badany w dwóch wariantach o różnym czasie działania.","beschreibung":"CJC-1295 to stabilizowany analog własnego GHRH organizmu, badany w kontekście osi hormonu wzrostu. Występuje w dwóch wariantach: bez DAC (Drug Affinity Complex), o krótkim czasie działania, oraz z DAC, który dzięki wiązaniu z albuminą surowicy znacznie wydłuża czas działania. Dostępne dane z badań na ludziach pochodzą głównie z wczesnych badań klinicznych u zdrowych dorosłych.","beschreibung_en":"CJC-1295 to stabilizowany analog własnego GHRH organizmu, badany w kontekście osi hormonu wzrostu. Występuje w dwóch wariantach: bez DAC (Drug Affinity Complex), o krótkim czasie działania, oraz z DAC, który dzięki wiązaniu z albuminą surowicy znacznie wydłuża czas działania. Dostępne dane z badań na ludziach pochodzą głównie z wczesnych badań klinicznych u zdrowych dorosłych.","mechanismus":"CJC-1295 wiąże się z receptorem GHRH na komórkach somatotropowych w przysadce mózgowej, wywołując pulsacyjne wydzielanie własnego hormonu wzrostu przez organizm. Bez DAC cząsteczka jest rozkładana w ciągu minut, co daje krótki, wyraźny impuls hormonalny. Z DAC chemiczna kotwica wiąże się kowalencyjnie z albuminą we krwi, wydłużając czas działania do kilku dni, a badania wskazują, że wzorzec pulsacyjnego uwalniania zostaje zachowany.","mechanismus_en":"CJC-1295 wiąże się z receptorem GHRH na komórkach somatotropowych w przysadce mózgowej, wywołując pulsacyjne wydzielanie własnego hormonu wzrostu przez organizm. Bez DAC cząsteczka jest rozkładana w ciągu minut, co daje krótki, wyraźny impuls hormonalny. Z DAC chemiczna kotwica wiąże się kowalencyjnie z albuminą we krwi, wydłużając czas działania do kilku dni, a badania wskazują, że wzorzec pulsacyjnego uwalniania zostaje zachowany.","evidenz":[{"art":"kliniczne","kurz":"Dwa randomizowane badania kontrolowane placebo u zdrowych dorosłych, ze stopniowo zwiększanymi ilościami: pojedynczy zastrzyk CJC-1295 z DAC podnosił poziom hormonu wzrostu przez kilka dni, a poziom IGF-1 przez 9-11 dni.","kurz_en":"Dwa randomizowane badania kontrolowane placebo u zdrowych dorosłych, ze stopniowo zwiększanymi ilościami: pojedynczy zastrzyk CJC-1295 z DAC podnosił poziom hormonu wzrostu przez kilka dni, a poziom IGF-1 przez 9-11 dni.","quelle":"Teichman et al. 2006, Journal of Clinical Endocrinology & Metabolism, PMID 16352683"},{"art":"kliniczne","kurz":"Analiza uzupełniająca tych samych uczestników wykazała, że pulsacyjne wydzielanie hormonu wzrostu zostało zachowane nawet przy przedłużonej stymulacji CJC-1295 z DAC.","kurz_en":"Analiza uzupełniająca tych samych uczestników wykazała, że pulsacyjne wydzielanie hormonu wzrostu zostało zachowane nawet przy przedłużonej stymulacji CJC-1295 z DAC.","quelle":"Ionescu & Frohman 2006, Journal of Clinical Endocrinology & Metabolism, PMID 17018654"}],"sicherheit":["W dostępnych badaniach zgłaszano głównie łagodne, lokalne reakcje w miejscu wstrzyknięcia.","Badanie fazy 2 z CJC-1295 z DAC w niezwiązanym wskazaniu przerwano prewencyjnie po śmierci uczestnika; związku przyczynowego z peptydem nie ustalono.","Długoterminowe skutki stale podwyższonego poziomu IGF-1 u ludzi nie są w pełni poznane.","Długoterminowe dane dotyczące bezpieczeństwa u ludzi nie są jeszcze dostępne."],"sicherheit_en":["W dostępnych badaniach zgłaszano głównie łagodne, lokalne reakcje w miejscu wstrzyknięcia.","Badanie fazy 2 z CJC-1295 z DAC w niezwiązanym wskazaniu przerwano prewencyjnie po śmierci uczestnika; związku przyczynowego z peptydem nie ustalono.","Długoterminowe skutki stale podwyższonego poziomu IGF-1 u ludzi nie są w pełni poznane.","Długoterminowe dane dotyczące bezpieczeństwa u ludzi nie są jeszcze dostępne."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"CJC-1295 nie jest zatwierdzony jako lek w UE ani w USA. Jest sprzedawany wyłącznie jako odczynnik badawczy i nie jest przeznaczony do stosowania u ludzi.","rechtsstatus_en":"CJC-1295 nie jest zatwierdzony jako lek w UE ani w USA. Jest sprzedawany wyłącznie jako odczynnik badawczy i nie jest przeznaczony do stosowania u ludzi.","typischeMg":[2,5],"faq":[{"q":"Jaka jest różnica między CJC-1295 z a bez DAC","a":"Bez DAC peptyd jest rozkładany w ciągu minut, co daje krótki, wyraźny impuls hormonalny. Z DAC chemiczna kotwica wiąże się z albuminą we krwi, wydłużając czas działania do kilku dni, a badania wskazują, że wzorzec pulsacyjnego uwalniania zostaje zachowany.","q_en":"Jaka jest różnica między CJC-1295 z a bez DAC","a_en":"Bez DAC peptyd jest rozkładany w ciągu minut, co daje krótki, wyraźny impuls hormonalny. Z DAC chemiczna kotwica wiąże się z albuminą we krwi, wydłużając czas działania do kilku dni, a badania wskazują, że wzorzec pulsacyjnego uwalniania zostaje zachowany."},{"q":"Czy CJC-1295 jest zatwierdzonym lekiem","a":"Nie. CJC-1295 nie jest zatwierdzony jako lek w UE ani w USA i jest sprzedawany wyłącznie jako odczynnik badawczy do użytku laboratoryjnego.","q_en":"Czy CJC-1295 jest zatwierdzonym lekiem","a_en":"Nie. CJC-1295 nie jest zatwierdzony jako lek w UE ani w USA i jest sprzedawany wyłącznie jako odczynnik badawczy do użytku laboratoryjnego."},{"q":"W jakim celu bada się CJC-1295","a":"CJC-1295 jest badany w kontekście osi hormonu wzrostu, zwłaszcza w odniesieniu do własnego wydzielania hormonu wzrostu przez organizm i wynikającego z tego wytwarzania IGF-1 w wątrobie.","q_en":"W jakim celu bada się CJC-1295","a_en":"CJC-1295 jest badany w kontekście osi hormonu wzrostu, zwłaszcza w odniesieniu do własnego wydzielania hormonu wzrostu przez organizm i wynikającego z tego wytwarzania IGF-1 w wątrobie."}],"seo":{"title":"Przegląd badań: CJC-1295","title_en":"Przegląd badań: CJC-1295","description":"CJC-1295 przedstawiony rzeczowo: mechanizm działania, różnica między wariantem z DAC i bez DAC, dane z badań i status prawny tego analogu GHRH.","description_en":"CJC-1295 przedstawiony rzeczowo: mechanizm działania, różnica między wariantem z DAC i bez DAC, dane z badań i status prawny tego analogu GHRH."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":null,"aminosaeuren":null,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":null,"quellen":["chemverify Katalog 14.09.2026 (Eintrag deckt CJC-1295 mit und ohne DAC generisch ab, CAS/Molekulargewicht nicht eindeutig einer Variante zuordenbar)"]},"verwandt":["ipamorelin","sermorelin","tesamorelin","igf-1-lr3"]},{"slug":"hexarelin","name":"Hexarelin","synonyme":[],"kategorie":"Wachstumshormon-Achse","studienlage":"frühe klinische Studien","kurz":"Syntetyczny heksapeptyd z klasy peptydów uwalniających hormon wzrostu, badany we wczesnych badaniach klinicznych dotyczących wydzielania hormonu wzrostu.","kurz_en":"Syntetyczny heksapeptyd z klasy peptydów uwalniających hormon wzrostu, badany we wczesnych badaniach klinicznych dotyczących wydzielania hormonu wzrostu.","beschreibung":"Hexarelin to syntetyczny heksapeptyd z klasy GHRP (peptyd uwalniający hormon wzrostu), po raz pierwszy opisany farmakologicznie w 1994 roku. Był badany w badaniach klinicznych nad wydzielaniem hormonu wzrostu u dzieci, dorosłych i osób starszych, a osobno w badaniach przedklinicznych dotyczących wpływu na serce.","beschreibung_en":"Hexarelin to syntetyczny heksapeptyd z klasy GHRP (peptyd uwalniający hormon wzrostu), po raz pierwszy opisany farmakologicznie w 1994 roku. Był badany w badaniach klinicznych nad wydzielaniem hormonu wzrostu u dzieci, dorosłych i osób starszych, a osobno w badaniach przedklinicznych dotyczących wpływu na serce.","mechanismus":"Hexarelin wiąże się z receptorem ghreliny (GHS-R1a) w podwzgórzu i przysadce mózgowej, wywołując pulsacyjne uwalnianie własnego hormonu wzrostu organizmu. W przeciwieństwie do bardziej selektywnych peptydów tej samej klasy, takich jak ipamorelin, hexarelin w badaniach wykazywał istotne dodatkowe uwalnianie ACTH i kortyzolu. Badania przedkliniczne opisują także niezależne od hormonu wzrostu wiązanie z receptorami GHS-R1a w sercu.","mechanismus_en":"Hexarelin wiąże się z receptorem ghreliny (GHS-R1a) w podwzgórzu i przysadce mózgowej, wywołując pulsacyjne uwalnianie własnego hormonu wzrostu organizmu. W przeciwieństwie do bardziej selektywnych peptydów tej samej klasy, takich jak ipamorelin, hexarelin w badaniach wykazywał istotne dodatkowe uwalnianie ACTH i kortyzolu. Badania przedkliniczne opisują także niezależne od hormonu wzrostu wiązanie z receptorami GHS-R1a w sercu.","evidenz":[{"art":"przedkliniczne","kurz":"W badaniach na noworodkowych i dorosłych szczurach hexarelin wywoływał wyraźne i długotrwałe uwalnianie hormonu wzrostu i był skuteczniejszy niż pokrewny peptyd GHRP-6 przy podaniu podskórnym.","kurz_en":"W badaniach na noworodkowych i dorosłych szczurach hexarelin wywoływał wyraźne i długotrwałe uwalnianie hormonu wzrostu i był skuteczniejszy niż pokrewny peptyd GHRP-6 przy podaniu podskórnym.","quelle":"Deghenghi R et al. 1994, Life Sciences, Bd. 54(18), S. 1321-1328, PMID 7910650"},{"art":"kliniczne","kurz":"W badaniu 60 osób w wieku od 5 do 81 lat porównano odpowiedź hormonu wzrostu na hexarelin u dzieci przedpubertycznych i pubertycznych, młodych dorosłych i osób starszych, z wyraźnie słabszą odpowiedzią u dzieci przedpubertycznych i starszych uczestników.","kurz_en":"W badaniu 60 osób w wieku od 5 do 81 lat porównano odpowiedź hormonu wzrostu na hexarelin u dzieci przedpubertycznych i pubertycznych, młodych dorosłych i osób starszych, z wyraźnie słabszą odpowiedzią u dzieci przedpubertycznych i starszych uczestników.","quelle":"Arvat E et al. 1997, European Journal of Endocrinology, Bd. 137(6), PMID 9437229"},{"art":"kliniczne","kurz":"W badaniu na 15 zdrowych mężczyznach hexarelin zwiększał ACTH i kortyzol, a efekt ten nasilała desmopresyna (analog wazopresyny), co sugeruje udział wazopresyny w tym działaniu niepożądanym.","kurz_en":"W badaniu na 15 zdrowych mężczyznach hexarelin zwiększał ACTH i kortyzol, a efekt ten nasilała desmopresyna (analog wazopresyny), co sugeruje udział wazopresyny w tym działaniu niepożądanym.","quelle":"Korbonits M et al. 1999, Journal of Clinical Endocrinology & Metabolism, Bd. 84(7), S. 2489-2495, PMID 10404825"},{"art":"przedkliniczne","kurz":"W modelu szczurzym hexarelin wykazywał działanie ochronne na serce po niedokrwieniu i reperfuzji, niezależne od aktywności hormonu wzrostu, i przypisywano je bezpośredniemu wiązaniu z receptorami w sercu.","kurz_en":"W modelu szczurzym hexarelin wykazywał działanie ochronne na serce po niedokrwieniu i reperfuzji, niezależne od aktywności hormonu wzrostu, i przypisywano je bezpośredniemu wiązaniu z receptorami w sercu.","quelle":"Locatelli V et al. 1999, Endocrinology, Bd. 140(9), S. 4024-4031, PMID 10465272"}],"sicherheit":["W badaniach klinicznych hexarelin wywoływał nie tylko uwalnianie hormonu wzrostu, ale także istotne uwalnianie ACTH, kortyzolu i prolaktyny, czego w takim stopniu nie obserwowano przy bardziej selektywnych GHRP, takich jak ipamorelin.","Odpowiedź hormonu wzrostu na hexarelin jest wyraźnie słabsza u dzieci przedpubertycznych i osób starszych niż u nastolatków i młodych dorosłych.","Niezależne dane dotyczące bezpieczeństwa w długim okresie u zdrowych dorosłych poza kontrolowanymi krótkoterminowymi badaniami nie są dostępne.","Interakcje z innymi osiami hormonalnymi, zwłaszcza z osią podwzgórze-przysadka-nadnercza, nie zostały rozstrzygająco zbadane."],"sicherheit_en":["W badaniach klinicznych hexarelin wywoływał nie tylko uwalnianie hormonu wzrostu, ale także istotne uwalnianie ACTH, kortyzolu i prolaktyny, czego w takim stopniu nie obserwowano przy bardziej selektywnych GHRP, takich jak ipamorelin.","Odpowiedź hormonu wzrostu na hexarelin jest wyraźnie słabsza u dzieci przedpubertycznych i osób starszych niż u nastolatków i młodych dorosłych.","Niezależne dane dotyczące bezpieczeństwa w długim okresie u zdrowych dorosłych poza kontrolowanymi krótkoterminowymi badaniami nie są dostępne.","Interakcje z innymi osiami hormonalnymi, zwłaszcza z osią podwzgórze-przysadka-nadnercza, nie zostały rozstrzygająco zbadane."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Hexarelin nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych i jest sprzedawany wyłącznie jako odczynnik badawczy do celów laboratoryjnych.","rechtsstatus_en":"Hexarelin nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych i jest sprzedawany wyłącznie jako odczynnik badawczy do celów laboratoryjnych.","typischeMg":[2,5],"faq":[{"q":"Czy hexarelin różni się od ipamorelinu","a":"Tak. Oba wiążą się z tym samym receptorem ghreliny, ale hexarelin wykazał dodatkowo istotne uwalnianie ACTH i kortyzolu w badaniach, podczas gdy ipamorelin jest uważany za bardziej selektywny dla osi hormonu wzrostu.","q_en":"Czy hexarelin różni się od ipamorelinu","a_en":"Tak. Oba wiążą się z tym samym receptorem ghreliny, ale hexarelin wykazał dodatkowo istotne uwalnianie ACTH i kortyzolu w badaniach, podczas gdy ipamorelin jest uważany za bardziej selektywny dla osi hormonu wzrostu."},{"q":"Czy hexarelin był badany u dzieci","a":"Hexarelin był stosowany w badaniach klinicznych dotyczących wydzielania hormonu wzrostu u dzieci w różnych stadiach puberalnych, w ramach kontrolowanych protokołów badawczych i nie jako zatwierdzony lek.","q_en":"Czy hexarelin był badany u dzieci","a_en":"Hexarelin był stosowany w badaniach klinicznych dotyczących wydzielania hormonu wzrostu u dzieci w różnych stadiach puberalnych, w ramach kontrolowanych protokołów badawczych i nie jako zatwierdzony lek."},{"q":"Czy hexarelin jest zatwierdzonym lekiem","a":"Nie. Hexarelin nie jest zatwierdzony jako lek w UE ani w USA i jest oferowany wyłącznie jako odczynnik badawczy, nie do użytku ludzkiego.","q_en":"Czy hexarelin jest zatwierdzonym lekiem","a_en":"Nie. Hexarelin nie jest zatwierdzony jako lek w UE ani w USA i jest oferowany wyłącznie jako odczynnik badawczy, nie do użytku ludzkiego."}],"seo":{"title":"Przegląd badań: Hexarelin","title_en":"Przegląd badań: Hexarelin","description":"Hexarelin przedstawiony rzeczowo: mechanizm działania, dane badawcze dotyczące hormonu wzrostu i ACTH/kortyzolu, profil bezpieczeństwa i status prawny tego peptydu GHRP.","description_en":"Hexarelin przedstawiony rzeczowo: mechanizm działania, dane badawcze dotyczące hormonu wzrostu i ACTH/kortyzolu, profil bezpieczeństwa i status prawny tego peptydu GHRP."},"demo":false,"steckbrief":{"cas":"140703-51-1","molekulargewicht":"887,0 g/mol","aminosaeuren":6,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":6,"quellen":["PubChem CID 6918297","chemverify Katalog 14.09.2026"]},"verwandt":["ipamorelin","cjc-1295","sermorelin","igf-1-lr3"]},{"slug":"igf-1-lr3","name":"IGF-1 LR3","synonyme":["Long R3 IGF-1","LR3-IGF-1","IGF-1 Long R3"],"kategorie":"Wachstumshormon-Achse","studienlage":"präklinisch","kurz":"Genetycznie wydłużony analog IGF-1 złożony z 83 aminokwasów, badany w modelach zwierzęcych pod kątem wpływu na wzrost i wymieniony jako substancja dopingowa w sporcie wyczynowym.","kurz_en":"Genetycznie wydłużony analog IGF-1 złożony z 83 aminokwasów, badany w modelach zwierzęcych pod kątem wpływu na wzrost i wymieniony jako substancja dopingowa w sporcie wyczynowym.","beschreibung":"IGF-1 LR3 jest rekombinowanym analogiem naturalnie występującego czynnika wzrostu insulinopodobnego 1, pierwotnie opracowanym do badań na kulturach komórkowych. Ma dodatkowe aminokwasy na N-końcu i zmienioną pozycję 3, przez co w dużej mierze nie wiąże białek wiążących IGF. Jest badany głównie w zwierzęcych modelach wzrostu narządów i komórek, ale poza badaniami jest też szeroko stosowany w celu domniemanej poprawy wyników sportowych, bez solidnych danych z badań na ludziach.","beschreibung_en":"IGF-1 LR3 jest rekombinowanym analogiem naturalnie występującego czynnika wzrostu insulinopodobnego 1, pierwotnie opracowanym do badań na kulturach komórkowych. Ma dodatkowe aminokwasy na N-końcu i zmienioną pozycję 3, przez co w dużej mierze nie wiąże białek wiążących IGF. Jest badany głównie w zwierzęcych modelach wzrostu narządów i komórek, ale poza badaniami jest też szeroko stosowany w celu domniemanej poprawy wyników sportowych, bez solidnych danych z badań na ludziach.","mechanismus":"Ponieważ słabo wiąże się z białkami wiążącymi IGF, większa część IGF-1 LR3 pozostaje swobodnie dostępna i aktywuje receptor IGF-1 silniej i dłużej niż natywny IGF-1. W modelach przedklinicznych opisuje się to jako czynnik wzmagający proliferację komórek poprzez szlaki ERK i PI3K/Akt. Jednocześnie zgłaszane jest hamowanie produkcji endogennego IGF-1 i obniżenie poziomu białek wiążących IGF.","mechanismus_en":"Ponieważ słabo wiąże się z białkami wiążącymi IGF, większa część IGF-1 LR3 pozostaje swobodnie dostępna i aktywuje receptor IGF-1 silniej i dłużej niż natywny IGF-1. W modelach przedklinicznych opisuje się to jako czynnik wzmagający proliferację komórek poprzez szlaki ERK i PI3K/Akt. Jednocześnie zgłaszane jest hamowanie produkcji endogennego IGF-1 i obniżenie poziomu białek wiążących IGF.","evidenz":[{"art":"przedkliniczne","kurz":"Badanie z wlewem u świnek morskich opisało zwiększony wzrost narządów pod wpływem Long R3 IGF-1, przy jednoczesnym spadku stężeń endogennego IGF-1, IGF-2 i białek wiążących IGF w osoczu.","kurz_en":"Badanie z wlewem u świnek morskich opisało zwiększony wzrost narządów pod wpływem Long R3 IGF-1, przy jednoczesnym spadku stężeń endogennego IGF-1, IGF-2 i białek wiążących IGF w osoczu.","quelle":"Conlon et al. 1995, Journal of Endocrinology, PMID 7561636"},{"art":"przedkliniczne","kurz":"Badanie komórkowe na kardiomiocytach płodów owczych wykorzystało IGF-1 LR3 jako stabilny bodziec receptorowy i opisało proliferację komórek zależną od szlaków ERK i PI3K.","kurz_en":"Badanie komórkowe na kardiomiocytach płodów owczych wykorzystało IGF-1 LR3 jako stabilny bodziec receptorowy i opisało proliferację komórek zależną od szlaków ERK i PI3K.","quelle":"Sundgren et al. 2003, American Journal of Physiology, PMID 12947030"},{"art":"kliniczne","kurz":"Przegląd z 2026 roku opisał znaczną lukę między bazą dowodów klinicznych dla peptydów osi hormonu wzrostu, takich jak IGF-1 LR3, a ich powszechnym samodzielnym stosowaniem poza nadzorem medycznym.","kurz_en":"Przegląd z 2026 roku opisał znaczną lukę między bazą dowodów klinicznych dla peptydów osi hormonu wzrostu, takich jak IGF-1 LR3, a ich powszechnym samodzielnym stosowaniem poza nadzorem medycznym.","quelle":"Dominikowski et al. 2026, Frontiers in Endocrinology, PMID 42395176"}],"sicherheit":["Brakuje kontrolowanych badań bezpieczeństwa IGF-1 LR3 u ludzi, dostępne dowody pochodzą z modeli komórkowych i zwierzęcych.","Modele zwierzęce opisują hamowanie własnej osi IGF-1 organizmu, a konsekwencje tego nie zostały zbadane u ludzi.","Niekontrolowane podwyższenie aktywności IGF-1 jest omawiane w literaturze jako teoretyczny czynnik ryzyka dla niepożądanego wzrostu komórek i tkanek, związek przyczynowy u ludzi nie został ustalony.","Produkty z niekontrolowanej produkcji niosą ryzyko zanieczyszczenia niezależne od samej cząsteczki."],"sicherheit_en":["Brakuje kontrolowanych badań bezpieczeństwa IGF-1 LR3 u ludzi, dostępne dowody pochodzą z modeli komórkowych i zwierzęcych.","Modele zwierzęce opisują hamowanie własnej osi IGF-1 organizmu, a konsekwencje tego nie zostały zbadane u ludzi.","Niekontrolowane podwyższenie aktywności IGF-1 jest omawiane w literaturze jako teoretyczny czynnik ryzyka dla niepożądanego wzrostu komórek i tkanek, związek przyczynowy u ludzi nie został ustalony.","Produkty z niekontrolowanej produkcji niosą ryzyko zanieczyszczenia niezależne od samej cząsteczki."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"IGF-1 LR3 nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych i nie jest klasyfikowany jako produkt spożywczy. Jest sprzedawany wyłącznie jako substancja chemiczna do badań. W sporcie zorganizowanym jest zabroniony przez cały czas jako czynnik wzrostu kategorii S2 według Listy substancji i metod zabronionych WADA.","rechtsstatus_en":"IGF-1 LR3 nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych i nie jest klasyfikowany jako produkt spożywczy. Jest sprzedawany wyłącznie jako substancja chemiczna do badań. W sporcie zorganizowanym jest zabroniony przez cały czas jako czynnik wzrostu kategorii S2 według Listy substancji i metod zabronionych WADA.","typischeMg":[],"faq":[{"q":"Co odróżnia IGF-1 LR3 od naturalnego IGF-1?","a":"IGF-1 LR3 ma dodatkowe aminokwasy na N-końcu i zmienioną pozycję 3, przez co prawie nie wiąże się z białkami wiążącymi IGF i dlatego działa na receptor dłużej i silniej niż natywny IGF-1.","q_en":"Co odróżnia IGF-1 LR3 od naturalnego IGF-1?","a_en":"IGF-1 LR3 ma dodatkowe aminokwasy na N-końcu i zmienioną pozycję 3, przez co prawie nie wiąże się z białkami wiążącymi IGF i dlatego działa na receptor dłużej i silniej niż natywny IGF-1."},{"q":"Czy IGF-1 LR3 jest dozwolony w sporcie?","a":"Nie, jest wymieniony jako czynnik wzrostu na Liście Substancji Zabronionych WADA (kategoria S2) i jest zabroniony przez cały czas w sporcie zorganizowanym.","q_en":"Czy IGF-1 LR3 jest dozwolony w sporcie?","a_en":"Nie, jest wymieniony jako czynnik wzrostu na Liście Substancji Zabronionych WADA (kategoria S2) i jest zabroniony przez cały czas w sporcie zorganizowanym."},{"q":"Czy istnieją badania na ludziach dotyczące IGF-1 LR3?","a":"Kontrolowanych badań na ludziach brak, istniejące dowody pochodzą z modeli komórkowych i zwierzęcych, a przegląd z 2026 roku wskazuje na tę lukę w dowodach.","q_en":"Czy istnieją badania na ludziach dotyczące IGF-1 LR3?","a_en":"Kontrolowanych badań na ludziach brak, istniejące dowody pochodzą z modeli komórkowych i zwierzęcych, a przegląd z 2026 roku wskazuje na tę lukę w dowodach."}],"seo":{"title":"IGF-1 LR3: profil badawczy i dowody","title_en":"IGF-1 LR3: profil badawczy i dowody","description":"Przegląd IGF-1 LR3: struktura, dowody przedkliniczne, status dopingowy w sporcie (WADA S2) i profil bezpieczeństwa, przedstawione rzeczowo w kontekście badawczym.","description_en":"Przegląd IGF-1 LR3: struktura, dowody przedkliniczne, status dopingowy w sporcie (WADA S2) i profil bezpieczeństwa, przedstawione rzeczowo w kontekście badawczym."},"demo":false,"steckbrief":{"cas":null,"molekulargewicht":"9111,4 g/mol","aminosaeuren":83,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":83,"quellen":["chemverify Katalog 14.09.2026 (PubChem: kein Eintrag für IGF-1 LR3, CAS dort nicht geführt)"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)"},"verwandt":["hexarelin","cjc-1295","tesamorelin","sermorelin"]},{"slug":"ipamorelin","name":"Ipamorelin","synonyme":["NNC 26-0161"],"kategorie":"Wachstumshormon-Achse","studienlage":"frühe klinische Studien","kurz":"Selektywny pentapeptyd z klasy peptydów uwalniających hormon wzrostu, badany we wczesnych badaniach klinicznych.","kurz_en":"Selektywny pentapeptyd z klasy peptydów uwalniających hormon wzrostu, badany we wczesnych badaniach klinicznych.","beschreibung":"Ipamorelin to syntetyczny peptyd złożony z pięciu aminokwasów, który naśladuje własny przekaźnik organizmu, grelinę. Po raz pierwszy opisano go w 1998 roku jako pierwszego selektywnego przedstawiciela swojej klasy leków; badano go w badaniach klinicznych, m.in. u pacjentów po operacjach jamy brzusznej. W zastosowaniach związanych z hormonem wzrostu do tej pory nie ma dostępnych kontrolowanych badań u zdrowych dorosłych.","beschreibung_en":"Ipamorelin to syntetyczny peptyd złożony z pięciu aminokwasów, który naśladuje własny przekaźnik organizmu, grelinę. Po raz pierwszy opisano go w 1998 roku jako pierwszego selektywnego przedstawiciela swojej klasy leków; badano go w badaniach klinicznych, m.in. u pacjentów po operacjach jamy brzusznej. W zastosowaniach związanych z hormonem wzrostu do tej pory nie ma dostępnych kontrolowanych badań u zdrowych dorosłych.","mechanismus":"Ipamorelin selektywnie wiąże się z receptorem ghreliny (GHS-R1A) w podwzgórzu i przysadce mózgowej, osłabiając hamujące działanie somatostatyny. Prowadzi to do pulsacyjnego uwalniania własnego hormonu wzrostu organizmu z przysadki mózgowej. W przeciwieństwie do starszych peptydów tej samej klasy w badaniach nie stwierdzono istotnego wzrostu ACTH, kortyzolu ani prolaktyny po ipamorelinie.","mechanismus_en":"Ipamorelin selektywnie wiąże się z receptorem ghreliny (GHS-R1A) w podwzgórzu i przysadce mózgowej, osłabiając hamujące działanie somatostatyny. Prowadzi to do pulsacyjnego uwalniania własnego hormonu wzrostu organizmu z przysadki mózgowej. W przeciwieństwie do starszych peptydów tej samej klasy w badaniach nie stwierdzono istotnego wzrostu ACTH, kortyzolu ani prolaktyny po ipamorelinie.","evidenz":[{"art":"przedkliniczne","kurz":"Pierwotny opis w modelu świńskim wykazał, że ipamorelin uwalnia hormon wzrostu bez istotnego wpływu na ACTH, kortyzol, prolaktynę, FSH ani LH, w przeciwieństwie do starszych peptydów tej samej klasy.","kurz_en":"Pierwotny opis w modelu świńskim wykazał, że ipamorelin uwalnia hormon wzrostu bez istotnego wpływu na ACTH, kortyzol, prolaktynę, FSH ani LH, w przeciwieństwie do starszych peptydów tej samej klasy.","quelle":"Raun et al. 1998, European Journal of Endocrinology, PMID 9849822"},{"art":"przedkliniczne","kurz":"W modelu szczura z pooperacyjnym porażeniem jelit, ipamorelin przyspieszył powrót perystaltyki po operacji.","kurz_en":"W modelu szczura z pooperacyjnym porażeniem jelit, ipamorelin przyspieszył powrót perystaltyki po operacji.","quelle":"Venkova et al. 2009, Journal of Pharmacology and Experimental Therapeutics, PMID 19289567"},{"art":"kliniczne","kurz":"W randomizowanym badaniu fazy 2 z grupą placebo, obejmującym 117 pacjentów po operacji jelit, czas do pierwszego tolerowanego posiłku nie różnił się statystycznie między grupą ipamorelinu a grupą placebo.","kurz_en":"W randomizowanym badaniu fazy 2 z grupą placebo, obejmującym 117 pacjentów po operacji jelit, czas do pierwszego tolerowanego posiłku nie różnił się statystycznie między grupą ipamorelinu a grupą placebo.","quelle":"International Journal of Colorectal Disease 2014, DOI 10.1007/s00384-014-2030-8"}],"sicherheit":["W największym dotychczasowym badaniu kontrolowanym zgłaszane zdarzenia niepożądane były równie częste w grupie ipamorelinu i w grupie placebo.","FDA wstrzymała rozwój kliniczny ipamorelinu w 2023 roku po wystąpieniu dwóch zgonów w populacji badanej; związek przyczynowy z peptydem jest uważany za naukowo sporny.","Dane dotyczące długoterminowego bezpieczeństwa u zdrowych dorosłych nie są dostępne.","Interakcje z innymi osiami hormonalnymi nie zostały w pełni zbadane."],"sicherheit_en":["W największym dotychczasowym badaniu kontrolowanym zgłaszane zdarzenia niepożądane były równie częste w grupie ipamorelinu i w grupie placebo.","FDA wstrzymała rozwój kliniczny ipamorelinu w 2023 roku po wystąpieniu dwóch zgonów w populacji badanej; związek przyczynowy z peptydem jest uważany za naukowo sporny.","Dane dotyczące długoterminowego bezpieczeństwa u zdrowych dorosłych nie są dostępne.","Interakcje z innymi osiami hormonalnymi nie zostały w pełni zbadane."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Ipamorelin nie jest zatwierdzony jako lek ani w UE, ani w USA. FDA wstrzymała dalszy rozwój kliniczny w 2023 roku. Jest sprzedawany wyłącznie jako substancja badawcza.","rechtsstatus_en":"Ipamorelin nie jest zatwierdzony jako lek ani w UE, ani w USA. FDA wstrzymała dalszy rozwój kliniczny w 2023 roku. Jest sprzedawany wyłącznie jako substancja badawcza.","typischeMg":[2,5],"faq":[{"q":"Czy ipamorelin podnosi kortyzol jak wcześniejsze peptydy z tej samej klasy","a":"W dostępnych badaniach, w przeciwieństwie do starszych peptydów, takich jak GHRP-6 lub GHRP-2, ipamorelin nie powodował istotnego wzrostu ACTH ani kortyzolu. Uważa się to za jego najlepiej udokumentowaną naukowo cechę wyróżniającą.","q_en":"Czy ipamorelin podnosi kortyzol jak wcześniejsze peptydy z tej samej klasy","a_en":"W dostępnych badaniach, w przeciwieństwie do starszych peptydów, takich jak GHRP-6 lub GHRP-2, ipamorelin nie powodował istotnego wzrostu ACTH ani kortyzolu. Uważa się to za jego najlepiej udokumentowaną naukowo cechę wyróżniającą."},{"q":"Czy ipamorelin jest zatwierdzonym lekiem","a":"Nie. FDA wstrzymała rozwój kliniczny ipamorelinu w 2023 roku. Nie jest zatwierdzony w UE ani w USA i jest sprzedawany jako odczynnik badawczy.","q_en":"Czy ipamorelin jest zatwierdzonym lekiem","a_en":"Nie. FDA wstrzymała rozwój kliniczny ipamorelinu w 2023 roku. Nie jest zatwierdzony w UE ani w USA i jest sprzedawany jako odczynnik badawczy."},{"q":"Dlaczego rozwój ipamorelinu został zatrzymany","a":"Po dwóch zgonach w badanej populacji ciężko chorych pacjentów po operacji jamy brzusznej FDA wstrzymała w 2023 roku dalszy rozwój. Związek przyczynowy z peptydem jest przedmiotem sporów naukowych.","q_en":"Dlaczego rozwój ipamorelinu został zatrzymany","a_en":"Po dwóch zgonach w badanej populacji ciężko chorych pacjentów po operacji jamy brzusznej FDA wstrzymała w 2023 roku dalszy rozwój. Związek przyczynowy z peptydem jest przedmiotem sporów naukowych."}],"seo":{"title":"Przegląd badań: Ipamorelin","title_en":"Przegląd badań: Ipamorelin","description":"Ipamorelin przedstawiony rzeczowo: selektywny mechanizm działania, dane z badań, profil bezpieczeństwa i status prawny tego mimetyku greliny.","description_en":"Ipamorelin przedstawiony rzeczowo: selektywny mechanizm działania, dane z badań, profil bezpieczeństwa i status prawny tego mimetyku greliny."},"demo":false,"steckbrief":{"cas":"170851-70-4","molekulargewicht":"711,9 g/mol","aminosaeuren":5,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":5,"quellen":["PubChem CID 9831659","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, standard handlowy)"},"verwandt":["cjc-1295","sermorelin","tesamorelin","hexarelin"]},{"slug":"sermorelin","name":"Sermorelin","synonyme":["GRF 1-29","GHRH(1-29)","Geref (historyczna nazwa handlowa)"],"kategorie":"Wachstumshormon-Achse","studienlage":"klinisch untersucht","kurz":"Krótki fragment własnej GHRH organizmu, historycznie zatwierdzony jako lek, jest obecnie sprzedawany jako substancja badawcza.","kurz_en":"Krótki fragment własnej GHRH organizmu, historycznie zatwierdzony jako lek, jest obecnie sprzedawany jako substancja badawcza.","beschreibung":"Sermorelin to biologicznie czynny fragment GHRH(1-29) własnego hormonu uwalniającego hormon wzrostu. W USA został zatwierdzony w 1990 roku jako środek diagnostyczny, a w 1997 roku w niskorosłości związanej z niedoborem hormonu wzrostu u dzieci; zatwierdzenie wycofano w 2008 roku z powodów produkcyjnych. Dziś bada się go poza tym historycznym zatwierdzeniem jako substancję badawczą.","beschreibung_en":"Sermorelin to biologicznie czynny fragment GHRH(1-29) własnego hormonu uwalniającego hormon wzrostu. W USA został zatwierdzony w 1990 roku jako środek diagnostyczny, a w 1997 roku w niskorosłości związanej z niedoborem hormonu wzrostu u dzieci; zatwierdzenie wycofano w 2008 roku z powodów produkcyjnych. Dziś bada się go poza tym historycznym zatwierdzeniem jako substancję badawczą.","mechanismus":"Sermorelin wiąże się z receptorem GHRH na komórkach somatotropowych w przysadce mózgowej i aktywuje kaskadę cyklazy adenylanowej i cAMP. Wywołuje to uwalnianie własnego hormonu wzrostu organizmu w fizjologicznych pulsach. Ze względu na bardzo krótki okres półtrwania, wynoszący zaledwie kilka minut, powstający impuls hormonalny jest krótki i umiarkowany.","mechanismus_en":"Sermorelin wiąże się z receptorem GHRH na komórkach somatotropowych w przysadce mózgowej i aktywuje kaskadę cyklazy adenylanowej i cAMP. Wywołuje to uwalnianie własnego hormonu wzrostu organizmu w fizjologicznych pulsach. Ze względu na bardzo krótki okres półtrwania, wynoszący zaledwie kilka minut, powstający impuls hormonalny jest krótki i umiarkowany.","evidenz":[{"art":"kliniczne","kurz":"W randomizowanym badaniu kontrolowanym placebo u starszych mężczyzn i kobiet analog GHRH(1-29) z podstawieniem Nle27 podniósł poziom hormonu wzrostu i IGF-1 w ciągu kilku miesięcy i zwiększył beztłuszczową masę ciała.","kurz_en":"W randomizowanym badaniu kontrolowanym placebo u starszych mężczyzn i kobiet analog GHRH(1-29) z podstawieniem Nle27 podniósł poziom hormonu wzrostu i IGF-1 w ciągu kilku miesięcy i zwiększył beztłuszczową masę ciała.","quelle":"Khorram et al. 1997, Journal of Clinical Endocrinology & Metabolism, PMID 9141536"},{"art":"kliniczne","kurz":"Przegląd dostępnych danych klinicznych u dzieci z niedoborem hormonu wzrostu opisał przyspieszone tempo wzrostu w ciągu dwunastu miesięcy u większości badanych dzieci.","kurz_en":"Przegląd dostępnych danych klinicznych u dzieci z niedoborem hormonu wzrostu opisał przyspieszone tempo wzrostu w ciągu dwunastu miesięcy u większości badanych dzieci.","quelle":"Prakash & Goa 1999, BioDrugs, PMID 18031173"}],"sicherheit":["Dostępne badania zgłaszały głównie łagodne, przejściowe działania niepożądane.","Pierwotne zatwierdzenie zostało wycofane w 2008 roku z powodów produkcyjnych; decyzja ta nie wynikała z ostrzeżenia dotyczącego bezpieczeństwa.","W literaturze omawia się możliwy, niekonsekwentnie obserwowany wzrost LH i FSH.","Dane dotyczące długoterminowego bezpieczeństwa u zdrowych dorosłych nie są dostępne."],"sicherheit_en":["Dostępne badania zgłaszały głównie łagodne, przejściowe działania niepożądane.","Pierwotne zatwierdzenie zostało wycofane w 2008 roku z powodów produkcyjnych; decyzja ta nie wynikała z ostrzeżenia dotyczącego bezpieczeństwa.","W literaturze omawia się możliwy, niekonsekwentnie obserwowany wzrost LH i FSH.","Dane dotyczące długoterminowego bezpieczeństwa u zdrowych dorosłych nie są dostępne."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Sermorelin był zatwierdzony jako lek w USA w latach 1990-2008; zatwierdzenie wycofano z powodów produkcyjnych. Obecnie nie jest sprzedawany jako lek ani w UE, ani w USA i jest oferowany jako odczynnik badawczy.","rechtsstatus_en":"Sermorelin był zatwierdzony jako lek w USA w latach 1990-2008; zatwierdzenie wycofano z powodów produkcyjnych. Obecnie nie jest sprzedawany jako lek ani w UE, ani w USA i jest oferowany jako odczynnik badawczy.","typischeMg":[5,10],"faq":[{"q":"Czy sermorelin był kiedyś zatwierdzonym lekiem","a":"Tak. Sermorelin był zatwierdzony w USA w latach 1990-2008, najpierw jako środek diagnostyczny, później w niskorosłości związanej z niedoborem hormonu wzrostu u dzieci. Zatwierdzenie zostało wycofane z powodów produkcyjnych, a nie z obaw o bezpieczeństwo.","q_en":"Czy sermorelin był kiedyś zatwierdzonym lekiem","a_en":"Tak. Sermorelin był zatwierdzony w USA w latach 1990-2008, najpierw jako środek diagnostyczny, później w niskorosłości związanej z niedoborem hormonu wzrostu u dzieci. Zatwierdzenie zostało wycofane z powodów produkcyjnych, a nie z obaw o bezpieczeństwo."},{"q":"Jaka jest różnica między sermorelinem a CJC-1295","a":"Oba są analogami GHRH. Sermorelin składa się z pierwszych 29 aminokwasów własnego GHRH organizmu bez dalszej modyfikacji, podczas gdy CJC-1295 jest dodatkowo stabilizowany i dlatego ma dłuższy okres półtrwania.","q_en":"Jaka jest różnica między sermorelinem a CJC-1295","a_en":"Oba są analogami GHRH. Sermorelin składa się z pierwszych 29 aminokwasów własnego GHRH organizmu bez dalszej modyfikacji, podczas gdy CJC-1295 jest dodatkowo stabilizowany i dlatego ma dłuższy okres półtrwania."},{"q":"Czy sermorelin jest dostępny jako lek dzisiaj","a":"Nie. Od wycofania z rynku w 2008 roku sermorelin nie jest już dostępny jako zatwierdzony lek w UE ani w USA i jest sprzedawany jako odczynnik badawczy.","q_en":"Czy sermorelin jest dostępny jako lek dzisiaj","a_en":"Nie. Od wycofania z rynku w 2008 roku sermorelin nie jest już dostępny jako zatwierdzony lek w UE ani w USA i jest sprzedawany jako odczynnik badawczy."}],"seo":{"title":"Przegląd badań: Sermorelin","title_en":"Przegląd badań: Sermorelin","description":"Sermorelin przedstawiony rzeczowo: mechanizm działania, historyczne zatwierdzenie, dane z badań i obecny status prawny tego fragmentu GHRH.","description_en":"Sermorelin przedstawiony rzeczowo: mechanizm działania, historyczne zatwierdzenie, dane z badań i obecny status prawny tego fragmentu GHRH."},"demo":false,"steckbrief":{"cas":"86168-78-7","molekulargewicht":"3357,9 g/mol","aminosaeuren":29,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":"rozpuszczalny w wodzie i rozcieńczonym kwasie octowym","sequenzLaenge":29,"quellen":["PubChem CID 16132413","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit_en":"rozpuszczalny w wodzie i rozcieńczonym kwasie octowym"},"verwandt":["cjc-1295","ipamorelin","tesamorelin","hexarelin"]},{"slug":"tesamorelin","name":"Tesamorelin","synonyme":["Egrifta","TH9507","Egrifta WR"],"kategorie":"Wachstumshormon-Achse","studienlage":"zugelassenes Arzneimittel","kurz":"Stabilizowany analog GHRH, zatwierdzony w USA jako lek Egrifta do zmniejszania trzewnej tkanki tłuszczowej brzucha w lipodystrofii związanej z HIV.","kurz_en":"Stabilizowany analog GHRH, zatwierdzony w USA jako lek Egrifta do zmniejszania trzewnej tkanki tłuszczowej brzucha w lipodystrofii związanej z HIV.","beschreibung":"Tesamorelin jest stabilizowanym analogiem pełnej, 44-aminokwasowej cząsteczki GHRH. Pod nazwą handlową Egrifta jest zatwierdzony przez amerykańską FDA od 2010 roku do zmniejszania trzewnej tkanki tłuszczowej brzucha w lipodystrofii związanej z HIV. Czyni go to jedynym peptydem w swojej klasie z ukończonym badaniem fazy 3, na którym oparto zatwierdzenie, z udziałem ponad 800 uczestników.","beschreibung_en":"Tesamorelin jest stabilizowanym analogiem pełnej, 44-aminokwasowej cząsteczki GHRH. Pod nazwą handlową Egrifta jest zatwierdzony przez amerykańską FDA od 2010 roku do zmniejszania trzewnej tkanki tłuszczowej brzucha w lipodystrofii związanej z HIV. Czyni go to jedynym peptydem w swojej klasie z ukończonym badaniem fazy 3, na którym oparto zatwierdzenie, z udziałem ponad 800 uczestników.","mechanismus":"Tesamorelin wiąże się z receptorem GHRH na komórkach somatotropowych w przysadce mózgowej, pobudzając pulsacyjne uwalnianie własnego hormonu wzrostu organizmu, przy w pełni zachowanej pętli sprzężenia zwrotnego z udziałem somatostatyny. Uwolniony hormon wzrostu jest w wątrobie przekształcany w IGF-1. Tesamorelin działa też stosunkowo selektywnie na receptory hormonu wzrostu w trzewnej tkance tłuszczowej, aktywując tam lipazę wrażliwą na hormony.","mechanismus_en":"Tesamorelin wiąże się z receptorem GHRH na komórkach somatotropowych w przysadce mózgowej, pobudzając pulsacyjne uwalnianie własnego hormonu wzrostu organizmu, przy w pełni zachowanej pętli sprzężenia zwrotnego z udziałem somatostatyny. Uwolniony hormon wzrostu jest w wątrobie przekształcany w IGF-1. Tesamorelin działa też stosunkowo selektywnie na receptory hormonu wzrostu w trzewnej tkance tłuszczowej, aktywując tam lipazę wrażliwą na hormony.","evidenz":[{"art":"kliniczne","kurz":"W randomizowanym badaniu fazy 3 kontrolowanym placebo u osób z redystrybucją tkanki tłuszczowej związaną z HIV tesamorelin w ciągu 26 tygodni zmniejszył trzewną tkankę tłuszczową istotnie bardziej niż placebo i podniósł poziom IGF-1.","kurz_en":"W randomizowanym badaniu fazy 3 kontrolowanym placebo u osób z redystrybucją tkanki tłuszczowej związaną z HIV tesamorelin w ciągu 26 tygodni zmniejszył trzewną tkankę tłuszczową istotnie bardziej niż placebo i podniósł poziom IGF-1.","quelle":"Falutz et al. 2007, New England Journal of Medicine, PMID 18057338"},{"art":"kliniczne","kurz":"Kolejne badanie randomizowane u pacjentów z HIV z nagromadzeniem tkanki tłuszczowej w jamie brzusznej potwierdziło zmniejszenie trzewnej tkanki tłuszczowej i dodatkowo wykazało zmniejszenie tkanki tłuszczowej w wątrobie.","kurz_en":"Kolejne badanie randomizowane u pacjentów z HIV z nagromadzeniem tkanki tłuszczowej w jamie brzusznej potwierdziło zmniejszenie trzewnej tkanki tłuszczowej i dodatkowo wykazało zmniejszenie tkanki tłuszczowej w wątrobie.","quelle":"Stanley et al. 2014, JAMA, PMID 25038357"}],"sicherheit":["Najczęstszym zgłaszanym działaniem niepożądanym w badaniach były bóle stawów u części uczestników.","Zatrzymanie płynów w kończynach zaobserwowano u mniejszej części uczestników, rzadziej niż przy hormonie wzrostu.","Średnio stężenie glukozy we krwi w badaniach rosło nieznacznie i przejściowo.","Zgodnie z ChPL tesamorelin uznaje się za przeciwwskazany w aktywnej chorobie nowotworowej, guzie przysadki, ciąży lub retinopatii cukrzycowej."],"sicherheit_en":["Najczęstszym zgłaszanym działaniem niepożądanym w badaniach były bóle stawów u części uczestników.","Zatrzymanie płynów w kończynach zaobserwowano u mniejszej części uczestników, rzadziej niż przy hormonie wzrostu.","Średnio stężenie glukozy we krwi w badaniach rosło nieznacznie i przejściowo.","Zgodnie z ChPL tesamorelin uznaje się za przeciwwskazany w aktywnej chorobie nowotworowej, guzie przysadki, ciąży lub retinopatii cukrzycowej."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Tesamorelin jest zatwierdzony w USA pod nazwą handlową Egrifta od 2010 roku w określonym wskazaniu w lipodystrofii związanej z HIV. Nie jest zatwierdzony w UE ani w Szwajcarii, a w krajach niemieckojęzycznych nie jest praktycznie dostępny. Poza zatwierdzonym wskazaniem każde zastosowanie uznaje się za stosowanie poza wskazaniami rejestracyjnymi (off-label).","rechtsstatus_en":"Tesamorelin jest zatwierdzony w USA pod nazwą handlową Egrifta od 2010 roku w określonym wskazaniu w lipodystrofii związanej z HIV. Nie jest zatwierdzony w UE ani w Szwajcarii, a w krajach niemieckojęzycznych nie jest praktycznie dostępny. Poza zatwierdzonym wskazaniem każde zastosowanie uznaje się za stosowanie poza wskazaniami rejestracyjnymi (off-label).","typischeMg":[2,5],"faq":[{"q":"Czy tesamorelin jest zatwierdzonym lekiem","a":"Tak, pod nazwą Egrifta od 2010 roku w USA, ale tylko w określonym wskazaniu: zmniejszanie trzewnej tkanki tłuszczowej brzucha w lipodystrofii związanej z HIV. W UE nie ma zatwierdzenia.","q_en":"Czy tesamorelin jest zatwierdzonym lekiem","a_en":"Tak, pod nazwą Egrifta od 2010 roku w USA, ale tylko w określonym wskazaniu: zmniejszanie trzewnej tkanki tłuszczowej brzucha w lipodystrofii związanej z HIV. W UE nie ma zatwierdzenia."},{"q":"Czy tesamorelin buduje mięśnie","a":"Badania wykazują wzrost masy ciała wolnej od tłuszczu, ale istotna część tej masy stanowi woda i tkanka łączna. Wyraźny wzrost mięśni bez dodatkowego stymulowania receptorów androgenowych nie jest udokumentowany naukowo.","q_en":"Czy tesamorelin buduje mięśnie","a_en":"Badania wykazują wzrost masy ciała wolnej od tłuszczu, ale istotna część tej masy stanowi woda i tkanka łączna. Wyraźny wzrost mięśni bez dodatkowego stymulowania receptorów androgenowych nie jest udokumentowany naukowo."},{"q":"Jak tesamorelin różni się od innych analogów GHRH","a":"Tesamorelin jest jedynym analogiem GHRH z ukończonym badaniem fazy 3 z udziałem ponad 800 uczestników i obowiązującym zatwierdzeniem regulacyjnym w USA. Sermorelin i CJC-1295 nie osiągnęły tego statusu.","q_en":"Jak tesamorelin różni się od innych analogów GHRH","a_en":"Tesamorelin jest jedynym analogiem GHRH z ukończonym badaniem fazy 3 z udziałem ponad 800 uczestników i obowiązującym zatwierdzeniem regulacyjnym w USA. Sermorelin i CJC-1295 nie osiągnęły tego statusu."}],"seo":{"title":"Przegląd badań: Tesamorelin","title_en":"Przegląd badań: Tesamorelin","description":"Tesamorelin (Egrifta) przedstawiony rzeczowo: status zatwierdzenia, mechanizm działania, dane z badań klinicznych i status prawny poza USA.","description_en":"Tesamorelin (Egrifta) przedstawiony rzeczowo: status zatwierdzenia, mechanizm działania, dane z badań klinicznych i status prawny poza USA."},"demo":false,"steckbrief":{"cas":"218949-48-5","molekulargewicht":"5136 g/mol","aminosaeuren":44,"halbwertszeit":"≈ 8 minut (eliminacja, ChPL Egrifta SV)","reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":44,"quellen":["PubChem CID 16137828","DailyMed SPL EGRIFTA SV (Tesamorelin), Theratechnologies","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 8 minut (eliminacja, ChPL Egrifta SV)","reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)"},"verwandt":["cjc-1295","ipamorelin","sermorelin","igf-1-lr3"]},{"slug":"ghk-cu","name":"GHK-Cu","synonyme":["Glicylo-L-histydylo-L-lizyna z miedzią","Miedziowy tripeptyd-1"],"kategorie":"Haut & Kosmetik","studienlage":"frühe klinische Studien","kurz":"Naturalny tripeptyd wiążący miedź, najszerzej badany w badaniach nad skórą, z dodatkowymi danymi przedklinicznymi dotyczącymi innych tkanek.","kurz_en":"Naturalny tripeptyd wiążący miedź, najszerzej badany w badaniach nad skórą, z dodatkowymi danymi przedklinicznymi dotyczącymi innych tkanek.","beschreibung":"GHK-Cu to tripeptyd złożony z trzech aminokwasów, który występuje naturalnie w organizmie i trwale wiąże jon miedzi. Jest badany głównie w badaniach kosmetycznych i dermatologicznych nad tworzeniem kolagenu i odnową skóry. Ponadto w głównie przedklinicznych badaniach analizuje się możliwy wpływ na procesy zapalne i ekspresję genów w różnych modelach tkankowych.","beschreibung_en":"GHK-Cu to tripeptyd złożony z trzech aminokwasów, który występuje naturalnie w organizmie i trwale wiąże jon miedzi. Jest badany głównie w badaniach kosmetycznych i dermatologicznych nad tworzeniem kolagenu i odnową skóry. Ponadto w głównie przedklinicznych badaniach analizuje się możliwy wpływ na procesy zapalne i ekspresję genów w różnych modelach tkankowych.","mechanismus":"W komórkach skóry opisano, że GHK-Cu zwiększa syntezę kolagenu i elastyny oraz aktywuje fibroblasty, komórki budujące tkankę łączną. W przedklinicznych modelach ekspresji genów GHK-Cu wykazywał zależną od kontekstu regulację licznych genów związanych z naprawą tkanek, stresem oksydacyjnym i stanem zapalnym. Zakres, w jakim te efekty na ekspresję genów przenoszą się na żywych ludzi, jest przedmiotem trwających badań.","mechanismus_en":"W komórkach skóry opisano, że GHK-Cu zwiększa syntezę kolagenu i elastyny oraz aktywuje fibroblasty, komórki budujące tkankę łączną. W przedklinicznych modelach ekspresji genów GHK-Cu wykazywał zależną od kontekstu regulację licznych genów związanych z naprawą tkanek, stresem oksydacyjnym i stanem zapalnym. Zakres, w jakim te efekty na ekspresję genów przenoszą się na żywych ludzi, jest przedmiotem trwających badań.","evidenz":[{"art":"kliniczne","kurz":"Dwunastotygodniowe badanie stosowania u kobiet z widocznymi oznakami starzenia skóry opisało zwiększoną grubość skóry, mniejszą głębokość zmarszczek i potwierdzony biopsją wzrost aktywności komórek skóry po kremie z GHK-Cu w porównaniu z wartością wyjściową.","kurz_en":"Dwunastotygodniowe badanie stosowania u kobiet z widocznymi oznakami starzenia skóry opisało zwiększoną grubość skóry, mniejszą głębokość zmarszczek i potwierdzony biopsją wzrost aktywności komórek skóry po kremie z GHK-Cu w porównaniu z wartością wyjściową.","quelle":"Finkley et al. 2005, in: Cosmeceuticals and Active Cosmetics: Drugs vs. Cosmetics"},{"art":"przedkliniczne","kurz":"Badanie na mysim modelu wrzodziejącego zapalenia jelita grubego opisało, że GHK-Cu wspiera funkcję bariery jelitowej poprzez szlak SIRT1/STAT3 i zmniejsza ilość mediatorów zapalnych.","kurz_en":"Badanie na mysim modelu wrzodziejącego zapalenia jelita grubego opisało, że GHK-Cu wspiera funkcję bariery jelitowej poprzez szlak SIRT1/STAT3 i zmniejsza ilość mediatorów zapalnych.","quelle":"Mao et al. 2025, Frontiers in Pharmacology, PMID 40672369"}],"sicherheit":["W dostępnych badaniach nad stosowaniem miejscowym nie opisano istotnych zastrzeżeń dotyczących bezpieczeństwa.","GHK-Cu zawiera związaną miedź; w typowych stężeniach kosmetycznych nie wiąże się to z nadmiarem miedzi w organizmie.","W przypadku stosowania wstrzykiwanego, ogólnoustrojowego nie są dostępne kontrolowane placebo badania bezpieczeństwa u ludzi.","Produkty z niekontrolowanej produkcji niosą ryzyko zanieczyszczenia niezależne od samej cząsteczki."],"sicherheit_en":["W dostępnych badaniach nad stosowaniem miejscowym nie opisano istotnych zastrzeżeń dotyczących bezpieczeństwa.","GHK-Cu zawiera związaną miedź; w typowych stężeniach kosmetycznych nie wiąże się to z nadmiarem miedzi w organizmie.","W przypadku stosowania wstrzykiwanego, ogólnoustrojowego nie są dostępne kontrolowane placebo badania bezpieczeństwa u ludzi.","Produkty z niekontrolowanej produkcji niosą ryzyko zanieczyszczenia niezależne od samej cząsteczki."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"W preparatach kosmetycznych Copper Tripeptide-1 jest w Stanach Zjednoczonych wymieniony jako składnik kosmetyczny. W UE i Niemczech wstrzykiwana forma badawcza znajduje się w szarej strefie prawnej i nie jest zatwierdzona jako lek.","rechtsstatus_en":"W preparatach kosmetycznych Copper Tripeptide-1 jest w Stanach Zjednoczonych wymieniony jako składnik kosmetyczny. W UE i Niemczech wstrzykiwana forma badawcza znajduje się w szarej strefie prawnej i nie jest zatwierdzona jako lek.","typischeMg":[],"faq":[{"q":"Czy GHK-Cu jest zatwierdzony w kosmetykach?","a":"W Stanach Zjednoczonych Copper Tripeptide-1 jest wymieniony jako składnik kosmetyczny. UE nie ma porównywalnego samodzielnego zatwierdzenia, chociaż produkty kosmetyczne są szeroko sprzedawane.","q_en":"Czy GHK-Cu jest zatwierdzony w kosmetykach?","a_en":"W Stanach Zjednoczonych Copper Tripeptide-1 jest wymieniony jako składnik kosmetyczny. UE nie ma porównywalnego samodzielnego zatwierdzenia, chociaż produkty kosmetyczne są szeroko sprzedawane."},{"q":"Gdzie znajdują się najmocniejsze dowody dotyczące GHK-Cu?","a":"Najbardziej solidne dane z badań na ludziach pochodzą z badań nad miejscowym stosowaniem na skórę. Zastosowanie ogólnoustrojowe, we wstrzyknięciach, opiera się głównie na przedklinicznych modelach zwierzęcych i komórkowych.","q_en":"Gdzie znajdują się najmocniejsze dowody dotyczące GHK-Cu?","a_en":"Najbardziej solidne dane z badań na ludziach pochodzą z badań nad miejscowym stosowaniem na skórę. Zastosowanie ogólnoustrojowe, we wstrzyknięciach, opiera się głównie na przedklinicznych modelach zwierzęcych i komórkowych."},{"q":"Czy miedź w GHK-Cu stanowi zagrożenie dla bezpieczeństwa?","a":"W typowych stężeniach kosmetycznych nie opisuje się tego jako istotnego ryzyka. W literaturze za bardziej prawdopodobny uważa się niedobór miedzi niż jej nadmiar.","q_en":"Czy miedź w GHK-Cu stanowi zagrożenie dla bezpieczeństwa?","a_en":"W typowych stężeniach kosmetycznych nie opisuje się tego jako istotnego ryzyka. W literaturze za bardziej prawdopodobny uważa się niedobór miedzi niż jej nadmiar."}],"seo":{"title":"GHK-Cu: profil badawczy i dowody","title_en":"GHK-Cu: profil badawczy i dowody","description":"Przegląd GHK-Cu: tripeptyd miedziowy, mechanizm działania, badania nad skórą i profil bezpieczeństwa, przedstawiony rzeczowo w kontekście badawczym.","description_en":"Przegląd GHK-Cu: tripeptyd miedziowy, mechanizm działania, badania nad skórą i profil bezpieczeństwa, przedstawiony rzeczowo w kontekście badawczym."},"demo":false,"steckbrief":{"cas":"89030-95-5","molekulargewicht":"402,92 g/mol","aminosaeuren":3,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard komercyjny, proszek niebieski)","loeslichkeit":null,"sequenzLaenge":3,"quellen":["PubChem CID 71587328","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard komercyjny, proszek niebieski)"},"verwandt":["bpc-157","tb-500","pentadeca-arginate"]},{"slug":"dihexa","name":"Dihexa","synonyme":["PNB-0408","N-Hexanoyl-Tyr-Ile-(6)aminohexanamide"],"kategorie":"Kognition","studienlage":"präklinisch","kurz":"Syntetyczny analog angiotensyny IV, badany w przedklinicznych modelach szczurzych dotyczących funkcji pamięci, bez dotychczas opublikowanych danych dotyczących ludzi.","kurz_en":"Syntetyczny analog angiotensyny IV, badany w przedklinicznych modelach szczurzych dotyczących funkcji pamięci, bez dotychczas opublikowanych danych dotyczących ludzi.","beschreibung":"Dihexa jest syntetycznym peptydomimetykiem wywodzącym się z własnej angiotensyny IV organizmu, opracowanym w grupie badawczej Josepha Hardinga na Washington State University. Do tej pory była badana wyłącznie w modelach przedklinicznych, głównie na szczurach, w związku z uczeniem się i pamięcią. Nie opublikowano badań na ludziach dotyczących dihexy, dlatego jej profil bezpieczeństwa u ludzi nie został zbadany.","beschreibung_en":"Dihexa jest syntetycznym peptydomimetykiem wywodzącym się z własnej angiotensyny IV organizmu, opracowanym w grupie badawczej Josepha Hardinga na Washington State University. Do tej pory była badana wyłącznie w modelach przedklinicznych, głównie na szczurach, w związku z uczeniem się i pamięcią. Nie opublikowano badań na ludziach dotyczących dihexy, dlatego jej profil bezpieczeństwa u ludzi nie został zbadany.","mechanismus":"Dihexa jest opisywana jako metabolicznie stabilizowany analog angiotensyny IV, dostępny po podaniu doustnym i zdolny do przekraczania bariery krew-mózg. W odróżnieniu od własnej angiotensyny IV organizmu, według doniesień z modeli komórkowych wiąże się bezpośrednio z receptorem czynnika wzrostu hepatocytów c-Met, przez co miałaby pobudzać wzrost dendrytów i synaptogenezę. Część prac pierwotnie wspierających ten mechanizm została wycofana w 2025 roku z powodu potwierdzonej manipulacji obrazami, dlatego dokładnego mechanizmu działania nie można uznać za naukowo ustalony.","mechanismus_en":"Dihexa jest opisywana jako metabolicznie stabilizowany analog angiotensyny IV, dostępny po podaniu doustnym i zdolny do przekraczania bariery krew-mózg. W odróżnieniu od własnej angiotensyny IV organizmu, według doniesień z modeli komórkowych wiąże się bezpośrednio z receptorem czynnika wzrostu hepatocytów c-Met, przez co miałaby pobudzać wzrost dendrytów i synaptogenezę. Część prac pierwotnie wspierających ten mechanizm została wycofana w 2025 roku z powodu potwierdzonej manipulacji obrazami, dlatego dokładnego mechanizmu działania nie można uznać za naukowo ustalony.","evidenz":[{"art":"przedkliniczne","kurz":"U szczurów doustnie podana dihexa (2 mg/kg) odwróciła deficyty pamięci wywołane skopolaminą w teście wodnego labiryntu Morrisa i poprawiła uczenie się u 24-miesięcznych zwierząt.","kurz_en":"U szczurów doustnie podana dihexa (2 mg/kg) odwróciła deficyty pamięci wywołane skopolaminą w teście wodnego labiryntu Morrisa i poprawiła uczenie się u 24-miesięcznych zwierząt.","quelle":"McCoy AT et al. 2013, Journal of Pharmacology and Experimental Therapeutics, PMID 23055539 (This paper has carried an Expression of Concern from the publisher since 2021 over possible image manipulation, no retraction)"},{"art":"przedkliniczne","kurz":"W szczurzym modelu objawów przypominających chorobę Huntingtona, wywołanych kwasem 3-nitropropionowym, PNB-0408 (dihexa) nie wykazał istotnej poprawy w zakresie punktów końcowych ruchowych ani neuropatologicznych w porównaniu ze zwierzętami kontrolnymi.","kurz_en":"W szczurzym modelu objawów przypominających chorobę Huntingtona, wywołanych kwasem 3-nitropropionowym, PNB-0408 (dihexa) nie wykazał istotnej poprawy w zakresie punktów końcowych ruchowych ani neuropatologicznych w porównaniu ze zwierzętami kontrolnymi.","quelle":"Wells RG et al. 2024, Journal of Huntington's Disease, Bd. 13, Nr. 1, S. 55-66, PMID 38489193"}],"sicherheit":["Nie opublikowano badań na ludziach dotyczących dihexy, a jej profil bezpieczeństwa u ludzi nie został zbadany.","Wszystkie opublikowane dane do tej pory pochodzą z modeli zwierzęcych, głównie szczurów, z okresami obserwacji wynoszącymi zaledwie kilka tygodni.","Badanie z 2013 roku dotyczące metabolicznie stabilizowanych analogów angiotensyny IV od 2021 roku jest opatrzone przez wydawcę redakcyjnym wyrażeniem zaniepokojenia (Expression of Concern) z powodu możliwej manipulacji obrazami, bez wycofania pracy.","Artykuł z 2014 roku dotyczący leżącego u podstaw mechanizmu HGF/c-Met został formalnie wycofany w 2025 roku po dochodzeniu, które potwierdziło sfałszowane i zmanipulowane ryciny.","Dane dotyczące długoterminowego bezpieczeństwa, w tym z badań zwierzęcych, nie są jeszcze dostępne."],"sicherheit_en":["Nie opublikowano badań na ludziach dotyczących dihexy, a jej profil bezpieczeństwa u ludzi nie został zbadany.","Wszystkie opublikowane dane do tej pory pochodzą z modeli zwierzęcych, głównie szczurów, z okresami obserwacji wynoszącymi zaledwie kilka tygodni.","Badanie z 2013 roku dotyczące metabolicznie stabilizowanych analogów angiotensyny IV od 2021 roku jest opatrzone przez wydawcę redakcyjnym wyrażeniem zaniepokojenia (Expression of Concern) z powodu możliwej manipulacji obrazami, bez wycofania pracy.","Artykuł z 2014 roku dotyczący leżącego u podstaw mechanizmu HGF/c-Met został formalnie wycofany w 2025 roku po dochodzeniu, które potwierdziło sfałszowane i zmanipulowane ryciny.","Dane dotyczące długoterminowego bezpieczeństwa, w tym z badań zwierzęcych, nie są jeszcze dostępne."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Dihexa nigdy nie weszła w proces rejestracji klinicznej do stosowania u ludzi i nie jest zatwierdzona jako lek w Niemczech, UE ani w Stanach Zjednoczonych. Jest sprzedawana wyłącznie jako odczynnik badawczy do użytku laboratoryjnego.","rechtsstatus_en":"Dihexa nigdy nie weszła w proces rejestracji klinicznej do stosowania u ludzi i nie jest zatwierdzona jako lek w Niemczech, UE ani w Stanach Zjednoczonych. Jest sprzedawana wyłącznie jako odczynnik badawczy do użytku laboratoryjnego.","typischeMg":[],"faq":[{"q":"Czy istnieją jakiekolwiek badania na ludziach dotyczące dihexy","a":"Nie. Wszystkie dane opublikowane na temat dihexy do tej pory pochodzą z modeli zwierzęcych, głównie szczurów. Profil bezpieczeństwa do stosowania u ludzi nie był badany, więc nie istnieją dane dotyczące tolerancji ani skuteczności u ludzi.","q_en":"Czy istnieją jakiekolwiek badania na ludziach dotyczące dihexy","a_en":"Nie. Wszystkie dane opublikowane na temat dihexy do tej pory pochodzą z modeli zwierzęcych, głównie szczurów. Profil bezpieczeństwa do stosowania u ludzi nie był badany, więc nie istnieją dane dotyczące tolerancji ani skuteczności u ludzi."},{"q":"Jak wyjaśnia się mechanizm działania dihexy","a":"Podaje się, że dihexa wiąże się z receptorem czynnika wzrostu hepatocytów c-Met, szlakiem, który ma wywoływać synaptogenezę w modelach komórkowych. Część prac, które pierwotnie wspierały ten mechanizm, została wycofana w 2025 roku z powodu sfałszowanych danych.","q_en":"Jak wyjaśnia się mechanizm działania dihexy","a_en":"Podaje się, że dihexa wiąże się z receptorem czynnika wzrostu hepatocytów c-Met, szlakiem, który ma wywoływać synaptogenezę w modelach komórkowych. Część prac, które pierwotnie wspierały ten mechanizm, została wycofana w 2025 roku z powodu sfałszowanych danych."},{"q":"Czy dihexa jest zatwierdzonym lekiem","a":"Nie. Dihexa nigdy nie przeszła procesu zatwierdzania klinicznego do stosowania u ludzi i nie jest zatwierdzona jako lek w Niemczech, UE ani Stanach Zjednoczonych. Jest sprzedawana wyłącznie jako odczynnik badawczy.","q_en":"Czy dihexa jest zatwierdzonym lekiem","a_en":"Nie. Dihexa nigdy nie przeszła procesu zatwierdzania klinicznego do stosowania u ludzi i nie jest zatwierdzona jako lek w Niemczech, UE ani Stanach Zjednoczonych. Jest sprzedawana wyłącznie jako odczynnik badawczy."}],"seo":{"title":"Dihexa: stan badań nad analogiem angiotensyny IV","title_en":"Dihexa: stan badań nad analogiem angiotensyny IV","description":"Dihexa przedstawiona rzeczowo: pochodzenie, mechanizm działania, stan badań przedklinicznych i otwarte pytania dotyczące bezpieczeństwa tego peptydu badawczego.","description_en":"Dihexa przedstawiona rzeczowo: pochodzenie, mechanizm działania, stan badań przedklinicznych i otwarte pytania dotyczące bezpieczeństwa tego peptydu badawczego."},"demo":false,"steckbrief":{"cas":"1401708-83-5","molekulargewicht":"504,7 g/mol","aminosaeuren":2,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":2,"quellen":["PubChem CID 129010512","chemverify Katalog 14.09.2026"]},"verwandt":["semax","selank","dsip"]},{"slug":"dsip","name":"DSIP","synonyme":["Peptyd indukujący sen delta","Peptyd snu delta"],"kategorie":"Kognition","studienlage":"klinisch untersucht","kurz":"Jeden z najdłużej badanych neuropeptydów, pierwotnie izolowany jako mediator wywołujący sen z mózgu śpiących królików, z niespójnym zbiorem badań do dziś.","kurz_en":"Jeden z najdłużej badanych neuropeptydów, pierwotnie izolowany jako mediator wywołujący sen z mózgu śpiących królików, z niespójnym zbiorem badań do dziś.","beschreibung":"DSIP (peptyd wywołujący sen delta) to nonapeptyd, który po raz pierwszy wyizolowali w 1977 roku Schoenenberger i Monnier z krwi żylnej mózgu śpiących królików i nazwali go ze względu na zdolność do wywoływania aktywności EEG w paśmie fal delta w tym modelu zwierzęcym. W kolejnych dekadach badano go w licznych badaniach na ludziach dotyczących snu, osi stresu i regulacji hormonalnej. Pierwotnie opisanego działania wspomagającego sen nie udało się wiarygodnie odtworzyć w niezależnych, bardziej rygorystycznych badaniach.","beschreibung_en":"DSIP (peptyd wywołujący sen delta) to nonapeptyd, który po raz pierwszy wyizolowali w 1977 roku Schoenenberger i Monnier z krwi żylnej mózgu śpiących królików i nazwali go ze względu na zdolność do wywoływania aktywności EEG w paśmie fal delta w tym modelu zwierzęcym. W kolejnych dekadach badano go w licznych badaniach na ludziach dotyczących snu, osi stresu i regulacji hormonalnej. Pierwotnie opisanego działania wspomagającego sen nie udało się wiarygodnie odtworzyć w niezależnych, bardziej rygorystycznych badaniach.","mechanismus":"Dokładny mechanizm działania DSIP pozostaje niewyjaśniony mimo dziesięcioleci badań. Proponowany udział obejmuje rolę w regulacji osi podwzgórze-przysadka-nadnercza oraz interakcje ze szlakami sygnałowymi GABA-ergicznymi i opioidowymi. Dotychczas nie opisano żadnego konkretnego, jednoznacznie zidentyfikowanego receptora dla DSIP, co utrudnia interpretację jego działania.","mechanismus_en":"Dokładny mechanizm działania DSIP pozostaje niewyjaśniony mimo dziesięcioleci badań. Proponowany udział obejmuje rolę w regulacji osi podwzgórze-przysadka-nadnercza oraz interakcje ze szlakami sygnałowymi GABA-ergicznymi i opioidowymi. Dotychczas nie opisano żadnego konkretnego, jednoznacznie zidentyfikowanego receptora dla DSIP, co utrudnia interpretację jego działania.","evidenz":[{"art":"przedkliniczne","kurz":"Pierwotna izolacja z krwi mózgowej śpiących królików pozwoliła zidentyfikować sekwencję nonapeptydu i wykazała zwiększoną aktywność EEG w paśmie fal delta w modelu zwierzęcym po podaniu dokomorowym.","kurz_en":"Pierwotna izolacja z krwi mózgowej śpiących królików pozwoliła zidentyfikować sekwencję nonapeptydu i wykazała zwiększoną aktywność EEG w paśmie fal delta w modelu zwierzęcym po podaniu dokomorowym.","quelle":"Schoenenberger GA, Monnier M 1977, Proceedings of the National Academy of Sciences, Bd. 74(3), S. 1282-1286, PMID 265572"},{"art":"kliniczne","kurz":"W podwójnie zaślepionym badaniu krzyżowym u pacjentów z przewlekłą bezsennością z monitorowaniem polisomnograficznym przez cztery noce, poprawa snu pod wpływem DSIP była niewielka w porównaniu z placebo.","kurz_en":"W podwójnie zaślepionym badaniu krzyżowym u pacjentów z przewlekłą bezsennością z monitorowaniem polisomnograficznym przez cztery noce, poprawa snu pod wpływem DSIP była niewielka w porównaniu z placebo.","quelle":"Monti JM et al. 1987, International Journal of Clinical Pharmacology Research, Bd. 7(2), S. 105-110, PMID 3583493"},{"art":"kliniczne","kurz":"Przegląd podsumowujący trzy dekady badań na ludziach i zwierzętach dochodzi do wniosku, że pierwotnie postulowanego działania DSIP wywołującego sen nie udało się konsekwentnie potwierdzić w niezależnych badaniach.","kurz_en":"Przegląd podsumowujący trzy dekady badań na ludziach i zwierzętach dochodzi do wniosku, że pierwotnie postulowanego działania DSIP wywołującego sen nie udało się konsekwentnie potwierdzić w niezależnych badaniach.","quelle":"Kovalzon VM, Strekalova TV 2006, Journal of Neurochemistry, Bd. 97(2), S. 303-309, PMID 16539679"},{"art":"przedkliniczne","kurz":"Badanie przedkliniczne z 2024 roku objęło peptyd fuzyjny DSIP w mysim modelu bezsenności wywołanej farmakologicznie i opisało wpływ na poziom neuroprzekaźników, takich jak serotonina i dopamina.","kurz_en":"Badanie przedkliniczne z 2024 roku objęło peptyd fuzyjny DSIP w mysim modelu bezsenności wywołanej farmakologicznie i opisało wpływ na poziom neuroprzekaźników, takich jak serotonina i dopamina.","quelle":"Mu X et al. 2024, Frontiers in Pharmacology, Bd. 15, Artikel 1439536, PMID 39444618"}],"sicherheit":["Działanie wspomagające sen opisane w starszych badaniach na ludziach nie jest według aktualnej literatury przeglądowej uważane za wiarygodnie powtarzalne.","Wiele dostępnych badań na ludziach pochodzi z lat 1980. i wykazuje słabości metodologiczne, takie jak małe próby i krótkie okresy obserwacji.","W badaniu na zdrowych ochotnikach wlew DSIP nie zmienił w sposób mierzalny wydzielania ACTH i kortyzolu pobudzanego przez CRH.","Niezależnie powtórzone, nowoczesne dane o długoterminowym bezpieczeństwie u ludzi nie są dostępne."],"sicherheit_en":["Działanie wspomagające sen opisane w starszych badaniach na ludziach nie jest według aktualnej literatury przeglądowej uważane za wiarygodnie powtarzalne.","Wiele dostępnych badań na ludziach pochodzi z lat 1980. i wykazuje słabości metodologiczne, takie jak małe próby i krótkie okresy obserwacji.","W badaniu na zdrowych ochotnikach wlew DSIP nie zmienił w sposób mierzalny wydzielania ACTH i kortyzolu pobudzanego przez CRH.","Niezależnie powtórzone, nowoczesne dane o długoterminowym bezpieczeństwie u ludzi nie są dostępne."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"DSIP nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych, gdzie jest sprzedawany wyłącznie jako odczynnik badawczy.","rechtsstatus_en":"DSIP nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych, gdzie jest sprzedawany wyłącznie jako odczynnik badawczy.","typischeMg":[5,10],"faq":[{"q":"Czy działanie DSIP wspomagające sen zostało potwierdzone w badaniach","a":"Dowody są niespójne. Wczesne badania zgłaszały działanie wspomagające sen, ale przegląd z 2006 roku stwierdził, że w niezależnych badaniach nie udało się konsekwentnie odtworzyć tego efektu.","q_en":"Czy działanie DSIP wspomagające sen zostało potwierdzone w badaniach","a_en":"Dowody są niespójne. Wczesne badania zgłaszały działanie wspomagające sen, ale przegląd z 2006 roku stwierdził, że w niezależnych badaniach nie udało się konsekwentnie odtworzyć tego efektu."},{"q":"Skąd pochodzi nazwa DSIP","a":"DSIP oznacza peptyd wywołujący sen delta. Nazwa sięga do jego pierwszego opisu w 1977 roku, kiedy został wyizolowany z krwi mózgowej śpiących królików i wywołał aktywność EEG fal delta w tym modelu zwierzęcym.","q_en":"Skąd pochodzi nazwa DSIP","a_en":"DSIP oznacza peptyd wywołujący sen delta. Nazwa sięga do jego pierwszego opisu w 1977 roku, kiedy został wyizolowany z krwi mózgowej śpiących królików i wywołał aktywność EEG fal delta w tym modelu zwierzęcym."},{"q":"Czy DSIP jest legalnie dostępny w Niemczech","a":"DSIP nie jest zatwierdzony jako lek w Niemczech ani w UE. Jest oferowany wyłącznie jako odczynnik badawczy do celów laboratoryjnych, a nie do użytku ludzkiego.","q_en":"Czy DSIP jest legalnie dostępny w Niemczech","a_en":"DSIP nie jest zatwierdzony jako lek w Niemczech ani w UE. Jest oferowany wyłącznie jako odczynnik badawczy do celów laboratoryjnych, a nie do użytku ludzkiego."}],"seo":{"title":"DSIP: peptyd badawczy z niespójnymi dowodami","title_en":"DSIP: peptyd badawczy z niespójnymi dowodami","description":"DSIP w pigułce: pochodzenie, mechanizm, status badań i profil bezpieczeństwa jednego z najdłużej badanych peptydów wywołujących sen.","description_en":"DSIP w pigułce: pochodzenie, mechanizm, status badań i profil bezpieczeństwa jednego z najdłużej badanych peptydów wywołujących sen."},"demo":false,"steckbrief":{"cas":"62568-57-4","molekulargewicht":"848,8 g/mol","aminosaeuren":9,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":9,"quellen":["PubChem CID 68816","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)"},"verwandt":["selank","semax","dihexa"]},{"slug":"selank","name":"Selank","synonyme":[],"kategorie":"Kognition","studienlage":"klinisch untersucht","kurz":"Syntetyczny heptapeptydowy analog własnej tuftsyny organizmu, badany pod kątem regulacji lęku i funkcji poznawczych.","kurz_en":"Syntetyczny heptapeptydowy analog własnej tuftsyny organizmu, badany pod kątem regulacji lęku i funkcji poznawczych.","beschreibung":"Selank to heptapeptyd pochodzący od własnego tetrapeptydu organizmu, tuftsyny, pierwotnie opracowany w Rosji jako lek przeciwlękowy (anksjolityk). Badania wiążą go z działaniem regulującym lęk i łagodnie wspierającym funkcje poznawcze, bez sedacji typowej dla benzodiazepin.","beschreibung_en":"Selank to heptapeptyd pochodzący od własnego tetrapeptydu organizmu, tuftsyny, pierwotnie opracowany w Rosji jako lek przeciwlękowy (anksjolityk). Badania wiążą go z działaniem regulującym lęk i łagodnie wspierającym funkcje poznawcze, bez sedacji typowej dla benzodiazepin.","mechanismus":"Opisuje się, że selank hamuje enkefalinazy, enzymy rozkładające własne enkefaliny organizmu, dzięki czemu ich poziom pozostaje dłużej podwyższony. Wiąże się go także z modulacją receptora GABA w miejscu wiązania odmiennym od miejsca benzodiazepin oraz z pośrednim wpływem na układ dopaminowy poprzez szlak enkefalinowy.","mechanismus_en":"Opisuje się, że selank hamuje enkefalinazy, enzymy rozkładające własne enkefaliny organizmu, dzięki czemu ich poziom pozostaje dłużej podwyższony. Wiąże się go także z modulacją receptora GABA w miejscu wiązania odmiennym od miejsca benzodiazepin oraz z pośrednim wpływem na układ dopaminowy poprzez szlak enkefalinowy.","evidenz":[{"art":"kliniczne","kurz":"Randomizowane badanie z udziałem 62 osób z uogólnionymi zaburzeniami lękowymi lub neurastenią porównało działanie przeciwlękowe selanku z medazepamem; dodatkowo obserwowano poprawę energii i koncentracji bez sedacji.","kurz_en":"Randomizowane badanie z udziałem 62 osób z uogólnionymi zaburzeniami lękowymi lub neurastenią porównało działanie przeciwlękowe selanku z medazepamem; dodatkowo obserwowano poprawę energii i koncentracji bez sedacji.","quelle":"Zozulya AA et al. 2008, Bjulleten Eksperimentalnoj Biologii i Mediciny, PMID 18454096"},{"art":"kliniczne","kurz":"W badaniu fMRI z udziałem 52 zdrowych uczestników podanie selanku wiązało się ze zmienioną łącznością funkcjonalną między prawym ciałem migdałowatym a prawą korą skroniową, mierzalną już 5 minut po zastosowaniu.","kurz_en":"W badaniu fMRI z udziałem 52 zdrowych uczestników podanie selanku wiązało się ze zmienioną łącznością funkcjonalną między prawym ciałem migdałowatym a prawą korą skroniową, mierzalną już 5 minut po zastosowaniu.","quelle":"Panikratova KR et al. 2020, Doklady Biological Sciences, Bd. 490, S. 9-11"}],"sicherheit":["Dostępna literatura badawcza opisuje łagodne, przejściowe działania, takie jak podrażnienie nosa przy stosowaniu donosowym.","Jednoczesne stosowanie z benzodiazepinami jest omawiane w literaturze ze względu na możliwą wzajemną interakcję receptorową.","Solidne dane dotyczące bezpieczeństwa długoterminowego z niezależnych badań przeprowadzonych poza Rosją nie są jeszcze dostępne."],"sicherheit_en":["Dostępna literatura badawcza opisuje łagodne, przejściowe działania, takie jak podrażnienie nosa przy stosowaniu donosowym.","Jednoczesne stosowanie z benzodiazepinami jest omawiane w literaturze ze względu na możliwą wzajemną interakcję receptorową.","Solidne dane dotyczące bezpieczeństwa długoterminowego z niezależnych badań przeprowadzonych poza Rosją nie są jeszcze dostępne."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Selank jest zatwierdzony jako anksjolityk w Rosji, ale nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych, gdzie jest sprzedawany wyłącznie jako odczynnik badawczy.","rechtsstatus_en":"Selank jest zatwierdzony jako anksjolityk w Rosji, ale nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych, gdzie jest sprzedawany wyłącznie jako odczynnik badawczy.","typischeMg":[5,10],"faq":[{"q":"Czy selank jest tym samym co benzodiazepina?","a":"Nie. Oba wpływają na układ GABA, ale w różny sposób. Selank wiąże się w innym miejscu i w badaniach, w przeciwieństwie do klasycznych benzodiazepin, nie wykazał działania uspokajającego ani potencjału uzależniającego.","q_en":"Czy selank jest tym samym co benzodiazepina?","a_en":"Nie. Oba wpływają na układ GABA, ale w różny sposób. Selank wiąże się w innym miejscu i w badaniach, w przeciwieństwie do klasycznych benzodiazepin, nie wykazał działania uspokajającego ani potencjału uzależniającego."},{"q":"Skąd pochodzi selank?","a":"Selank został opracowany w Rosyjskiej Akademii Nauk na bazie własnego peptydu organizmu, tuftsyny, z dodatkiem stabilizującym, który wydłuża jego trwałość w organizmie.","q_en":"Skąd pochodzi selank?","a_en":"Selank został opracowany w Rosyjskiej Akademii Nauk na bazie własnego peptydu organizmu, tuftsyny, z dodatkiem stabilizującym, który wydłuża jego trwałość w organizmie."},{"q":"Czy selank jest legalnie dostępny w Niemczech?","a":"Selank nie jest zatwierdzony jako lek w Niemczech ani w UE. Jest oferowany wyłącznie jako odczynnik badawczy do celów laboratoryjnych, nie do użytku ludzkiego.","q_en":"Czy selank jest legalnie dostępny w Niemczech?","a_en":"Selank nie jest zatwierdzony jako lek w Niemczech ani w UE. Jest oferowany wyłącznie jako odczynnik badawczy do celów laboratoryjnych, nie do użytku ludzkiego."}],"seo":{"title":"Selank: peptyd badawczy do regulacji lęku","title_en":"Selank: peptyd badawczy do regulacji lęku","description":"Selank w pigułce: pochodzenie, mechanizm, status badań i profil bezpieczeństwa peptydu badawczego, badanego pod kątem regulacji lęku i funkcji poznawczych.","description_en":"Selank w pigułce: pochodzenie, mechanizm, status badań i profil bezpieczeństwa peptydu badawczego, badanego pod kątem regulacji lęku i funkcji poznawczych."},"demo":false,"steckbrief":{"cas":"129954-34-3","molekulargewicht":"751,9 g/mol","aminosaeuren":7,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 11765600","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)"},"verwandt":["semax","epitalon","dihexa"]},{"slug":"semax","name":"Semax","synonyme":[],"kategorie":"Kognition","studienlage":"klinisch untersucht","kurz":"Syntetyczny heptapeptyd pochodzący z ACTH, zatwierdzony w Rosji do neuroprotekcji i badany w badaniach nad poznaniem i adaptacją do stresu.","kurz_en":"Syntetyczny heptapeptyd pochodzący z ACTH, zatwierdzony w Rosji do neuroprotekcji i badany w badaniach nad poznaniem i adaptacją do stresu.","beschreibung":"Semax jest heptapeptydem pochodzącym od fragmentu ACTH(4-10) hormonu stresu ACTH, zatwierdzonym w Rosji jako lek w udarze niedokrwiennym. W badaniach analizuje się go także w kontekście neuroplastyczności i funkcji poznawczych, bez aktywowania osi kortyzolowej.","beschreibung_en":"Semax jest heptapeptydem pochodzącym od fragmentu ACTH(4-10) hormonu stresu ACTH, zatwierdzonym w Rosji jako lek w udarze niedokrwiennym. W badaniach analizuje się go także w kontekście neuroplastyczności i funkcji poznawczych, bez aktywowania osi kortyzolowej.","mechanismus":"Semax jest opisywany jako zwiększający poziom BDNF i jego receptora TrkB, co jest powiązane z plastycznością neuronalną. Jako pochodna ACTH wiąże się również z receptorami melanokortynowymi, co może wpływać na poziom dopaminy, serotoniny i noradrenaliny. Wiązanie z receptorem mu-opioidowym, opisane w 2025 roku, powiązano z działaniem antyoksydacyjnym.","mechanismus_en":"Semax jest opisywany jako zwiększający poziom BDNF i jego receptora TrkB, co jest powiązane z plastycznością neuronalną. Jako pochodna ACTH wiąże się również z receptorami melanokortynowymi, co może wpływać na poziom dopaminy, serotoniny i noradrenaliny. Wiązanie z receptorem mu-opioidowym, opisane w 2025 roku, powiązano z działaniem antyoksydacyjnym.","evidenz":[{"art":"przedkliniczne","kurz":"W badaniu na szczurach pojedyncze podanie donosowe semax zwiększyło poziom białka BDNF w hipokampie 1,4-krotnie, a fosforylację TrkB 1,6-krotnie.","kurz_en":"W badaniu na szczurach pojedyncze podanie donosowe semax zwiększyło poziom białka BDNF w hipokampie 1,4-krotnie, a fosforylację TrkB 1,6-krotnie.","quelle":"PubMed ID 14556513"},{"art":"kliniczne","kurz":"W tym samym badaniu fMRI z udziałem 52 zdrowych uczestników semax wykazał również zmienioną łączność funkcjonalną między ciałem migdałowatym a korą skroniową, z efektami częściowo odróżnialnymi od selanku.","kurz_en":"W tym samym badaniu fMRI z udziałem 52 zdrowych uczestników semax wykazał również zmienioną łączność funkcjonalną między ciałem migdałowatym a korą skroniową, z efektami częściowo odróżnialnymi od selanku.","quelle":"Panikratova KR et al. 2020, Doklady Biological Sciences, Bd. 490, S. 9-11"}],"sicherheit":["Badania na zwierzętach nie wykazały dotąd poważnych działań toksycznych.","Opisano interakcję in vitro z enzymami zależnymi od miedzi, której znaczenie kliniczne nie zostało jeszcze ustalone.","Niezależne zachodnie dane dotyczące długoterminowego bezpieczeństwa u ludzi nie są jeszcze dostępne."],"sicherheit_en":["Badania na zwierzętach nie wykazały dotąd poważnych działań toksycznych.","Opisano interakcję in vitro z enzymami zależnymi od miedzi, której znaczenie kliniczne nie zostało jeszcze ustalone.","Niezależne zachodnie dane dotyczące długoterminowego bezpieczeństwa u ludzi nie są jeszcze dostępne."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Semax jest zatwierdzony jako lek na neuroprotekcję w Rosji, ale nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych, gdzie jest sprzedawany wyłącznie jako odczynnik badawczy.","rechtsstatus_en":"Semax jest zatwierdzony jako lek na neuroprotekcję w Rosji, ale nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych, gdzie jest sprzedawany wyłącznie jako odczynnik badawczy.","typischeMg":[10,30],"faq":[{"q":"Czy semax działa jak klasyczny nootropik?","a":"Badania wiążą semax głównie z działaniem neuroprotekcyjnym i związanym z BDNF, a w mniejszym stopniu z doraźnym efektem poprawy koncentracji, jak w przypadku klasycznych stymulantów.","q_en":"Czy semax działa jak klasyczny nootropik?","a_en":"Badania wiążą semax głównie z działaniem neuroprotekcyjnym i związanym z BDNF, a w mniejszym stopniu z doraźnym efektem poprawy koncentracji, jak w przypadku klasycznych stymulantów."},{"q":"Czy semax jest tym samym co selank?","a":"Nie, to dwa pokrewne rosyjskie peptydy o różnym pochodzeniu. Semax wywodzi się z ACTH i jest powiązany głównie z neuroprotekcją, selank z tuftsyny i głównie z regulacją lęku.","q_en":"Czy semax jest tym samym co selank?","a_en":"Nie, to dwa pokrewne rosyjskie peptydy o różnym pochodzeniu. Semax wywodzi się z ACTH i jest powiązany głównie z neuroprotekcją, selank z tuftsyny i głównie z regulacją lęku."},{"q":"Czy semax jest legalnie dostępny w Niemczech?","a":"Semax nie jest zatwierdzony jako lek w Niemczech ani w UE i jest oferowany wyłącznie jako odczynnik badawczy do celów laboratoryjnych, nie do użytku ludzkiego.","q_en":"Czy semax jest legalnie dostępny w Niemczech?","a_en":"Semax nie jest zatwierdzony jako lek w Niemczech ani w UE i jest oferowany wyłącznie jako odczynnik badawczy do celów laboratoryjnych, nie do użytku ludzkiego."}],"seo":{"title":"Semax: peptyd badawczy pochodzący z ACTH w neuroprotekcji","title_en":"Semax: peptyd badawczy pochodzący z ACTH w neuroprotekcji","description":"Semax w pigułce: pochodzenie, mechanizm, status badań i profil bezpieczeństwa peptydu badawczego, badanego pod kątem neuroprotekcji i funkcji poznawczych.","description_en":"Semax w pigułce: pochodzenie, mechanizm, status badań i profil bezpieczeństwa peptydu badawczego, badanego pod kątem neuroprotekcji i funkcji poznawczych."},"demo":false,"steckbrief":{"cas":"80714-61-0","molekulargewicht":"813,9 g/mol","aminosaeuren":7,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 9811102","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)"},"verwandt":["selank","epitalon","dsip"]},{"slug":"kpv","name":"KPV","synonyme":["Lys-Pro-Val","alfa-MSH(11-13)"],"kategorie":"Immunsystem","studienlage":"präklinisch","kurz":"Trójaminokwasowy fragment alfa-MSH, badany na modelach zwierzęcych pod kątem właściwości przeciwzapalnych w jelitach i na skórze.","kurz_en":"Trójaminokwasowy fragment alfa-MSH, badany na modelach zwierzęcych pod kątem właściwości przeciwzapalnych w jelitach i na skórze.","beschreibung":"KPV to tripeptyd złożony z aminokwasów lizyny, proliny i waliny, pochodzący z C-końca hormonu alfa-MSH. Należy do najmniejszych peptydów badanych w badaniach nad stanem zapalnym, ze szczególnym uwzględnieniem zwierzęcych modeli przewlekłej choroby zapalnej jelit i zapalenia skóry. Badania na ludziach nie są jeszcze dostępne.","beschreibung_en":"KPV to tripeptyd złożony z aminokwasów lizyny, proliny i waliny, pochodzący z C-końca hormonu alfa-MSH. Należy do najmniejszych peptydów badanych w badaniach nad stanem zapalnym, ze szczególnym uwzględnieniem zwierzęcych modeli przewlekłej choroby zapalnej jelit i zapalenia skóry. Badania na ludziach nie są jeszcze dostępne.","mechanismus":"W modelach przedklinicznych opisany jest efekt przeciwzapalny, który działa niezależnie od receptora melanokortynowego i opiera się zamiast tego na wchłanianiu do komórek jelitowych poprzez transporter peptydowy PepT1. Opisuje się tam hamowanie aktywacji NF-κB, centralnego przełącznika w odpowiedzi zapalnej. Dokładne mechanizmy u ludzi nie były badane.","mechanismus_en":"W modelach przedklinicznych opisany jest efekt przeciwzapalny, który działa niezależnie od receptora melanokortynowego i opiera się zamiast tego na wchłanianiu do komórek jelitowych poprzez transporter peptydowy PepT1. Opisuje się tam hamowanie aktywacji NF-κB, centralnego przełącznika w odpowiedzi zapalnej. Dokładne mechanizmy u ludzi nie były badane.","evidenz":[{"art":"przedkliniczne","kurz":"Badanie na dwóch mysich modelach zapalenia jelita grubego opisało szybszy powrót masy ciała i wyraźnie zmniejszone nacieki zapalne w tkance jelita po KPV w porównaniu ze zwierzętami nieleczonymi.","kurz_en":"Badanie na dwóch mysich modelach zapalenia jelita grubego opisało szybszy powrót masy ciała i wyraźnie zmniejszone nacieki zapalne w tkance jelita po KPV w porównaniu ze zwierzętami nieleczonymi.","quelle":"Kannengiesser et al. 2008, Inflammatory Bowel Diseases, PMID 18092346"},{"art":"przedkliniczne","kurz":"Badanie wykazało, że działanie przeciwzapalne KPV w modelu mysim zachodzi poprzez wychwyt przez transporter peptydowy PepT1, a nie przez receptor melanokortynowy.","kurz_en":"Badanie wykazało, że działanie przeciwzapalne KPV w modelu mysim zachodzi poprzez wychwyt przez transporter peptydowy PepT1, a nie przez receptor melanokortynowy.","quelle":"Dalmasso et al. 2008, Gastroenterology, PMID 18061177"},{"art":"przedkliniczne","kurz":"Badanie z użyciem nanocząstek funkcjonalizowanych kwasem hialuronowym, służących do ukierunkowanego doustnego uwalniania KPV w jelicie grubym, opisało istotne zmniejszenie stanu zapalnego u myszy z zapaleniem jelita grubego w porównaniu z niezmodyfikowanym KPV.","kurz_en":"Badanie z użyciem nanocząstek funkcjonalizowanych kwasem hialuronowym, służących do ukierunkowanego doustnego uwalniania KPV w jelicie grubym, opisało istotne zmniejszenie stanu zapalnego u myszy z zapaleniem jelita grubego w porównaniu z niezmodyfikowanym KPV.","quelle":"Xiao et al. 2017, Molecular Therapy, PMID 28143741"}],"sicherheit":["Badania bezpieczeństwa na ludziach dotyczących KPV nie są jeszcze dostępne, wszystkie dowody pochodzą z modeli komórkowych i zwierzęcych.","Nie zgłoszono poważnych działań niepożądanych w dostępnych badaniach na zwierzętach.","Interakcje z innymi substancjami nie były badane u ludzi.","Produkty z niekontrolowanej produkcji niosą ryzyko zanieczyszczenia niezależne od samej cząsteczki."],"sicherheit_en":["Badania bezpieczeństwa na ludziach dotyczących KPV nie są jeszcze dostępne, wszystkie dowody pochodzą z modeli komórkowych i zwierzęcych.","Nie zgłoszono poważnych działań niepożądanych w dostępnych badaniach na zwierzętach.","Interakcje z innymi substancjami nie były badane u ludzi.","Produkty z niekontrolowanej produkcji niosą ryzyko zanieczyszczenia niezależne od samej cząsteczki."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"KPV nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych i nie jest klasyfikowany jako produkt spożywczy. Jest sprzedawany wyłącznie jako substancja chemiczna do badań.","rechtsstatus_en":"KPV nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych i nie jest klasyfikowany jako produkt spożywczy. Jest sprzedawany wyłącznie jako substancja chemiczna do badań.","typischeMg":[],"faq":[{"q":"Skąd pochodzi KPV?","a":"KPV jest fragmentem hormonu alfa-MSH, składającym się z trzech aminokwasów lizyny, proliny i waliny.","q_en":"Skąd pochodzi KPV?","a_en":"KPV jest fragmentem hormonu alfa-MSH, składającym się z trzech aminokwasów lizyny, proliny i waliny."},{"q":"Czy KPV działa poprzez receptor melanokortynowy?","a":"Nie. W modelach zwierzęcych działanie przeciwzapalne opisuje się jako niezależne od receptora melanokortynowego; opiera się ono na transporterze PepT1.","q_en":"Czy KPV działa poprzez receptor melanokortynowy?","a_en":"Nie. W modelach zwierzęcych działanie przeciwzapalne opisuje się jako niezależne od receptora melanokortynowego; opiera się ono na transporterze PepT1."},{"q":"Czy istnieją badania na ludziach dotyczące KPV?","a":"Nie, jak dotąd istnieją wyłącznie badania na komórkach i zwierzętach, głównie dotyczące chorób zapalnych jelit.","q_en":"Czy istnieją badania na ludziach dotyczące KPV?","a_en":"Nie, jak dotąd istnieją wyłącznie badania na komórkach i zwierzętach, głównie dotyczące chorób zapalnych jelit."}],"seo":{"title":"KPV: profil badawczy i dowody","title_en":"KPV: profil badawczy i dowody","description":"Przegląd KPV: pochodzenie z alfa-MSH, mechanizm, dowody przedkliniczne i profil bezpieczeństwa, przedstawiony rzeczowo w kontekście badawczym.","description_en":"Przegląd KPV: pochodzenie z alfa-MSH, mechanizm, dowody przedkliniczne i profil bezpieczeństwa, przedstawiony rzeczowo w kontekście badawczym."},"demo":false,"steckbrief":{"cas":"67727-97-3","molekulargewicht":"342,43 g/mol","aminosaeuren":3,"halbwertszeit":null,"reinheitsstandard":null,"loeslichkeit":null,"sequenzLaenge":3,"quellen":["PubChem CID 125672","chemverify Katalog 14.09.2026"]},"verwandt":["ll-37","thymosin-alpha-1","bpc-157"]},{"slug":"ll-37","name":"LL-37","synonyme":["Katelicydyna","hCAP18(134-170)","Ludzka katelicydyna"],"kategorie":"Immunsystem","studienlage":"klinisch untersucht","kurz":"Naturalnie występujący peptyd przeciwdrobnoustrojowy złożony z 37 aminokwasów, który chroni skórę i błony śluzowe, badany w badaniach klinicznych pod kątem gojenia ran.","kurz_en":"Naturalnie występujący peptyd przeciwdrobnoustrojowy złożony z 37 aminokwasów, który chroni skórę i błony śluzowe, badany w badaniach klinicznych pod kątem gojenia ran.","beschreibung":"LL-37 jest jedynym znanym u ludzi przedstawicielem rodziny peptydów katelicydyn i jest wytwarzany przez komórki odpornościowe, a także komórki skóry i błon śluzowych w odpowiedzi na uraz lub infekcję. Powstaje przez odcięcie od białka prekursorowego hCAP18. Badania kliniczne koncentrowały się głównie na miejscowym stosowaniu w trudno gojących się ranach, takich jak żylne owrzodzenia podudzi i owrzodzenia stopy cukrzycowej.","beschreibung_en":"LL-37 jest jedynym znanym u ludzi przedstawicielem rodziny peptydów katelicydyn i jest wytwarzany przez komórki odpornościowe, a także komórki skóry i błon śluzowych w odpowiedzi na uraz lub infekcję. Powstaje przez odcięcie od białka prekursorowego hCAP18. Badania kliniczne koncentrowały się głównie na miejscowym stosowaniu w trudno gojących się ranach, takich jak żylne owrzodzenia podudzi i owrzodzenia stopy cukrzycowej.","mechanismus":"LL-37 wnika w błony komórek bakteryjnych i zaburza ich integralność, co daje bezpośrednie działanie przeciwdrobnoustrojowe wobec szerokiego spektrum patogenów. Opisano dodatkowe działanie immunomodulujące, w tym przyciąganie komórek odpornościowych do miejsca rany i wspieranie angiogenezy. Endogenne wytwarzanie może być nasilane przez określone bodźce, takie jak analogi witaminy D.","mechanismus_en":"LL-37 wnika w błony komórek bakteryjnych i zaburza ich integralność, co daje bezpośrednie działanie przeciwdrobnoustrojowe wobec szerokiego spektrum patogenów. Opisano dodatkowe działanie immunomodulujące, w tym przyciąganie komórek odpornościowych do miejsca rany i wspieranie angiogenezy. Endogenne wytwarzanie może być nasilane przez określone bodźce, takie jak analogi witaminy D.","evidenz":[{"art":"kliniczne","kurz":"Randomizowane, kontrolowane placebo badanie z pierwszym podaniem u ludzi (first-in-human) z udziałem 34 pacjentów z trudno gojącymi się żylnymi owrzodzeniami podudzi opisało około 3- do 6-krotnie szybsze tempo gojenia przy dwóch niższych stężeniach LL-37 w porównaniu z placebo.","kurz_en":"Randomizowane, kontrolowane placebo badanie z pierwszym podaniem u ludzi (first-in-human) z udziałem 34 pacjentów z trudno gojącymi się żylnymi owrzodzeniami podudzi opisało około 3- do 6-krotnie szybsze tempo gojenia przy dwóch niższych stężeniach LL-37 w porównaniu z placebo.","quelle":"Grönberg et al. 2014, Wound Repair and Regeneration, PMID 25041740"},{"art":"kliniczne","kurz":"Randomizowane badanie podwójnie zaślepione u pacjentów z owrzodzeniami stopy cukrzycowej oceniło krem zawierający LL-37 i opisało wpływ na kolonizację bakteryjną, markery stanu zapalnego i tempo gojenia w porównaniu z placebo.","kurz_en":"Randomizowane badanie podwójnie zaślepione u pacjentów z owrzodzeniami stopy cukrzycowej oceniło krem zawierający LL-37 i opisało wpływ na kolonizację bakteryjną, markery stanu zapalnego i tempo gojenia w porównaniu z placebo.","quelle":"Miranda et al. 2023, Archives of Dermatological Research, PMID 37480520"},{"art":"kliniczne","kurz":"Badanie skóry człowieka opisało, że endogenna produkcja hCAP18/LL-37 zwiększa się po urazie i może być dodatkowo wzmacniana przez miejscowe stosowanie analogu witaminy D calcipotriolu.","kurz_en":"Badanie skóry człowieka opisało, że endogenna produkcja hCAP18/LL-37 zwiększa się po urazie i może być dodatkowo wzmacniana przez miejscowe stosowanie analogu witaminy D calcipotriolu.","quelle":"Heilborn et al. 2010, Experimental Dermatology, PMID 19878298"}],"sicherheit":["W dostępnych badaniach randomizowanych miejscowe stosowanie LL-37 opisano jako bezpieczne i dobrze tolerowane, bez poważnych zdarzeń niepożądanych.","Badane populacje były w każdym przypadku małe; większe badania kontrolowane placebo z większą liczbą uczestników dopiero się oczekuje.","Ogólnoustrojowe formy podawania i długoterminowe bezpieczeństwo u ludzi nie były badane w takim samym zakresie jak stosowanie miejscowe.","Produkty z niekontrolowanej produkcji niosą ryzyko zanieczyszczenia niezależne od samej cząsteczki."],"sicherheit_en":["W dostępnych badaniach randomizowanych miejscowe stosowanie LL-37 opisano jako bezpieczne i dobrze tolerowane, bez poważnych zdarzeń niepożądanych.","Badane populacje były w każdym przypadku małe; większe badania kontrolowane placebo z większą liczbą uczestników dopiero się oczekuje.","Ogólnoustrojowe formy podawania i długoterminowe bezpieczeństwo u ludzi nie były badane w takim samym zakresie jak stosowanie miejscowe.","Produkty z niekontrolowanej produkcji niosą ryzyko zanieczyszczenia niezależne od samej cząsteczki."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"LL-37 nie jest zatwierdzony jako lek w Niemczech, UE ani w Stanach Zjednoczonych i nie jest klasyfikowany jako produkt spożywczy. Jest sprzedawany wyłącznie jako odczynnik badawczy, a badawcze formulacje kliniczne LL-37 są powiązane z poszczególnymi programami badań.","rechtsstatus_en":"LL-37 nie jest zatwierdzony jako lek w Niemczech, UE ani w Stanach Zjednoczonych i nie jest klasyfikowany jako produkt spożywczy. Jest sprzedawany wyłącznie jako odczynnik badawczy, a badawcze formulacje kliniczne LL-37 są powiązane z poszczególnymi programami badań.","typischeMg":[],"faq":[{"q":"Czy LL-37 jest naturalnym peptydem ludzkim?","a":"Tak. Jest to jedyny znany ludzki peptyd z rodziny katelicydyn, wytwarzany przez komórki odpornościowe, skóry i błon śluzowych, zwłaszcza podczas urazu lub infekcji.","q_en":"Czy LL-37 jest naturalnym peptydem ludzkim?","a_en":"Tak. Jest to jedyny znany ludzki peptyd z rodziny katelicydyn, wytwarzany przez komórki odpornościowe, skóry i błon śluzowych, zwłaszcza podczas urazu lub infekcji."},{"q":"Czy istnieją badania kliniczne dotyczące LL-37?","a":"Tak, kilka badań randomizowanych oceniało miejscowe stosowanie na trudno gojących się ranach, takich jak żylne owrzodzenia podudzi i owrzodzenia stopy cukrzycowej, z przeważnie pozytywnymi wynikami dotyczącymi bezpieczeństwa.","q_en":"Czy istnieją badania kliniczne dotyczące LL-37?","a_en":"Tak, kilka badań randomizowanych oceniało miejscowe stosowanie na trudno gojących się ranach, takich jak żylne owrzodzenia podudzi i owrzodzenia stopy cukrzycowej, z przeważnie pozytywnymi wynikami dotyczącymi bezpieczeństwa."},{"q":"Czy LL-37 działa wyłącznie jako środek przeciwdrobnoustrojowy?","a":"Nie, oprócz bezpośredniego działania na błony bakteryjne opisuje się także działanie immunomodulujące, takie jak przyciąganie komórek odpornościowych i wspieranie powstawania naczyń krwionośnych.","q_en":"Czy LL-37 działa wyłącznie jako środek przeciwdrobnoustrojowy?","a_en":"Nie, oprócz bezpośredniego działania na błony bakteryjne opisuje się także działanie immunomodulujące, takie jak przyciąganie komórek odpornościowych i wspieranie powstawania naczyń krwionośnych."}],"seo":{"title":"LL-37: profil badawczy i dowody","title_en":"LL-37: profil badawczy i dowody","description":"Przegląd LL-37: naturalnie występująca katelicydyna, mechanizm działania, dowody kliniczne dotyczące gojenia ran oraz profil bezpieczeństwa w kontekście badawczym.","description_en":"Przegląd LL-37: naturalnie występująca katelicydyna, mechanizm działania, dowody kliniczne dotyczące gojenia ran oraz profil bezpieczeństwa w kontekście badawczym."},"demo":false,"steckbrief":{"cas":"154947-66-7","molekulargewicht":"4493 g/mol","aminosaeuren":37,"halbwertszeit":null,"reinheitsstandard":"≥ 95 % (HPLC, standard handlowy)","loeslichkeit":"rozpuszczalny w wodzie i DMSO","sequenzLaenge":37,"quellen":["PubChem CID 16198951","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 95 % (HPLC, standard handlowy)","loeslichkeit_en":"rozpuszczalny w wodzie i DMSO"},"verwandt":["kpv","thymosin-alpha-1","bpc-157"]},{"slug":"thymosin-alpha-1","name":"Tymozyna alfa 1","synonyme":["Tα1","Zadaxin (nazwa handlowa)"],"kategorie":"Immunsystem","studienlage":"zugelassenes Arzneimittel","kurz":"Naturalny peptyd odpornościowy pochodzący z grasicy, zatwierdzony jako lek w ponad 35 krajach, choć obecnie nie w Niemczech, Austrii ani Szwajcarii.","kurz_en":"Naturalny peptyd odpornościowy pochodzący z grasicy, zatwierdzony jako lek w ponad 35 krajach, choć obecnie nie w Niemczech, Austrii ani Szwajcarii.","beschreibung":"Tymozyna alfa 1 to 28-aminokwasowy peptyd pierwotnie wyizolowany z grasicy, centralnego narządu, w którym dojrzewają limfocyty T. Działa jako modulator układu odpornościowego i jest wykorzystywana zarówno w badaniach klinicznych, jak i, pod nazwą handlową Zadaxin, jako zatwierdzony lek w niektórych schorzeniach immunologicznych. Obszary badań obejmują przewlekłe zakażenia wirusowe, odpowiedź immunologiczną na szczepienia oraz wspierającą rolę w onkologii.","beschreibung_en":"Tymozyna alfa 1 to 28-aminokwasowy peptyd pierwotnie wyizolowany z grasicy, centralnego narządu, w którym dojrzewają limfocyty T. Działa jako modulator układu odpornościowego i jest wykorzystywana zarówno w badaniach klinicznych, jak i, pod nazwą handlową Zadaxin, jako zatwierdzony lek w niektórych schorzeniach immunologicznych. Obszary badań obejmują przewlekłe zakażenia wirusowe, odpowiedź immunologiczną na szczepienia oraz wspierającą rolę w onkologii.","mechanismus":"Działanie opisuje się głównie poprzez receptory Toll-podobne na komórkach odpornościowych, struktury rozpoznające cząsteczki, które reagują na patogeny. Uruchamia to szlaki, takie jak NF-κB i wytwarzanie interferonu, angażując jednocześnie zarówno wrodzony, jak i nabyty układ odpornościowy. Opisywane efekty obejmują zwiększoną aktywność limfocytów T i komórek NK (naturalnych zabójców), a także lepsze wytwarzanie przeciwciał.","mechanismus_en":"Działanie opisuje się głównie poprzez receptory Toll-podobne na komórkach odpornościowych, struktury rozpoznające cząsteczki, które reagują na patogeny. Uruchamia to szlaki, takie jak NF-κB i wytwarzanie interferonu, angażując jednocześnie zarówno wrodzony, jak i nabyty układ odpornościowy. Opisywane efekty obejmują zwiększoną aktywność limfocytów T i komórek NK (naturalnych zabójców), a także lepsze wytwarzanie przeciwciał.","evidenz":[{"art":"kliniczne","kurz":"Retrospektywna analiza 76 pacjentów z ciężkim COVID-19 w dwóch szpitalach opisała niższą śmiertelność po zastosowaniu tymozyny alfa 1 w porównaniu z grupą nieleczoną, wraz z odbudową liczby limfocytów T.","kurz_en":"Retrospektywna analiza 76 pacjentów z ciężkim COVID-19 w dwóch szpitalach opisała niższą śmiertelność po zastosowaniu tymozyny alfa 1 w porównaniu z grupą nieleczoną, wraz z odbudową liczby limfocytów T.","quelle":"Liu et al. 2020, Clinical Infectious Diseases"},{"art":"kliniczne","kurz":"Randomizowane badanie z udziałem 42 pacjentów z niedrobnokomórkowym rakiem płuca po radioterapii opisało szybszą normalizację funkcji limfocytów T po zastosowaniu tymozyny alfa 1 w porównaniu z placebo, a także korzyść w zakresie przeżycia, najbardziej wyraźną u pacjentów z mniejszymi guzami.","kurz_en":"Randomizowane badanie z udziałem 42 pacjentów z niedrobnokomórkowym rakiem płuca po radioterapii opisało szybszą normalizację funkcji limfocytów T po zastosowaniu tymozyny alfa 1 w porównaniu z placebo, a także korzyść w zakresie przeżycia, najbardziej wyraźną u pacjentów z mniejszymi guzami.","quelle":"Schulof et al. 1985, Journal of Biological Response Modifiers, PMID 3998766"}],"sicherheit":["Duże bazy danych bezpieczeństwa obejmujące tysiące pacjentów opisują głównie łagodne, przejściowe reakcje w miejscu wstrzyknięcia i lekkie zmęczenie.","Rzadkie zgłoszenia obejmują reakcje skórne alergiczne i tymczasowe nasilenie istniejących wcześniej schorzeń autoimmunologicznych.","Jednoczesne stosowanie leku immunosupresyjnego jest wymienione jako przeciwwskazanie w informacji o produkcie, ponieważ działają one w przeciwnych kierunkach.","Informacja o produkcie zaleca ostrożność w przypadku aktywnego przeszczepiania narządów oraz aktywnej choroby autoimmunologicznej."],"sicherheit_en":["Duże bazy danych bezpieczeństwa obejmujące tysiące pacjentów opisują głównie łagodne, przejściowe reakcje w miejscu wstrzyknięcia i lekkie zmęczenie.","Rzadkie zgłoszenia obejmują reakcje skórne alergiczne i tymczasowe nasilenie istniejących wcześniej schorzeń autoimmunologicznych.","Jednoczesne stosowanie leku immunosupresyjnego jest wymienione jako przeciwwskazanie w informacji o produkcie, ponieważ działają one w przeciwnych kierunkach.","Informacja o produkcie zaleca ostrożność w przypadku aktywnego przeszczepiania narządów oraz aktywnej choroby autoimmunologicznej."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Pod nazwą handlową Zadaxin tymozyna alfa 1 jest zatwierdzona jako lek do leczenia określonych schorzeń immunologicznych, w tym wirusowego zapalenia wątroby typu B i C, w ponad 35 krajach. Obecnie nie jest zatwierdzona w Niemczech, Austrii ani Szwajcarii, gdzie pozyskiwanie znajduje się w szarej strefie prawnej.","rechtsstatus_en":"Pod nazwą handlową Zadaxin tymozyna alfa 1 jest zatwierdzona jako lek do leczenia określonych schorzeń immunologicznych, w tym wirusowego zapalenia wątroby typu B i C, w ponad 35 krajach. Obecnie nie jest zatwierdzona w Niemczech, Austrii ani Szwajcarii, gdzie pozyskiwanie znajduje się w szarej strefie prawnej.","typischeMg":[],"faq":[{"q":"Czy tymozyna alfa 1 jest zatwierdzonym lekiem?","a":"Tak, pod nazwą handlową Zadaxin w ponad 35 krajach, m.in. w przewlekłym zapaleniu wątroby typu B i C. Obecnie nie ma zatwierdzenia w Niemczech, Austrii ani Szwajcarii.","q_en":"Czy tymozyna alfa 1 jest zatwierdzonym lekiem?","a_en":"Tak, pod nazwą handlową Zadaxin w ponad 35 krajach, m.in. w przewlekłym zapaleniu wątroby typu B i C. Obecnie nie ma zatwierdzenia w Niemczech, Austrii ani Szwajcarii."},{"q":"Na co działa tymozyna alfa 1 w układzie odpornościowym?","a":"Działa jednocześnie na wrodzony i nabyty układ odpornościowy, m.in. poprzez zwiększoną aktywność limfocytów T i komórek NK (naturalnych zabójców) oraz lepsze wytwarzanie przeciwciał.","q_en":"Na co działa tymozyna alfa 1 w układzie odpornościowym?","a_en":"Działa jednocześnie na wrodzony i nabyty układ odpornościowy, m.in. poprzez zwiększoną aktywność limfocytów T i komórek NK (naturalnych zabójców) oraz lepsze wytwarzanie przeciwciał."},{"q":"Czy istnieją badania na ludziach dotyczące tymozyny alfa 1?","a":"Tak, w porównaniu z wieloma innymi peptydami istnieje szersza baza badań klinicznych, w tym prace nad ciężkimi infekcjami wirusowymi, wspierająca rola w leczeniu nowotworów i odpowiedź na szczepionki.","q_en":"Czy istnieją badania na ludziach dotyczące tymozyny alfa 1?","a_en":"Tak, w porównaniu z wieloma innymi peptydami istnieje szersza baza badań klinicznych, w tym prace nad ciężkimi infekcjami wirusowymi, wspierająca rola w leczeniu nowotworów i odpowiedź na szczepionki."}],"seo":{"title":"Tymozyna alfa 1: profil badawczy i dowody","title_en":"Tymozyna alfa 1: profil badawczy i dowody","description":"Przegląd tymozyny alfa 1: modulacja układu odpornościowego, status zatwierdzenia międzynarodowego, dowody kliniczne i profil bezpieczeństwa.","description_en":"Przegląd tymozyny alfa 1: modulacja układu odpornościowego, status zatwierdzenia międzynarodowego, dowody kliniczne i profil bezpieczeństwa."},"demo":false,"steckbrief":{"cas":"62304-98-7","molekulargewicht":"3108,3 g/mol","aminosaeuren":28,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":28,"quellen":["PubChem CID 16130571","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)"},"verwandt":["bpc-157","tb-500","kpv","ll-37"]},{"slug":"epitalon","name":"Epitalon","synonyme":["Epithalon","Tetrapeptyd AEDG"],"kategorie":"Sonstige","studienlage":"präklinisch","kurz":"Syntetyczny tetrapeptyd, badany w badaniach nad starzeniem się jako substancja badawcza związana ze starzeniem się komórkowym.","kurz_en":"Syntetyczny tetrapeptyd, badany w badaniach nad starzeniem się jako substancja badawcza związana ze starzeniem się komórkowym.","beschreibung":"Epitalon to syntetyczny tetrapeptyd opracowany przez Vladimira Khavinsona w petersburskim Instytucie Bioregulacji i Gerontologii. Jest badany w badaniach przedklinicznych w związku ze starzeniem komórkowym i regulacją aktywności telomerazy. Solidne dane kliniczne u ludzi nadal nie są dostępne.","beschreibung_en":"Epitalon to syntetyczny tetrapeptyd opracowany przez Vladimira Khavinsona w petersburskim Instytucie Bioregulacji i Gerontologii. Jest badany w badaniach przedklinicznych w związku ze starzeniem komórkowym i regulacją aktywności telomerazy. Solidne dane kliniczne u ludzi nadal nie są dostępne.","mechanismus":"Epitalon został opisany jako zwiększający aktywność telomerazy w kulturach komórkowych, co było związane z wydłużaniem telomerów in vitro. Opisano również działanie na syntezę melatoniny i na cząsteczki sygnalizacyjne układu odpornościowego.","mechanismus_en":"Epitalon został opisany jako zwiększający aktywność telomerazy w kulturach komórkowych, co było związane z wydłużaniem telomerów in vitro. Opisano również działanie na syntezę melatoniny i na cząsteczki sygnalizacyjne układu odpornościowego.","evidenz":[{"art":"przedkliniczne","kurz":"W hodowlach ludzkich fibroblastów płodowych epitalon indukował ekspresję katalitycznej podjednostki telomerazy i mierzalną aktywność telomerazy, co wiązało się z wydłużaniem telomerów.","kurz_en":"W hodowlach ludzkich fibroblastów płodowych epitalon indukował ekspresję katalitycznej podjednostki telomerazy i mierzalną aktywność telomerazy, co wiązało się z wydłużaniem telomerów.","quelle":"Khavinson VKh, Bondarev IE, Butyugov AA 2003, Bulletin of Experimental Biology and Medicine 135:590-592"},{"art":"przedkliniczne","kurz":"W modelach zwierzęcych opisano działanie epitalonu na uwalnianie melatoniny i na parametry układu odpornościowego, z wynikami mieszanymi dotyczącymi długości życia w zależności od użytego modelu i protokołu.","kurz_en":"W modelach zwierzęcych opisano działanie epitalonu na uwalnianie melatoniny i na parametry układu odpornościowego, z wynikami mieszanymi dotyczącymi długości życia w zależności od użytego modelu i protokołu.","quelle":"Khavinson VKh, Morozov VG 2003, Neuroendocrinology Letters"}],"sicherheit":["Badania przedkliniczne do tej pory nie wykazały żadnych poważnych działań toksycznych.","Nie są dostępne kontrolowane badania bezpieczeństwa na ludziach spełniające standardy badań zachodnich.","Nie istnieją solidne dane dotyczące długotrwałego stosowania."],"sicherheit_en":["Badania przedkliniczne do tej pory nie wykazały żadnych poważnych działań toksycznych.","Nie są dostępne kontrolowane badania bezpieczeństwa na ludziach spełniające standardy badań zachodnich.","Nie istnieją solidne dane dotyczące długotrwałego stosowania."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Epitalon nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych i jest sprzedawany wyłącznie jako odczynnik badawczy do celów laboratoryjnych.","rechtsstatus_en":"Epitalon nie jest zatwierdzony jako lek w Niemczech, UE ani Stanach Zjednoczonych i jest sprzedawany wyłącznie jako odczynnik badawczy do celów laboratoryjnych.","typischeMg":[10,20],"faq":[{"q":"Czy epitalon był badany u ludzi?","a":"Dostępne dane pochodzą głównie z badań w kulturach komórkowych i modelach zwierzęcych. Kontrolowane badania kliniczne na ludziach spełniające standardy zachodnie nie są jeszcze dostępne.","q_en":"Czy epitalon był badany u ludzi?","a_en":"Dostępne dane pochodzą głównie z badań w kulturach komórkowych i modelach zwierzęcych. Kontrolowane badania kliniczne na ludziach spełniające standardy zachodnie nie są jeszcze dostępne."},{"q":"Co epitalon ma wspólnego z telomerami?","a":"W badaniach na kulturach komórkowych zaobserwowano wzrost aktywności telomerazy i wydłużanie telomerów. Czy przekłada się to na cały organizm, pozostaje kwestią otwartą.","q_en":"Co epitalon ma wspólnego z telomerami?","a_en":"W badaniach na kulturach komórkowych zaobserwowano wzrost aktywności telomerazy i wydłużanie telomerów. Czy przekłada się to na cały organizm, pozostaje kwestią otwartą."},{"q":"Czy epitalon jest legalnie dostępny w Niemczech?","a":"Epitalon nie jest zatwierdzony jako lek i jest oferowany wyłącznie jako odczynnik badawczy, nie do użytku ludzkiego.","q_en":"Czy epitalon jest legalnie dostępny w Niemczech?","a_en":"Epitalon nie jest zatwierdzony jako lek i jest oferowany wyłącznie jako odczynnik badawczy, nie do użytku ludzkiego."}],"seo":{"title":"Epitalon: Tetrapeptyd w badaniach nad starzeniem się","title_en":"Epitalon: Tetrapeptyd w badaniach nad starzeniem się","description":"Epitalon w pigułce: mechanizm, stan badań przedklinicznych i profil bezpieczeństwa badawczego peptydu telomerazowego Khavinsona.","description_en":"Epitalon w pigułce: mechanizm, stan badań przedklinicznych i profil bezpieczeństwa badawczego peptydu telomerazowego Khavinsona."},"demo":false,"steckbrief":{"cas":"307297-39-8","molekulargewicht":"390,35 g/mol","aminosaeuren":4,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":4,"quellen":["PubChem CID 219042","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)"},"verwandt":["melanotan-2","selank","semax","dsip"]},{"slug":"kisspeptin","name":"Kisspeptyna-10","synonyme":["Metastin (45-54)","KP-10"],"kategorie":"Sonstige","studienlage":"klinisch untersucht","kurz":"Najkrótszy bioaktywny fragment własnego systemu kisspeptyny organizmu, badany w badaniach endokrynnych dotyczących kontroli osi podwzgórze-przysadka-gonady.","kurz_en":"Najkrótszy bioaktywny fragment własnego systemu kisspeptyny organizmu, badany w badaniach endokrynnych dotyczących kontroli osi podwzgórze-przysadka-gonady.","beschreibung":"Kisspeptyna-10 jest najkrótszym fragmentem własnego peptydu organizmu, kisspeptyny (metastyny), który zachowuje pełną aktywność na receptorze KISS1R. W badaniach służy do bezpośredniego wywoływania uwalniania GnRH oraz do badania osi podwzgórze-przysadka-gonady w kwestiach rozwoju pokwitania, hipogonadyzmu i płodności. Większe badania kliniczne z punktami końcowymi, takimi jak dojrzewanie oocytów czy pobudzenie seksualne, wykorzystywały w większości dłuższą, naturalną izoformę, kisspeptynę-54, która działa na ten sam receptor.","beschreibung_en":"Kisspeptyna-10 jest najkrótszym fragmentem własnego peptydu organizmu, kisspeptyny (metastyny), który zachowuje pełną aktywność na receptorze KISS1R. W badaniach służy do bezpośredniego wywoływania uwalniania GnRH oraz do badania osi podwzgórze-przysadka-gonady w kwestiach rozwoju pokwitania, hipogonadyzmu i płodności. Większe badania kliniczne z punktami końcowymi, takimi jak dojrzewanie oocytów czy pobudzenie seksualne, wykorzystywały w większości dłuższą, naturalną izoformę, kisspeptynę-54, która działa na ten sam receptor.","mechanismus":"Kisspeptyna-10 wiąże się z receptorem sprzężonym z białkiem G, KISS1R (GPR54), na neuronach GnRH w podwzgórzu. Poprzez kaskadę sygnałową zależną od Gq/11, z napływem wapnia, depolaryzuje te neurony i wywołuje pulsacyjne uwalnianie GnRH, które dalej reguluje wydzielanie LH i FSH z przysadki mózgowej. U mężczyzn bolus kisspeptyny-10 zwiększał poziom LH i częstotliwość pulsów, przy czym efekt był silniejszy przy wyższych podanych ilościach. Natomiast długotrwała lub wysokoczęstotliwościowa stymulacja receptora może prowadzić do desensytyzacji KISS1R i osłabienia odpowiedzi LH.","mechanismus_en":"Kisspeptyna-10 wiąże się z receptorem sprzężonym z białkiem G, KISS1R (GPR54), na neuronach GnRH w podwzgórzu. Poprzez kaskadę sygnałową zależną od Gq/11, z napływem wapnia, depolaryzuje te neurony i wywołuje pulsacyjne uwalnianie GnRH, które dalej reguluje wydzielanie LH i FSH z przysadki mózgowej. U mężczyzn bolus kisspeptyny-10 zwiększał poziom LH i częstotliwość pulsów, przy czym efekt był silniejszy przy wyższych podanych ilościach. Natomiast długotrwała lub wysokoczęstotliwościowa stymulacja receptora może prowadzić do desensytyzacji KISS1R i osłabienia odpowiedzi LH.","evidenz":[{"art":"kliniczne","kurz":"W badaniu u zdrowych mężczyzn dożylny bolus kisspeptyny-10 podnosił poziom LH, a efekt rósł wraz z wyższymi ilościami, natomiast ciągły wlew o niskim stężeniu dodatkowo zwiększał częstotliwość pulsów LH.","kurz_en":"W badaniu u zdrowych mężczyzn dożylny bolus kisspeptyny-10 podnosił poziom LH, a efekt rósł wraz z wyższymi ilościami, natomiast ciągły wlew o niskim stężeniu dodatkowo zwiększał częstotliwość pulsów LH.","quelle":"George JT et al. 2011, The Journal of Clinical Endocrinology & Metabolism, PMID 21632807"},{"art":"kliniczne","kurz":"W randomizowanym badaniu z udziałem 60 kobiet z wysokim ryzykiem OHSS pojedynczy zastrzyk pokrewnej izoformy, kisspeptyny-54, wywołał dojrzewanie oocytów w 95 procentach przypadków podczas cyklu IVF, bez obserwowanego umiarkowanego lub ciężkiego OHSS.","kurz_en":"W randomizowanym badaniu z udziałem 60 kobiet z wysokim ryzykiem OHSS pojedynczy zastrzyk pokrewnej izoformy, kisspeptyny-54, wywołał dojrzewanie oocytów w 95 procentach przypadków podczas cyklu IVF, bez obserwowanego umiarkowanego lub ciężkiego OHSS.","quelle":"Jayasena CN et al. 2015, The Journal of Clinical Endocrinology & Metabolism, PMID 26192876"},{"art":"kliniczne","kurz":"W randomizowanym badaniu z placebo u 32 mężczyzn z zaburzeniem hipoaktywnego pożądania seksualnego pojedynczy wlew izoformy, kisspeptyny-54, zwiększył aktywność mózgu związaną z reakcją seksualną i obrzmienie prącia (tumescencję) podczas oglądania filmu erotycznego w porównaniu z placebo.","kurz_en":"W randomizowanym badaniu z placebo u 32 mężczyzn z zaburzeniem hipoaktywnego pożądania seksualnego pojedynczy wlew izoformy, kisspeptyny-54, zwiększył aktywność mózgu związaną z reakcją seksualną i obrzmienie prącia (tumescencję) podczas oglądania filmu erotycznego w porównaniu z placebo.","quelle":"Mills EG et al. 2023, JAMA Network Open, PMID 36735255"}],"sicherheit":["W opublikowanych badaniach obejmujących łącznie ponad 1 000 uczestników do tej pory nie zgłoszono poważnych zdarzeń niepożądanych przypisywanych substancji, a profil zdarzeń niepożądanych był porównywalny z placebo.","Najczęściej opisywane efekty to łagodne, przejściowe reakcje takie jak reakcje w miejscu wstrzyknięcia, zaczerwienienie i łagodny ból głowy.","Długotrwała lub wysokoczęstotliwościowa stymulacja receptora KISS1R może prowadzić do desensytyzacji receptora i osłabienia odpowiedzi LH (tachyfilaksja).","Solidne dane dotyczące bezpieczeństwa długoterminowego nie są jeszcze dostępne, ponieważ dostępne badania dotyczą głównie krótkotrwałego, kontrolowanego podawania."],"sicherheit_en":["W opublikowanych badaniach obejmujących łącznie ponad 1 000 uczestników do tej pory nie zgłoszono poważnych zdarzeń niepożądanych przypisywanych substancji, a profil zdarzeń niepożądanych był porównywalny z placebo.","Najczęściej opisywane efekty to łagodne, przejściowe reakcje takie jak reakcje w miejscu wstrzyknięcia, zaczerwienienie i łagodny ból głowy.","Długotrwała lub wysokoczęstotliwościowa stymulacja receptora KISS1R może prowadzić do desensytyzacji receptora i osłabienia odpowiedzi LH (tachyfilaksja).","Solidne dane dotyczące bezpieczeństwa długoterminowego nie są jeszcze dostępne, ponieważ dostępne badania dotyczą głównie krótkotrwałego, kontrolowanego podawania."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Kisspeptyna-10 nie jest zatwierdzona jako lek w Niemczech, UE ani w Stanach Zjednoczonych. Jest sprzedawana wyłącznie jako odczynnik badawczy do celów laboratoryjnych; zastosowania kliniczne, takie jak wyzwalacz owulacji w IVF lub zastosowanie w hipoaktywnym zaburzeniu pożądania seksualnego, pozostają w fazie badań eksperymentalnych.","rechtsstatus_en":"Kisspeptyna-10 nie jest zatwierdzona jako lek w Niemczech, UE ani w Stanach Zjednoczonych. Jest sprzedawana wyłącznie jako odczynnik badawczy do celów laboratoryjnych; zastosowania kliniczne, takie jak wyzwalacz owulacji w IVF lub zastosowanie w hipoaktywnym zaburzeniu pożądania seksualnego, pozostają w fazie badań eksperymentalnych.","typischeMg":[5,10],"faq":[{"q":"Czy kisspeptyna-10 to to samo co kisspeptyna badana w badaniach klinicznych","a":"Nie do końca. Większość głównych badań klinicznych dotyczących płodności lub pobudzenia seksualnego wykorzystywała dłuższą, naturalną izoformę, kisspeptynę-54. Kisspeptyna-10 jest najkrótszym fragmentem o pełnej aktywności receptorowej i była badana głównie w badaniach mechanistycznych nad uwalnianiem LH u mężczyzn.","q_en":"Czy kisspeptyna-10 to to samo co kisspeptyna badana w badaniach klinicznych","a_en":"Nie do końca. Większość głównych badań klinicznych dotyczących płodności lub pobudzenia seksualnego wykorzystywała dłuższą, naturalną izoformę, kisspeptynę-54. Kisspeptyna-10 jest najkrótszym fragmentem o pełnej aktywności receptorowej i była badana głównie w badaniach mechanistycznych nad uwalnianiem LH u mężczyzn."},{"q":"Jak kisspeptyna-10 działa na organizm","a":"Wiąże się z receptorem KISS1R na neuronach GnRH w podwzgórzu i wywołuje pulsacyjne uwalnianie GnRH. To z kolei reguluje wydzielanie LH i FSH z przysadki mózgowej, a tym samym centralne funkcje osi rozrodczej.","q_en":"Jak kisspeptyna-10 działa na organizm","a_en":"Wiąże się z receptorem KISS1R na neuronach GnRH w podwzgórzu i wywołuje pulsacyjne uwalnianie GnRH. To z kolei reguluje wydzielanie LH i FSH z przysadki mózgowej, a tym samym centralne funkcje osi rozrodczej."},{"q":"Czy kisspeptyna-10 jest legalnie dostępna w Niemczech","a":"Kisspeptyna-10 nie jest zatwierdzona jako lek w Niemczech, UE ani w Stanach Zjednoczonych. Jest oferowana wyłącznie jako odczynnik badawczy do celów laboratoryjnych, nie do stosowania u ludzi.","q_en":"Czy kisspeptyna-10 jest legalnie dostępna w Niemczech","a_en":"Kisspeptyna-10 nie jest zatwierdzona jako lek w Niemczech, UE ani w Stanach Zjednoczonych. Jest oferowana wyłącznie jako odczynnik badawczy do celów laboratoryjnych, nie do stosowania u ludzi."}],"seo":{"title":"Kisspeptyna-10: peptyd badawczy dla osi hormonalnej","title_en":"Kisspeptyna-10: peptyd badawczy dla osi hormonalnej","description":"Kisspeptyna-10 przedstawiona rzeczowo: mechanizm działania na receptorze KISS1R, dane z badań nad GnRH i osią hormonalną oraz profil bezpieczeństwa peptydu badawczego.","description_en":"Kisspeptyna-10 przedstawiona rzeczowo: mechanizm działania na receptorze KISS1R, dane z badań nad GnRH i osią hormonalną oraz profil bezpieczeństwa peptydu badawczego."},"demo":false,"steckbrief":{"cas":"374675-21-5","molekulargewicht":"1302,4 g/mol","aminosaeuren":10,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":"rozpuszczalny w wodzie i buforach wodnych","sequenzLaenge":10,"quellen":["PubChem CID 25240297","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit_en":"rozpuszczalny w wodzie i buforach wodnych"},"verwandt":["pt-141","oxytocin"]},{"slug":"melanotan-2","name":"Melanotan II","synonyme":["MT-2","MT2"],"kategorie":"Sonstige","studienlage":"frühe klinische Studien","kurz":"Syntetyczny analog własnego hormonu organizmu, alfa-MSH, badany we wczesnych badaniach klinicznych dotyczących pigmentacji i funkcji seksualnej.","kurz_en":"Syntetyczny analog własnego hormonu organizmu, alfa-MSH, badany we wczesnych badaniach klinicznych dotyczących pigmentacji i funkcji seksualnej.","beschreibung":"Melanotan II to syntetyczny, cykliczny, siedmioaminokwasowy peptyd, który wiąże się z kilkoma receptorami melanokortynowymi w organizmie. Został opracowany w latach 1980. na Uniwersytecie Arizony i jest znacznie silniejszy niż jego naturalny odpowiednik, alfa-MSH. Obszary badań obejmują rolę w pigmentacji skóry, a także w pożądaniu i pobudzeniu seksualnym.","beschreibung_en":"Melanotan II to syntetyczny, cykliczny, siedmioaminokwasowy peptyd, który wiąże się z kilkoma receptorami melanokortynowymi w organizmie. Został opracowany w latach 1980. na Uniwersytecie Arizony i jest znacznie silniejszy niż jego naturalny odpowiednik, alfa-MSH. Obszary badań obejmują rolę w pigmentacji skóry, a także w pożądaniu i pobudzeniu seksualnym.","mechanismus":"Poprzez receptor MC1R na komórkach barwnikowych skóry melanotan II wywołuje produkcję eumelaniny niezależnie od ekspozycji na UV. Poprzez receptor MC4R w ośrodkowym układzie nerwowym opisuje się wpływ na pożądanie i pobudzenie seksualne oraz działanie regulujące apetyt. Ponieważ melanotan II aktywuje jednocześnie kilka receptorów w sposób nieselektywny, wzajemne oddziaływanie tych efektów jest bardziej złożone niż w przypadku bardziej selektywnych, pokrewnych związków.","mechanismus_en":"Poprzez receptor MC1R na komórkach barwnikowych skóry melanotan II wywołuje produkcję eumelaniny niezależnie od ekspozycji na UV. Poprzez receptor MC4R w ośrodkowym układzie nerwowym opisuje się wpływ na pożądanie i pobudzenie seksualne oraz działanie regulujące apetyt. Ponieważ melanotan II aktywuje jednocześnie kilka receptorów w sposób nieselektywny, wzajemne oddziaływanie tych efektów jest bardziej złożone niż w przypadku bardziej selektywnych, pokrewnych związków.","evidenz":[{"art":"kliniczne","kurz":"Pilotażowe badanie fazy 1 z udziałem trzech ochotników płci męskiej opisało wyraźną pigmentację skóry bez ekspozycji na UV po powtarzanych wstrzyknięciach podskórnych, której towarzyszyły nudności, zaczerwienienie twarzy i spontaniczne erekcje jako najczęstsze działania niepożądane.","kurz_en":"Pilotażowe badanie fazy 1 z udziałem trzech ochotników płci męskiej opisało wyraźną pigmentację skóry bez ekspozycji na UV po powtarzanych wstrzyknięciach podskórnych, której towarzyszyły nudności, zaczerwienienie twarzy i spontaniczne erekcje jako najczęstsze działania niepożądane.","quelle":"Dorr et al. 1996, Life Sciences, PMID 8637402"},{"art":"kliniczne","kurz":"Podwójnie zaślepione, kontrolowane placebo badanie krzyżowe u mężczyzn z psychogenną dysfunkcją erekcji opisało erekcję u 8 z 10 uczestników po wstrzyknięciu melanotan II, ze znacznie dłuższą sztywnością niż w grupie placebo.","kurz_en":"Podwójnie zaślepione, kontrolowane placebo badanie krzyżowe u mężczyzn z psychogenną dysfunkcją erekcji opisało erekcję u 8 z 10 uczestników po wstrzyknięciu melanotan II, ze znacznie dłuższą sztywnością niż w grupie placebo.","quelle":"Hadley et al. 1998, PMID 9679884"}],"sicherheit":["Często zgłaszane ostre działania to nudności i zaczerwienienie twarzy, przypisywane uwalnianiu histaminy.","Obserwowano łagodne wzrosty ciśnienia krwi i pulsu.","Udokumentowano stan nagły w postaci wielogodzinnej erekcji jako rzadkie, ale poważne działanie niepożądane.","Opisy przypadków dotyczą nowych lub ciemniejszych znamion (pieprzyków), najczęściej w związku z jednoczesną ekspozycją na promieniowanie UV. Związku przyczynowego z rakiem skóry nie ustalono."],"sicherheit_en":["Często zgłaszane ostre działania to nudności i zaczerwienienie twarzy, przypisywane uwalnianiu histaminy.","Obserwowano łagodne wzrosty ciśnienia krwi i pulsu.","Udokumentowano stan nagły w postaci wielogodzinnej erekcji jako rzadkie, ale poważne działanie niepożądane.","Opisy przypadków dotyczą nowych lub ciemniejszych znamion (pieprzyków), najczęściej w związku z jednoczesną ekspozycją na promieniowanie UV. Związku przyczynowego z rakiem skóry nie ustalono."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Melanotan II nie jest zatwierdzony jako lek w Niemczech, UE ani w Stanach Zjednoczonych i jest sprzedawany wyłącznie jako odczynnik badawczy. Trzy strukturalnie pokrewne leki melanokortynowe (afamelanotyd, bremelanotide, setmelanotyd) są zatwierdzone w odrębnych, konkretnych wskazaniach w Stanach Zjednoczonych i w części UE; sam melanotan II nie należy do nich.","rechtsstatus_en":"Melanotan II nie jest zatwierdzony jako lek w Niemczech, UE ani w Stanach Zjednoczonych i jest sprzedawany wyłącznie jako odczynnik badawczy. Trzy strukturalnie pokrewne leki melanokortynowe (afamelanotyd, bremelanotide, setmelanotyd) są zatwierdzone w odrębnych, konkretnych wskazaniach w Stanach Zjednoczonych i w części UE; sam melanotan II nie należy do nich.","typischeMg":[],"faq":[{"q":"Czy melanotan II jest zatwierdzony?","a":"Nie, sam melanotan II nie jest zatwierdzony w UE ani w Stanach Zjednoczonych. Jest sprzedawany wyłącznie jako odczynnik badawczy, podczas gdy trzy pokrewne związki są zatwierdzone w innych wskazaniach.","q_en":"Czy melanotan II jest zatwierdzony?","a_en":"Nie, sam melanotan II nie jest zatwierdzony w UE ani w Stanach Zjednoczonych. Jest sprzedawany wyłącznie jako odczynnik badawczy, podczas gdy trzy pokrewne związki są zatwierdzone w innych wskazaniach."},{"q":"Czy melanotan II działa tylko z promieniowaniem słonecznym?","a":"Nie. Według badań powstawanie pigmentu zachodzi niezależnie od ekspozycji na UV. Światło UV może dodatkowo wzmocnić efekt, ale nie jest do niego konieczne.","q_en":"Czy melanotan II działa tylko z promieniowaniem słonecznym?","a_en":"Nie. Według badań powstawanie pigmentu zachodzi niezależnie od ekspozycji na UV. Światło UV może dodatkowo wzmocnić efekt, ale nie jest do niego konieczne."},{"q":"Jakie działania niepożądane opisano w badaniach?","a":"Najczęściej nudności i zaczerwienienie twarzy. Rzadziej opisywano wzrost ciśnienia tętniczego, przedłużony wzwód jako nagły przypadek medyczny oraz zmiany w znamionach (pieprzykach).","q_en":"Jakie działania niepożądane opisano w badaniach?","a_en":"Najczęściej nudności i zaczerwienienie twarzy. Rzadziej opisywano wzrost ciśnienia tętniczego, przedłużony wzwód jako nagły przypadek medyczny oraz zmiany w znamionach (pieprzykach)."}],"seo":{"title":"Melanotan II: profil badawczy i dowody","title_en":"Melanotan II: profil badawczy i dowody","description":"Przegląd Melanotan II: mechanizm działania, dowody kliniczne dotyczące pigmentacji i funkcji seksualnej oraz profil bezpieczeństwa.","description_en":"Przegląd Melanotan II: mechanizm działania, dowody kliniczne dotyczące pigmentacji i funkcji seksualnej oraz profil bezpieczeństwa."},"demo":false,"steckbrief":{"cas":"121062-08-6","molekulargewicht":"1024,2 g/mol","aminosaeuren":7,"halbwertszeit":null,"reinheitsstandard":"≥ 99 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 92432","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 99 % (HPLC, standard handlowy)"},"verwandt":["ghk-cu","epitalon","pt-141","kpv"]},{"slug":"oxytocin","name":"Oksytocyna","synonyme":["OXT","Pitocin"],"kategorie":"Sonstige","studienlage":"zugelassenes Arzneimittel","kurz":"Endogenny hormon nonapeptydowy, zatwierdzony jako lek do wywoływania porodu, badany także w badaniach nad zachowaniami społecznymi i więzią.","kurz_en":"Endogenny hormon nonapeptydowy, zatwierdzony jako lek do wywoływania porodu, badany także w badaniach nad zachowaniami społecznymi i więzią.","beschreibung":"Oksytocyna to hormon złożony z dziewięciu aminokwasów, wytwarzany w podwzgórzu i uwalniany przez przysadkę mózgową. Jako lek, np. Syntocinon lub Pitocin, jest zatwierdzona do wywoływania porodu i kontroli krwawienia poporodowego. Niezależnie od tego oksytocyna podawana donosowo jest badana w badaniach podstawowych nad zachowaniem społecznym, zaufaniem i więzią.","beschreibung_en":"Oksytocyna to hormon złożony z dziewięciu aminokwasów, wytwarzany w podwzgórzu i uwalniany przez przysadkę mózgową. Jako lek, np. Syntocinon lub Pitocin, jest zatwierdzona do wywoływania porodu i kontroli krwawienia poporodowego. Niezależnie od tego oksytocyna podawana donosowo jest badana w badaniach podstawowych nad zachowaniem społecznym, zaufaniem i więzią.","mechanismus":"Oksytocyna wiąże się z receptorem oksytocyny (OXTR), receptorem sprzężonym z białkiem Gq/11, obecnym na mięśniach gładkich macicy i w różnych regionach mózgu. Związanie z receptorem aktywuje fosfolipazę C, a przez nią uwalnianie wewnątrzkomórkowego wapnia, co powoduje skurcz mięśniówki gładkiej macicy. Przy wyższych stężeniach oksytocyna działa także na strukturalnie pokrewny receptor wazopresyny V2, wywołując działanie antydiuretyczne.","mechanismus_en":"Oksytocyna wiąże się z receptorem oksytocyny (OXTR), receptorem sprzężonym z białkiem Gq/11, obecnym na mięśniach gładkich macicy i w różnych regionach mózgu. Związanie z receptorem aktywuje fosfolipazę C, a przez nią uwalnianie wewnątrzkomórkowego wapnia, co powoduje skurcz mięśniówki gładkiej macicy. Przy wyższych stężeniach oksytocyna działa także na strukturalnie pokrewny receptor wazopresyny V2, wywołując działanie antydiuretyczne.","evidenz":[{"art":"przedkliniczne","kurz":"W zwierzęcym modelu nornika preriowego (prairie vole) centralne podanie oksytocyny wywołało u samic preferencję partnera, a selektywny antagonista oksytocyny blokował jej powstanie po kojarzeniu.","kurz_en":"W zwierzęcym modelu nornika preriowego (prairie vole) centralne podanie oksytocyny wywołało u samic preferencję partnera, a selektywny antagonista oksytocyny blokował jej powstanie po kojarzeniu.","quelle":"Insel TR & Hulihan TJ 1995, Behavioral Neuroscience, 109:782-789"},{"art":"kliniczne","kurz":"W badaniu behawioralnym z placebo u zdrowych mężczyzn oksytocyna podana donosowo zwiększyła gotowość do powierzenia pieniędzy obcej osobie w grze zaufania, bez zmiany ogólnej skłonności do podejmowania ryzyka.","kurz_en":"W badaniu behawioralnym z placebo u zdrowych mężczyzn oksytocyna podana donosowo zwiększyła gotowość do powierzenia pieniędzy obcej osobie w grze zaufania, bez zmiany ogólnej skłonności do podejmowania ryzyka.","quelle":"Kosfeld M, Heinrichs M, Zak PJ, Fischbacher U, Fehr E 2005, Nature, PMID 15931222"},{"art":"kliniczne","kurz":"W randomizowanym badaniu kontrolowanym placebo z udziałem 106 dorosłych z zaburzeniami ze spektrum autyzmu sześć tygodni stosowania oksytocyny donosowo nie wykazało statystycznie istotnej poprawy w zakresie podstawowych objawów społecznych w porównaniu z placebo.","kurz_en":"W randomizowanym badaniu kontrolowanym placebo z udziałem 106 dorosłych z zaburzeniami ze spektrum autyzmu sześć tygodni stosowania oksytocyny donosowo nie wykazało statystycznie istotnej poprawy w zakresie podstawowych objawów społecznych w porównaniu z placebo.","quelle":"Yamasue H et al. 2020, Molecular Psychiatry, PMID 29955161"},{"art":"przedkliniczne","kurz":"Przegląd z zakresu farmakologii receptorów opisuje sprzężenie receptora oksytocyny ze szlakami sygnałowymi zależnymi od białka Gq/11, takimi jak fosfolipaza C i kinaza białkowa C, w modelach komórkowych i zwierzęcych.","kurz_en":"Przegląd z zakresu farmakologii receptorów opisuje sprzężenie receptora oksytocyny ze szlakami sygnałowymi zależnymi od białka Gq/11, takimi jak fosfolipaza C i kinaza białkowa C, w modelach komórkowych i zwierzęcych.","quelle":"Jurek B & Neumann ID 2018, Physiological Reviews, PMID 29897293"}],"sicherheit":["Przy podaniu dożylnym w połączeniu z dużymi objętościami płynów pozbawionych elektrolitów udokumentowano zatrucie wodne z hiponatremią, wynikające z działania antydiuretycznego oksytocyny, związanego z jej strukturalnym podobieństwem do wazopresyny.","Powszechnie cytowane badanie dotyczące wzmacniającego zaufanie działania oksytocyny podawanej donosowo nie zostało potwierdzone w późniejszym badaniu replikacyjnym w identycznych warunkach eksperymentalnych.","W największym dotychczasowym randomizowanym badaniu oksytocyny donosowej w zaburzeniach ze spektrum autyzmu nie zaobserwowano istotnego wpływu na podstawowe objawy.","Dla zastosowań poza zatwierdzonym wskazaniem położniczym nie są dostępne solidne dane dotyczące długoterminowego bezpieczeństwa."],"sicherheit_en":["Przy podaniu dożylnym w połączeniu z dużymi objętościami płynów pozbawionych elektrolitów udokumentowano zatrucie wodne z hiponatremią, wynikające z działania antydiuretycznego oksytocyny, związanego z jej strukturalnym podobieństwem do wazopresyny.","Powszechnie cytowane badanie dotyczące wzmacniającego zaufanie działania oksytocyny podawanej donosowo nie zostało potwierdzone w późniejszym badaniu replikacyjnym w identycznych warunkach eksperymentalnych.","W największym dotychczasowym randomizowanym badaniu oksytocyny donosowej w zaburzeniach ze spektrum autyzmu nie zaobserwowano istotnego wpływu na podstawowe objawy.","Dla zastosowań poza zatwierdzonym wskazaniem położniczym nie są dostępne solidne dane dotyczące długoterminowego bezpieczeństwa."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Oksytocyna jest zatwierdzona jako lek, np. Syntocinon lub Pitocin, w Niemczech, UE i Stanach Zjednoczonych do wywoływania porodu i leczenia krwotoku poporodowego i do tego zastosowania jest dostępna wyłącznie na receptę. W innych, niezatwierdzonych zagadnieniach badawczych, takich jak zachowania społeczne czy więź, jest osobno sprzedawana jako odczynnik badawczy.","rechtsstatus_en":"Oksytocyna jest zatwierdzona jako lek, np. Syntocinon lub Pitocin, w Niemczech, UE i Stanach Zjednoczonych do wywoływania porodu i leczenia krwotoku poporodowego i do tego zastosowania jest dostępna wyłącznie na receptę. W innych, niezatwierdzonych zagadnieniach badawczych, takich jak zachowania społeczne czy więź, jest osobno sprzedawana jako odczynnik badawczy.","typischeMg":[],"faq":[{"q":"Czy oksytocyna jest zatwierdzonym lekiem, czy odczynnikiem badawczym","a":"Jedno i drugie, w zależności od zastosowania. W indukcji porodu i krwotoku poporodowym oksytocyna jest lekiem na receptę. W innych zagadnieniach badawczych, takich jak zachowania społeczne, jest osobno sprzedawana jako odczynnik badawczy, bez zatwierdzenia do tego celu.","q_en":"Czy oksytocyna jest zatwierdzonym lekiem, czy odczynnikiem badawczym","a_en":"Jedno i drugie, w zależności od zastosowania. W indukcji porodu i krwotoku poporodowym oksytocyna jest lekiem na receptę. W innych zagadnieniach badawczych, takich jak zachowania społeczne, jest osobno sprzedawana jako odczynnik badawczy, bez zatwierdzenia do tego celu."},{"q":"W jakim celu bada się oksytocynę w badaniach nad zachowaniami społecznymi","a":"Badania dotyczą oksytocyny podawanej donosowo w kontekście zaufania, więzi i percepcji społecznej. Wyniki są niejednoznaczne, a szeroko cytowanego wczesnego badania nad zaufaniem nie udało się potwierdzić w replikacji.","q_en":"W jakim celu bada się oksytocynę w badaniach nad zachowaniami społecznymi","a_en":"Badania dotyczą oksytocyny podawanej donosowo w kontekście zaufania, więzi i percepcji społecznej. Wyniki są niejednoznaczne, a szeroko cytowanego wczesnego badania nad zaufaniem nie udało się potwierdzić w replikacji."},{"q":"Czy oksytocyna działa w zaburzeniach ze spektrum autyzmu","a":"Największe dotychczas randomizowane badanie u dorosłych z zaburzeniami ze spektrum autyzmu nie wykazało istotnego wpływu oksytocyny podawanej donosowo na podstawowe objawy społeczne w porównaniu z placebo.","q_en":"Czy oksytocyna działa w zaburzeniach ze spektrum autyzmu","a_en":"Największe dotychczas randomizowane badanie u dorosłych z zaburzeniami ze spektrum autyzmu nie wykazało istotnego wpływu oksytocyny podawanej donosowo na podstawowe objawy społeczne w porównaniu z placebo."}],"seo":{"title":"Oksytocyna: hormon, lek i peptyd badawczy","title_en":"Oksytocyna: hormon, lek i peptyd badawczy","description":"Oksytocyna przedstawiona rzeczowo: zatwierdzone wskazanie, mechanizm działania, badania nad zachowaniami społecznymi i status prawny jako odczynnika badawczego.","description_en":"Oksytocyna przedstawiona rzeczowo: zatwierdzone wskazanie, mechanizm działania, badania nad zachowaniami społecznymi i status prawny jako odczynnika badawczego."},"demo":false,"steckbrief":{"cas":"50-56-6","molekulargewicht":"1007,2 g/mol","aminosaeuren":9,"halbwertszeit":"≈ 1 do 6 minut (okres półtrwania w osoczu, charakterystyka produktu Pitocin)","reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":9,"quellen":["PubChem CID 439302","DailyMed SPL PITOCIN (Oxytocin), Par Health USA","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 1 do 6 minut (okres półtrwania w osoczu, charakterystyka produktu Pitocin)","reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)"},"verwandt":["kisspeptin","pt-141","dsip"]},{"slug":"pt-141","name":"PT-141 (bremelanotide)","synonyme":["Bremelanotide","Vyleesi"],"kategorie":"Sonstige","studienlage":"zugelassenes Arzneimittel","kurz":"Syntetyczny heptapeptyd i agonista receptorów melanokortynowych, zatwierdzony w USA pod nazwą Vyleesi w określonej postaci niskiego popędu seksualnego u kobiet.","kurz_en":"Syntetyczny heptapeptyd i agonista receptorów melanokortynowych, zatwierdzony w USA pod nazwą Vyleesi w określonej postaci niskiego popędu seksualnego u kobiet.","beschreibung":"PT-141 (bremelanotide) to siedmioaminokwasowy peptyd opracowany w Palatin Technologies jako związek następczy po melanotan II. W przeciwieństwie do melanotan II, który badano głównie pod kątem pigmentacji skóry, badania nad bremelanotide koncentrowały się na centralnej regulacji pożądania seksualnego. Od 2019 roku związek jest zatwierdzony w USA pod nazwą Vyleesi we wskazaniu hipoaktywnego zaburzenia pożądania seksualnego (HSDD) u kobiet przed menopauzą.","beschreibung_en":"PT-141 (bremelanotide) to siedmioaminokwasowy peptyd opracowany w Palatin Technologies jako związek następczy po melanotan II. W przeciwieństwie do melanotan II, który badano głównie pod kątem pigmentacji skóry, badania nad bremelanotide koncentrowały się na centralnej regulacji pożądania seksualnego. Od 2019 roku związek jest zatwierdzony w USA pod nazwą Vyleesi we wskazaniu hipoaktywnego zaburzenia pożądania seksualnego (HSDD) u kobiet przed menopauzą.","mechanismus":"Bremelanotide działa jako agonista receptorów melanokortynowych, głównie podtypu MC4R skoncentrowanego w przyśrodkowym polu przedwzrokowym podwzgórza. Badania przedkliniczne opisują uwalnianie dopaminy wywoływane przez ten receptor w obszarach mózgu zaangażowanych w pobudzenie seksualne. Miejsce działania jest zatem ośrodkowe, w mózgu, a nie naczyniowe, jak w przypadku inhibitorów PDE5. Zgodnie z oznakowaniem produktu zatwierdzonym przez FDA dokładny mechanizm poprawy objawów HSDD nie został w pełni ustalony.","mechanismus_en":"Bremelanotide działa jako agonista receptorów melanokortynowych, głównie podtypu MC4R skoncentrowanego w przyśrodkowym polu przedwzrokowym podwzgórza. Badania przedkliniczne opisują uwalnianie dopaminy wywoływane przez ten receptor w obszarach mózgu zaangażowanych w pobudzenie seksualne. Miejsce działania jest zatem ośrodkowe, w mózgu, a nie naczyniowe, jak w przypadku inhibitorów PDE5. Zgodnie z oznakowaniem produktu zatwierdzonym przez FDA dokładny mechanizm poprawy objawów HSDD nie został w pełni ustalony.","evidenz":[{"art":"przedkliniczne","kurz":"Badania na samicach szczurów wykazały nasilone zachowania zachęcające do kontaktu seksualnego po podaniu bremelanotide, zależne od uwalniania dopaminy po aktywacji receptorów MC4 w przyśrodkowym polu przedwzrokowym podwzgórza.","kurz_en":"Badania na samicach szczurów wykazały nasilone zachowania zachęcające do kontaktu seksualnego po podaniu bremelanotide, zależne od uwalniania dopaminy po aktywacji receptorów MC4 w przyśrodkowym polu przedwzrokowym podwzgórza.","quelle":"Pfaus JG et al. 2007, The Journal of Sexual Medicine, PMID 17958619"},{"art":"kliniczne","kurz":"W dwóch randomizowanych, kontrolowanych placebo badaniach fazy 3 (RECONNECT) u kobiet przed menopauzą z HSDD bremelanotide poprawiał pożądanie seksualne i związane z nim cierpienie bardziej niż placebo.","kurz_en":"W dwóch randomizowanych, kontrolowanych placebo badaniach fazy 3 (RECONNECT) u kobiet przed menopauzą z HSDD bremelanotide poprawiał pożądanie seksualne i związane z nim cierpienie bardziej niż placebo.","quelle":"Kingsberg SA, Clayton AH, Portman D et al. 2019, Obstetrics & Gynecology, PMID 31599840"},{"art":"kliniczne","kurz":"Analiza zbiorcza 43 badań klinicznych z udziałem około 3 500 uczestników udokumentowała nudności, zaczerwienienie twarzy, ból głowy i przejściowy wzrost ciśnienia krwi jako najczęstsze działania niepożądane bremelanotide.","kurz_en":"Analiza zbiorcza 43 badań klinicznych z udziałem około 3 500 uczestników udokumentowała nudności, zaczerwienienie twarzy, ból głowy i przejściowy wzrost ciśnienia krwi jako najczęstsze działania niepożądane bremelanotide.","quelle":"Clayton AH et al. 2022, Journal of Women's Health, PMID 35147466"}],"sicherheit":["W badaniach klinicznych nudności wystąpiły u około 40 procent uczestników przyjmujących bremelanotide, w porównaniu z około 1 procentem w grupie placebo.","Obserwowano przejściowy wzrost ciśnienia krwi i spadek częstości akcji serca po każdym podaniu, ustępujące w ciągu około 12 godzin zgodnie z oznakowaniem produktu zatwierdzonym przez FDA.","Zgodnie z oznakowaniem produktu zatwierdzonym przez FDA Vyleesi jest przeciwwskazany przy niekontrolowanym nadciśnieniu tętniczym lub rozpoznanej chorobie układu sercowo-naczyniowego.","W badaniach RECONNECT u około 1 procenta uczestników zaobserwowano ogniskową hiperpigmentację skóry."],"sicherheit_en":["W badaniach klinicznych nudności wystąpiły u około 40 procent uczestników przyjmujących bremelanotide, w porównaniu z około 1 procentem w grupie placebo.","Obserwowano przejściowy wzrost ciśnienia krwi i spadek częstości akcji serca po każdym podaniu, ustępujące w ciągu około 12 godzin zgodnie z oznakowaniem produktu zatwierdzonym przez FDA.","Zgodnie z oznakowaniem produktu zatwierdzonym przez FDA Vyleesi jest przeciwwskazany przy niekontrolowanym nadciśnieniu tętniczym lub rozpoznanej chorobie układu sercowo-naczyniowego.","W badaniach RECONNECT u około 1 procenta uczestników zaobserwowano ogniskową hiperpigmentację skóry."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"Bremelanotide jest zatwierdzony przez FDA jako Vyleesi od 2019 roku we wskazaniu HSDD u kobiet przed menopauzą. W Niemczech i UE nie istnieje zatwierdzenie leku, a substancja jest tam sprzedawana wyłącznie jako odczynnik badawczy.","rechtsstatus_en":"Bremelanotide jest zatwierdzony przez FDA jako Vyleesi od 2019 roku we wskazaniu HSDD u kobiet przed menopauzą. W Niemczech i UE nie istnieje zatwierdzenie leku, a substancja jest tam sprzedawana wyłącznie jako odczynnik badawczy.","typischeMg":[10,20],"faq":[{"q":"Czy PT-141 to to samo co melanotan II","a":"Nie. Oba wywodzą się z pokrewnych struktur melanokortynowych, ale PT-141 (bremelanotide) był badany specjalnie pod kątem pożądania seksualnego, a melanotan II głównie pod kątem pigmentacji skóry. Tylko bremelanotide uzyskał w USA dopuszczenie do obrotu, jako Vyleesi.","q_en":"Czy PT-141 to to samo co melanotan II","a_en":"Nie. Oba wywodzą się z pokrewnych struktur melanokortynowych, ale PT-141 (bremelanotide) był badany specjalnie pod kątem pożądania seksualnego, a melanotan II głównie pod kątem pigmentacji skóry. Tylko bremelanotide uzyskał w USA dopuszczenie do obrotu, jako Vyleesi."},{"q":"Czy bremelanotide jest zatwierdzonym lekiem","a":"W USA tak: od 2019 roku bremelanotide jest zatwierdzony pod nazwą Vyleesi we wskazaniu HSDD u kobiet przed menopauzą. W Niemczech i UE nie istnieje zatwierdzenie leku, a substancja jest tam klasyfikowana jako odczynnik badawczy.","q_en":"Czy bremelanotide jest zatwierdzonym lekiem","a_en":"W USA tak: od 2019 roku bremelanotide jest zatwierdzony pod nazwą Vyleesi we wskazaniu HSDD u kobiet przed menopauzą. W Niemczech i UE nie istnieje zatwierdzenie leku, a substancja jest tam klasyfikowana jako odczynnik badawczy."},{"q":"Jakie działania niepożądane zaobserwowano w badaniach","a":"Najczęściej udokumentowanymi działaniami były nudności, zaczerwienienie twarzy, ból głowy i przejściowy wzrost ciśnienia krwi po podaniu. Zgodnie z oznakowaniem produktu zatwierdzonym przez FDA substancja jest przeciwwskazana przy niekontrolowanym nadciśnieniu tętniczym lub rozpoznanej chorobie układu sercowo-naczyniowego.","q_en":"Jakie działania niepożądane zaobserwowano w badaniach","a_en":"Najczęściej udokumentowanymi działaniami były nudności, zaczerwienienie twarzy, ból głowy i przejściowy wzrost ciśnienia krwi po podaniu. Zgodnie z oznakowaniem produktu zatwierdzonym przez FDA substancja jest przeciwwskazana przy niekontrolowanym nadciśnieniu tętniczym lub rozpoznanej chorobie układu sercowo-naczyniowego."}],"seo":{"title":"Przegląd badań: PT-141 (bremelanotide)","title_en":"Przegląd badań: PT-141 (bremelanotide)","description":"PT-141 (bremelanotide): mechanizm, dane z badań, profil bezpieczeństwa i status zatwierdzenia tego agonisty receptorów melanokortynowych w pigułce.","description_en":"PT-141 (bremelanotide): mechanizm, dane z badań, profil bezpieczeństwa i status zatwierdzenia tego agonisty receptorów melanokortynowych w pigułce."},"demo":false,"steckbrief":{"cas":"189691-06-3","molekulargewicht":"1025,2 g/mol","aminosaeuren":7,"halbwertszeit":"≈ 2,7 godziny (wartość półtrwania terminalnego, informacje o stosowaniu Vyleesi)","reinheitsstandard":"≥ 99 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":7,"quellen":["PubChem CID 9941379","DailyMed SPL VYLEESI (Bremelanotid), Cosette Pharmaceuticals","chemverify Katalog 14.09.2026"],"halbwertszeit_en":"≈ 2,7 godziny (wartość półtrwania terminalnego, informacje o stosowaniu Vyleesi)","reinheitsstandard_en":"≥ 99 % (HPLC, standard handlowy)"},"verwandt":["melanotan-2","kisspeptin","kpv"]},{"slug":"ss-31","name":"SS-31 (elamipretide)","synonyme":["Elamipretide","MTP-131","Bendavia"],"kategorie":"Sonstige","studienlage":"klinisch untersucht","kurz":"Tetrapeptyd ukierunkowany na mitochondria, badany w kilku badaniach klinicznych pod kątem niewydolności serca i choroby mitochondrialnej, jeszcze nie zatwierdzony.","kurz_en":"Tetrapeptyd ukierunkowany na mitochondria, badany w kilku badaniach klinicznych pod kątem niewydolności serca i choroby mitochondrialnej, jeszcze nie zatwierdzony.","beschreibung":"SS-31, znany również pod nazwą międzynarodową (INN) elamipretide, jako MTP-131 lub Bendavia, jest syntetycznym tetrapeptydem, który specyficznie wiąże się z kardiolipiną, lipidem błony mitochondrialnej. Był badany w kilku badaniach klinicznych fazy 1-3 w niewydolności serca, pierwotnej miopatii mitochondrialnej i zespole Bartha. Mimo stosunkowo szerokiej bazy danych klinicznych żadne z tych badań nie doprowadziło dotąd do zatwierdzenia jako lek.","beschreibung_en":"SS-31, znany również pod nazwą międzynarodową (INN) elamipretide, jako MTP-131 lub Bendavia, jest syntetycznym tetrapeptydem, który specyficznie wiąże się z kardiolipiną, lipidem błony mitochondrialnej. Był badany w kilku badaniach klinicznych fazy 1-3 w niewydolności serca, pierwotnej miopatii mitochondrialnej i zespole Bartha. Mimo stosunkowo szerokiej bazy danych klinicznych żadne z tych badań nie doprowadziło dotąd do zatwierdzenia jako lek.","mechanismus":"SS-31 wiąże się z wysokim powinowactwem z kardiolipiną w wewnętrznej błonie mitochondrialnej, lipidem niezbędnym dla struktury krist. Opisuje się to jako zmniejszanie ilości reaktywnych form tlenu i stabilizację struktury błony mitochondrialnej. W modelach przedklinicznych wiązano to z ochroną przed uszkodzeniem niedokrwienno-reperfuzyjnym, na przykład w mięśniu sercowym.","mechanismus_en":"SS-31 wiąże się z wysokim powinowactwem z kardiolipiną w wewnętrznej błonie mitochondrialnej, lipidem niezbędnym dla struktury krist. Opisuje się to jako zmniejszanie ilości reaktywnych form tlenu i stabilizację struktury błony mitochondrialnej. W modelach przedklinicznych wiązano to z ochroną przed uszkodzeniem niedokrwienno-reperfuzyjnym, na przykład w mięśniu sercowym.","evidenz":[{"art":"kliniczne","kurz":"Randomizowane, kontrolowane placebo badanie fazy 3 u osób z pierwotną miopatią mitochondrialną nie osiągnęło wcześniej zdefiniowanych pierwszorzędowych punktów końcowych ani w teście 6-minutowego marszu, ani w skali zmęczenia, chociaż badany lek opisano jako dobrze tolerowany.","kurz_en":"Randomizowane, kontrolowane placebo badanie fazy 3 u osób z pierwotną miopatią mitochondrialną nie osiągnęło wcześniej zdefiniowanych pierwszorzędowych punktów końcowych ani w teście 6-minutowego marszu, ani w skali zmęczenia, chociaż badany lek opisano jako dobrze tolerowany.","quelle":"Karaa et al. 2023, Neurology, PMID 37268435"},{"art":"kliniczne","kurz":"Kontrolowane placebo badanie fazy 1 ze stopniowo zwiększanymi ilościami wlewu u osób z niewydolnością serca i zmniejszoną frakcją wyrzutową opisało pojedynczy wlew elamipretide jako bezpieczny i dobrze tolerowany.","kurz_en":"Kontrolowane placebo badanie fazy 1 ze stopniowo zwiększanymi ilościami wlewu u osób z niewydolnością serca i zmniejszoną frakcją wyrzutową opisało pojedynczy wlew elamipretide jako bezpieczny i dobrze tolerowany.","quelle":"Daubert et al. 2017, Circulation: Heart Failure, PMID 29217757"},{"art":"przedkliniczne","kurz":"Badanie na szczurach z uszkodzeniem niedokrwienno-reperfuzyjnym serca opisało znacznie mniejszy obszar zawału, gdy SS-31 podano wcześniej, w porównaniu ze zwierzętami kontrolnymi.","kurz_en":"Badanie na szczurach z uszkodzeniem niedokrwienno-reperfuzyjnym serca opisało znacznie mniejszy obszar zawału, gdy SS-31 podano wcześniej, w porównaniu ze zwierzętami kontrolnymi.","quelle":"Cho et al. 2007, Coronary Artery Disease, PMID 17429296"}],"sicherheit":["W dotychczasowych badaniach klinicznych elamipretide opisywano w większości jako bezpieczny i dobrze tolerowany, z przeważnie łagodnymi do umiarkowanych zdarzeniami niepożądanymi.","Kilka badań, w tym w miopatii mitochondrialnej i zespole Bartha, nie osiągnęło pierwszorzędowych punktów końcowych dotyczących skuteczności, dlatego wniosek o zatwierdzenie w USA nie został w 2021 roku przyjęty przez agencję do rozpatrzenia.","Dane długoterminowe poza programami badań kontrolowanych nie są dostępne.","Produkty z niekontrolowanej produkcji niosą ryzyko zanieczyszczenia niezależne od samej cząsteczki."],"sicherheit_en":["W dotychczasowych badaniach klinicznych elamipretide opisywano w większości jako bezpieczny i dobrze tolerowany, z przeważnie łagodnymi do umiarkowanych zdarzeniami niepożądanymi.","Kilka badań, w tym w miopatii mitochondrialnej i zespole Bartha, nie osiągnęło pierwszorzędowych punktów końcowych dotyczących skuteczności, dlatego wniosek o zatwierdzenie w USA nie został w 2021 roku przyjęty przez agencję do rozpatrzenia.","Dane długoterminowe poza programami badań kontrolowanych nie są dostępne.","Produkty z niekontrolowanej produkcji niosą ryzyko zanieczyszczenia niezależne od samej cząsteczki."],"hinweise":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"hinweise_en":["Wyłącznie do celów badawczych, nie do stosowania u ludzi","Certyfikat analizy nie dowodzi przydatności medycznej"],"rekonstitution":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rekonstitution_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","lagerung_en":"Warunki specyficzne dla produktu znajdują się w oryginalnej dokumentacji producenta. Ten portal nie zawiera instrukcji przygotowania ani stosowania u ludzi.","rechtsstatus":"SS-31 (elamipretide) nie jest zatwierdzony jako lek w Niemczech, UE ani w Stanach Zjednoczonych. Wniosek o zatwierdzenie w USA z 2021 roku nie został przyjęty do rozpatrzenia z powodu braku choćby jednego odpowiedniego, dobrze kontrolowanego badania skuteczności. Jest sprzedawany wyłącznie jako odczynnik badawczy.","rechtsstatus_en":"SS-31 (elamipretide) nie jest zatwierdzony jako lek w Niemczech, UE ani w Stanach Zjednoczonych. Wniosek o zatwierdzenie w USA z 2021 roku nie został przyjęty do rozpatrzenia z powodu braku choćby jednego odpowiedniego, dobrze kontrolowanego badania skuteczności. Jest sprzedawany wyłącznie jako odczynnik badawczy.","typischeMg":[],"faq":[{"q":"Czy elamipretide jest zatwierdzonym lekiem?","a":"Nie. Mimo kilku badań klinicznych w niewydolności serca, miopatii mitochondrialnej i zespole Bartha nie przyznano zatwierdzenia; wniosek o rejestrację w USA nie został w 2021 roku przyjęty do rozpatrzenia.","q_en":"Czy elamipretide jest zatwierdzonym lekiem?","a_en":"Nie. Mimo kilku badań klinicznych w niewydolności serca, miopatii mitochondrialnej i zespole Bartha nie przyznano zatwierdzenia; wniosek o rejestrację w USA nie został w 2021 roku przyjęty do rozpatrzenia."},{"q":"Jaki jest cel działania SS-31 w organizmie?","a":"Wiąże się z kardiolipiną w wewnętrznej błonie mitochondrialnej i jest powiązany ze zmniejszeniem ilości reaktywnych form tlenu oraz stabilizacją struktury błony.","q_en":"Jaki jest cel działania SS-31 w organizmie?","a_en":"Wiąże się z kardiolipiną w wewnętrznej błonie mitochondrialnej i jest powiązany ze zmniejszeniem ilości reaktywnych form tlenu oraz stabilizacją struktury błony."},{"q":"Czy badania kliniczne osiągnęły swoje cele?","a":"Kilka badań nie osiągnęło wcześniej zdefiniowanych pierwszorzędowych punktów końcowych dotyczących skuteczności, na przykład w miopatii mitochondrialnej i zespole Bartha, przy czym tolerancję konsekwentnie opisywano jako dobrą.","q_en":"Czy badania kliniczne osiągnęły swoje cele?","a_en":"Kilka badań nie osiągnęło wcześniej zdefiniowanych pierwszorzędowych punktów końcowych dotyczących skuteczności, na przykład w miopatii mitochondrialnej i zespole Bartha, przy czym tolerancję konsekwentnie opisywano jako dobrą."}],"seo":{"title":"SS-31 (elamipretide): profil badawczy i dowody","title_en":"SS-31 (elamipretide): profil badawczy i dowody","description":"Przegląd SS-31/elamipretidu: mechanizm mitochondrialny, dowody kliniczne w niewydolności serca i miopatii mitochondrialnej oraz profil bezpieczeństwa.","description_en":"Przegląd SS-31/elamipretidu: mechanizm mitochondrialny, dowody kliniczne w niewydolności serca i miopatii mitochondrialnej oraz profil bezpieczeństwa."},"demo":false,"steckbrief":{"cas":"736992-21-5","molekulargewicht":"639,8 g/mol","aminosaeuren":4,"halbwertszeit":null,"reinheitsstandard":"≥ 98 % (HPLC, standard handlowy)","loeslichkeit":null,"sequenzLaenge":4,"quellen":["PubChem CID 11764719","chemverify Katalog 14.09.2026"],"reinheitsstandard_en":"≥ 98 % (HPLC, standard handlowy)"},"verwandt":["mots-c","epitalon","dihexa"]}];
